-- 20261024000301_index_rate_limits_window_start.sql
-- =============================================================================
-- Lets the rate-limit cleanup find old windows quickly. One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists rate_limits_window_start_idx on private.rate_limits (window_start);

-- =============================================================================
-- 20261024000302_rate_limits_deny_policy.sql
-- =============================================================================
-- Says out loud what RLS already does by default: browser roles can never touch
-- rate limit rows. Only the SECURITY DEFINER check_rate_limit function writes them.
create policy "No browser access to rate limits"
  on private.rate_limits as restrictive for all
  to anon, authenticated
  using (false)
  with check (false);

-- =============================================================================
-- 20261024000400_library_items_logs.sql
-- =============================================================================
-- The brief's library and logs.
--
-- Design problem: libraries are private, but logs are public on a book's page.
-- library_items has owner-only policies. logs has its own public read policy
-- and carries just enough to show a log (book id, author's display name, date),
-- so listing every log for a book never reads anyone's library.
-- A log can exist only for a book in its author's library: a composite foreign
-- key to library_items(user_id, volume_id) enforces it, and removing the book
-- deletes its logs (on delete cascade).

create type public.reading_status as enum ('want_to_read', 'reading', 'finished');

create table public.library_items (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  -- Google Books volume id, checked against the format the API uses.
  volume_id  text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  status     public.reading_status not null default 'want_to_read',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Also the index for user_id (RLS) and the target of logs' foreign key.
  unique (user_id, volume_id)
);

create trigger library_items_set_updated_at
  before update on public.library_items
  for each row execute function public.set_updated_at();

alter table public.library_items enable row level security;

create policy "Readers see their own library"
  on public.library_items for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers add to their own library"
  on public.library_items for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Readers change status in their own library"
  on public.library_items for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Readers remove books from their own library"
  on public.library_items for delete
  to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.library_items from anon, authenticated;
grant select, delete on public.library_items to authenticated;
grant insert (user_id, volume_id, status) on public.library_items to authenticated;
grant update (status) on public.library_items to authenticated;


create table public.logs (
  id         uuid primary key default gen_random_uuid(),
  -- References profiles so the book page can embed the display name.
  user_id    uuid not null references public.profiles (id) on delete cascade,
  volume_id  text not null,
  body       text not null check (char_length(btrim(body)) between 1 and 5000),
  rating     smallint check (rating between 1 and 5),   -- optional
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (user_id, volume_id)
    references public.library_items (user_id, volume_id) on delete cascade
);
-- Indexes for the book page (volume_id, newest first) and the foreign key
-- (user_id, volume_id) are in the 0401/0402 migrations.

create trigger logs_set_updated_at
  before update on public.logs
  for each row execute function public.set_updated_at();

alter table public.logs enable row level security;

create policy "Logs are public"
  on public.logs for select
  to anon, authenticated
  using (true);

-- The foreign key does the "book is in my library" check; the policy makes
-- sure the library is the writer's own.
create policy "Readers write their own logs"
  on public.logs for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Readers edit their own logs"
  on public.logs for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Readers delete their own logs"
  on public.logs for delete
  to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.logs from anon, authenticated;
grant select on public.logs to anon, authenticated;
grant insert (user_id, volume_id, body, rating) on public.logs to authenticated;
grant update (body, rating) on public.logs to authenticated;
grant delete on public.logs to authenticated;

-- =============================================================================
-- 20261024000401_index_logs_volume_id.sql
-- =============================================================================
-- Book page: every log for a volume, newest first. One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists logs_volume_id_created_at_idx on public.logs (volume_id, created_at desc);

-- =============================================================================
-- 20261024000402_index_logs_user_id_volume_id.sql
-- =============================================================================
-- Composite foreign key to library_items and the user's own logs (RLS). One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists logs_user_id_volume_id_idx on public.logs (user_id, volume_id);

-- =============================================================================
-- 20261024000500_reading_progress_bookmarks.sql
-- =============================================================================
-- Reading progress and bookmarks (Phase 7: the reader and the audiobook player).
--
-- Both are private to the account, like library_items, and belong to a book in
-- the account's library: a composite foreign key to library_items(user_id,
-- volume_id) enforces it, and removing the book deletes its progress and
-- bookmarks (on delete cascade). Opening a book in the reader or player adds it
-- to the library as "reading" first.

create type public.book_format as enum ('ebook', 'audiobook');

-- Where the account stopped in each book: one row per book, for Continue Reading.
create table public.reading_progress (
  user_id       uuid not null,
  volume_id     text not null,
  -- The format last used, so Continue Reading reopens the reader or the player.
  format        public.book_format not null,
  chapter_index smallint not null check (chapter_index between 0 and 999),
  -- How far through the whole book, 0 to 1 (pages for ebooks, time for audiobooks).
  position      numeric(5, 4) not null check (position between 0 and 1),
  finished      boolean not null default false,
  updated_at    timestamptz not null default now(),
  -- Also the index for the foreign key and for RLS (user_id first).
  primary key (user_id, volume_id),
  foreign key (user_id, volume_id)
    references public.library_items (user_id, volume_id) on delete cascade
);

create trigger reading_progress_set_updated_at
  before update on public.reading_progress
  for each row execute function public.set_updated_at();

alter table public.reading_progress enable row level security;

create policy "Readers see their own progress"
  on public.reading_progress for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers save their own progress"
  on public.reading_progress for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Readers update their own progress"
  on public.reading_progress for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Readers clear their own progress"
  on public.reading_progress for delete
  to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.reading_progress from anon, authenticated;
grant select, delete on public.reading_progress to authenticated;
grant insert (user_id, volume_id, format, chapter_index, position, finished) on public.reading_progress to authenticated;
grant update (format, chapter_index, position, finished) on public.reading_progress to authenticated;


-- Bookmarks: a named place in a book, in either format.
create table public.bookmarks (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null,
  volume_id     text not null,
  format        public.book_format not null,
  chapter_index smallint not null check (chapter_index between 0 and 999),
  position      numeric(5, 4) not null check (position between 0 and 1),
  label         text not null check (char_length(btrim(label)) between 1 and 120),
  created_at    timestamptz not null default now(),
  foreign key (user_id, volume_id)
    references public.library_items (user_id, volume_id) on delete cascade
);
-- The foreign key's index (user_id, volume_id) is in the 0501 migration.

alter table public.bookmarks enable row level security;

create policy "Readers see their own bookmarks"
  on public.bookmarks for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers add their own bookmarks"
  on public.bookmarks for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Readers remove their own bookmarks"
  on public.bookmarks for delete
  to authenticated
  using (user_id = (select auth.uid()));

-- Bookmarks are added and removed, never edited.
revoke all on public.bookmarks from anon, authenticated;
grant select, delete on public.bookmarks to authenticated;
grant insert (user_id, volume_id, format, chapter_index, position, label) on public.bookmarks to authenticated;

-- =============================================================================
-- 20261024000501_index_bookmarks_user_id_volume_id.sql
-- =============================================================================
-- Bookmarks' foreign key to library_items, and the reader's "bookmarks in this book" list. One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists bookmarks_user_id_volume_id_idx on public.bookmarks (user_id, volume_id);

-- =============================================================================
-- 20261024000600_profile_age_rating.sql
-- =============================================================================
-- Phase 8: changing a profile's age rating after it was created.
--
-- The browser can't set age_rating on an existing profile (no column grant), so
-- the manage-profile Edge Function calls this after re-checking the account
-- password. Moving a profile to Kids records the parent's consent, as
-- create_kids_profile does; moving it off Kids marks that consent withdrawn
-- (the record itself is kept for as long as the law requires).

create or replace function public.set_profile_age_rating(
  p_account_id uuid, p_profile_id uuid, p_age_rating public.age_rating, p_notice_version text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_rating public.age_rating;
begin
  select age_rating into current_rating from public.reader_profiles
  where id = p_profile_id and account_id = p_account_id
  for update;

  if not found then
    raise exception 'Profile not found' using errcode = 'no_data_found';
  end if;
  if current_rating = p_age_rating then
    return;
  end if;

  if p_age_rating = 'kids' then
    if p_notice_version is null or char_length(p_notice_version) not between 1 and 40 then
      raise exception 'A Kids profile needs the parent''s consent' using errcode = 'check_violation';
    end if;
    update public.reader_profiles
    set age_rating = 'kids', kids_consent_at = now()
    where id = p_profile_id;
    insert into public.parental_consents (account_id, profile_id, notice_version)
    values (p_account_id, p_profile_id, p_notice_version);
  else
    update public.reader_profiles
    set age_rating = p_age_rating, kids_consent_at = null
    where id = p_profile_id;
    update public.parental_consents
    set withdrawn_at = now()
    where profile_id = p_profile_id and account_id = p_account_id and withdrawn_at is null;
  end if;
end;
$$;

revoke execute on function public.set_profile_age_rating(uuid, uuid, public.age_rating, text) from public, anon, authenticated;
grant execute on function public.set_profile_age_rating(uuid, uuid, public.age_rating, text) to service_role;

-- =============================================================================
-- 20261025000700_highlights.sql
-- =============================================================================
-- Highlights and notes (Phase 9: the reader's study tools).
--
-- A highlight marks a passage on one page of the ebook reader, in one of four
-- colours, and may carry a note. Like bookmarks they are private to the account
-- and belong to a book in its library: the composite foreign key to
-- library_items(user_id, volume_id) enforces it, and removing the book deletes
-- its highlights (on delete cascade).
--
-- The passage is found again by its page (chapter and page within the chapter)
-- and its character offsets in that page's text; `quote` keeps the words
-- themselves so the highlights list can show them without opening each page.

create type public.highlight_color as enum ('yellow', 'green', 'blue', 'pink');

create table public.highlights (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null,
  volume_id     text not null,
  chapter_index smallint not null check (chapter_index between 0 and 999),
  -- 0-based page within the chapter.
  page          smallint not null check (page between 0 and 999),
  -- Character offsets in the page's text (paragraphs joined by a line break).
  start_offset  integer not null check (start_offset between 0 and 20000),
  end_offset    integer not null check (end_offset > start_offset and end_offset - start_offset <= 2000),
  quote         text not null check (char_length(btrim(quote)) between 1 and 2000),
  color         public.highlight_color not null default 'yellow',
  -- A note is optional; when present it can't be blank.
  note          text check (note is null or char_length(btrim(note)) between 1 and 2000),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  foreign key (user_id, volume_id)
    references public.library_items (user_id, volume_id) on delete cascade
);
-- The foreign key's index (user_id, volume_id) is in the 0701 migration.

create trigger highlights_set_updated_at
  before update on public.highlights
  for each row execute function public.set_updated_at();

alter table public.highlights enable row level security;

create policy "Readers see their own highlights"
  on public.highlights for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers add their own highlights"
  on public.highlights for insert
  to authenticated
  with check (user_id = (select auth.uid()));

create policy "Readers edit their own highlights"
  on public.highlights for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Readers remove their own highlights"
  on public.highlights for delete
  to authenticated
  using (user_id = (select auth.uid()));

-- The passage is fixed once highlighted; only the colour and the note change.
revoke all on public.highlights from anon, authenticated;
grant select, delete on public.highlights to authenticated;
grant insert (user_id, volume_id, chapter_index, page, start_offset, end_offset, quote, color, note) on public.highlights to authenticated;
grant update (color, note) on public.highlights to authenticated;

-- =============================================================================
-- 20261025000701_index_highlights_user_id_volume_id.sql
-- =============================================================================
-- Highlights' foreign key to library_items, and the reader's "highlights in this book" list. One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists highlights_user_id_volume_id_idx on public.highlights (user_id, volume_id);

-- =============================================================================
-- 20261025000800_lists_ratings.sql
-- =============================================================================
-- Favourites, ratings, custom lists and recent searches (Phase 10).
--
-- These belong to one household profile, not the whole account: each profile
-- keeps its own taste and lists. Every row carries the account (user_id) for
-- RLS, and a composite foreign key to reader_profiles(id, account_id) makes
-- sure the profile is that account's (deleting the profile or the account
-- deletes its rows). Keys start with (profile_id, user_id), so they also index
-- those foreign keys.
--
-- A custom list can be shared by link: its share_slug is a random 22-character
-- token the owner sets and clears. public.shared_list() is the only way to read
-- a shared list without signing in, and returns only the list's name,
-- description, the profile's name and its titles. Kids profiles can't share.

-- Lets child tables require "this profile, of this account".
alter table public.reader_profiles add constraint reader_profiles_id_account_id_key unique (id, account_id);

-- The last eight searches, newest first (kept on the profile row).
alter table public.reader_profiles
  add column recent_searches text[] not null default '{}'
    check (cardinality(recent_searches) <= 8 and char_length(array_to_string(recent_searches, '')) <= 800);
grant update (recent_searches) on public.reader_profiles to authenticated;
grant select (recent_searches) on public.reader_profiles to authenticated;

-- Not for me / I like this / I love this.
create type public.taste_rating as enum ('not_for_me', 'like', 'love');

create table public.book_ratings (
  profile_id uuid not null,
  user_id    uuid not null,
  volume_id  text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  rating     public.taste_rating not null,
  updated_at timestamptz not null default now(),
  primary key (profile_id, user_id, volume_id),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

create trigger book_ratings_set_updated_at
  before update on public.book_ratings
  for each row execute function public.set_updated_at();

create table public.favorites (
  profile_id uuid not null,
  user_id    uuid not null,
  volume_id  text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  created_at timestamptz not null default now(),
  primary key (profile_id, user_id, volume_id),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

create table public.custom_lists (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null,
  user_id     uuid not null,
  name        text not null check (char_length(btrim(name)) between 1 and 40),
  name_key    text generated always as (lower(btrim(name))) stored,
  description text not null default '' check (char_length(description) <= 200),
  -- Order on the Library page (0 first).
  position    smallint not null default 0 check (position between 0 and 99),
  -- Set while the list is shared by link; clearing it stops the link working.
  share_slug  text unique check (share_slug ~ '^[A-Za-z0-9_-]{22}$'),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  -- One name per profile; also the index for the foreign key below.
  unique (profile_id, user_id, name_key),
  -- The target of custom_list_items' foreign key.
  unique (id, user_id),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

create trigger custom_lists_set_updated_at
  before update on public.custom_lists
  for each row execute function public.set_updated_at();

create table public.custom_list_items (
  list_id   uuid not null,
  user_id   uuid not null,
  volume_id text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  added_at  timestamptz not null default now(),
  primary key (list_id, user_id, volume_id),
  foreign key (list_id, user_id) references public.custom_lists (id, user_id) on delete cascade
);

-- Limits: 50 lists a profile, 200 books a list; and no sharing from Kids profiles.
create or replace function private.enforce_list_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_table_name = 'custom_lists' then
    if tg_op = 'INSERT' and (select count(*) from public.custom_lists where profile_id = new.profile_id) >= 50 then
      raise exception 'A profile can have up to 50 lists' using errcode = 'check_violation';
    end if;
    if new.share_slug is not null
       and (select age_rating from public.reader_profiles where id = new.profile_id) = 'kids' then
      raise exception 'Kids profiles can''t share lists' using errcode = 'check_violation';
    end if;
  elsif (select count(*) from public.custom_list_items where list_id = new.list_id) >= 200 then
    raise exception 'A list can hold up to 200 books' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
revoke execute on function private.enforce_list_rules() from public, anon, authenticated;

create trigger custom_lists_rules
  before insert or update of share_slug on public.custom_lists
  for each row execute function private.enforce_list_rules();

create trigger custom_list_items_rules
  before insert on public.custom_list_items
  for each row execute function private.enforce_list_rules();

-- A profile that becomes Kids stops sharing its lists.
create or replace function private.unshare_kids_lists()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.age_rating = 'kids' and old.age_rating is distinct from 'kids' then
    update public.custom_lists set share_slug = null where profile_id = new.id and share_slug is not null;
  end if;
  return new;
end;
$$;
revoke execute on function private.unshare_kids_lists() from public, anon, authenticated;

create trigger reader_profiles_unshare_kids_lists
  after update of age_rating on public.reader_profiles
  for each row execute function private.unshare_kids_lists();

-- RLS: each account sees and changes only its own rows.
alter table public.book_ratings enable row level security;
alter table public.favorites enable row level security;
alter table public.custom_lists enable row level security;
alter table public.custom_list_items enable row level security;

create policy "Readers see their own ratings" on public.book_ratings for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers rate as themselves" on public.book_ratings for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers change their own ratings" on public.book_ratings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Readers clear their own ratings" on public.book_ratings for delete to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers see their own favourites" on public.favorites for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers add their own favourites" on public.favorites for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers remove their own favourites" on public.favorites for delete to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers see their own lists" on public.custom_lists for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers create their own lists" on public.custom_lists for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers edit their own lists" on public.custom_lists for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Readers delete their own lists" on public.custom_lists for delete to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers see their own list books" on public.custom_list_items for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers add to their own lists" on public.custom_list_items for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers remove from their own lists" on public.custom_list_items for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.book_ratings, public.favorites, public.custom_lists, public.custom_list_items from anon, authenticated;
grant select, delete on public.book_ratings to authenticated;
grant insert (profile_id, user_id, volume_id, rating) on public.book_ratings to authenticated;
grant update (rating) on public.book_ratings to authenticated;
grant select, delete on public.favorites to authenticated;
grant insert (profile_id, user_id, volume_id) on public.favorites to authenticated;
grant select, delete on public.custom_lists to authenticated;
grant insert (profile_id, user_id, name, description, position) on public.custom_lists to authenticated;
grant update (name, description, position, share_slug) on public.custom_lists to authenticated;
grant select, delete on public.custom_list_items to authenticated;
grant insert (list_id, user_id, volume_id) on public.custom_list_items to authenticated;

-- A shared list, for anyone with its link: only the name, description, the
-- profile's name and the titles in the order they were added. Nothing when the
-- link is wrong, sharing has stopped, or the profile is Kids.
create or replace function public.shared_list(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'name', l.name,
    'description', l.description,
    'owner', p.name,
    'updatedAt', l.updated_at,
    'items', coalesce(
      (select jsonb_agg(i.volume_id order by i.added_at) from public.custom_list_items i where i.list_id = l.id),
      '[]'::jsonb
    )
  )
  from public.custom_lists l
  join public.reader_profiles p on p.id = l.profile_id
  where p_slug ~ '^[A-Za-z0-9_-]{22}$'
    and l.share_slug = p_slug
    and p.age_rating <> 'kids';
$$;
revoke execute on function public.shared_list(text) from public;
grant execute on function public.shared_list(text) to anon, authenticated;

-- =============================================================================
-- 20261028000900_book_summaries.sql
-- =============================================================================
-- AI-written book summaries, a short one and a detailed one per book.
--
-- The `summaries` Edge Function writes a book's summaries the first time
-- anyone asks for them (Claude, from the book's title, author and description)
-- and keeps them here, so each book is summarised once and every later reader
-- gets the same text. A book is a LiteraryWorm catalog id or a Google Books
-- volume id, the same ids library_items uses.
--
-- Only the function (service_role) reads and writes these rows; browser roles
-- have no access at all and go through the function.

create table public.book_summaries (
  volume_id        text        primary key check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  short_summary    text        not null check (char_length(btrim(short_summary)) between 1 and 600),
  detailed_summary text        not null check (char_length(btrim(detailed_summary)) between 1 and 8000),
  -- The Claude model that wrote them, so they can be rewritten when the model changes.
  model            text        not null check (char_length(model) between 1 and 80),
  created_at       timestamptz not null default now()
);

alter table public.book_summaries enable row level security;
revoke all on public.book_summaries from public, anon, authenticated;

-- Says out loud what RLS already does with no permissive policy: browser roles can't touch summaries.
create policy "No browser access to book summaries"
  on public.book_summaries as restrictive for all
  to anon, authenticated
  using (false)
  with check (false);

-- =============================================================================
-- 20261028001000_reading_goals.sql
-- =============================================================================
-- Reading goals and streaks (Phase 12).
--
-- Like favourites and lists, these belong to one household profile: every row
-- carries the account (user_id) for RLS and a composite foreign key to
-- reader_profiles(id, account_id), so the profile must be the account's and
-- deleting the profile or the account deletes its rows. Keys start with
-- (profile_id, user_id), so they also index those foreign keys.
--
-- reading_goals: a profile's target number of books for a year.
-- reading_days: minutes read or listened and books finished, per profile per
-- day (the device's date). Streaks and monthly summaries are worked out from
-- these rows in the app. The app adds to a day through record_reading(), which
-- adds atomically, so two tabs can't overwrite each other's minutes.

create table public.reading_goals (
  profile_id uuid not null,
  user_id    uuid not null,
  year       smallint not null check (year between 2020 and 2100),
  books      smallint not null check (books between 1 and 365),
  updated_at timestamptz not null default now(),
  primary key (profile_id, user_id, year),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

create trigger reading_goals_set_updated_at
  before update on public.reading_goals
  for each row execute function public.set_updated_at();

create table public.reading_days (
  profile_id     uuid not null,
  user_id        uuid not null,
  day            date not null check (day >= date '2020-01-01'),
  minutes        smallint not null default 0 check (minutes between 0 and 1440),
  books_finished smallint not null default 0 check (books_finished between 0 and 100),
  primary key (profile_id, user_id, day),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

alter table public.reading_goals enable row level security;
alter table public.reading_days enable row level security;

create policy "Readers see their own goals" on public.reading_goals for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers set their own goals" on public.reading_goals for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers change their own goals" on public.reading_goals for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Readers clear their own goals" on public.reading_goals for delete to authenticated
  using (user_id = (select auth.uid()));

create policy "Readers see their own reading days" on public.reading_days for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers record their own reading days" on public.reading_days for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers add to their own reading days" on public.reading_days for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Readers clear their own reading days" on public.reading_days for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.reading_goals, public.reading_days from anon, authenticated;
grant select, delete on public.reading_goals to authenticated;
grant insert (profile_id, user_id, year, books) on public.reading_goals to authenticated;
grant update (books) on public.reading_goals to authenticated;
grant select, delete on public.reading_days to authenticated;
grant insert (profile_id, user_id, day, minutes, books_finished) on public.reading_days to authenticated;
grant update (minutes, books_finished) on public.reading_days to authenticated;

-- Adds a little reading to a profile's day: at most an hour and one finished
-- book per call, for a day within two days of the database's date (devices sit
-- in different time zones). SECURITY INVOKER: RLS and the grants above apply,
-- so a caller can only add to their own profiles' days.
create or replace function public.record_reading(p_profile_id uuid, p_day date, p_minutes integer, p_finished integer)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if p_minutes is null or p_minutes not between 0 and 60 then
    raise exception 'minutes must be 0 to 60' using errcode = 'check_violation';
  end if;
  if p_finished is null or p_finished not between 0 and 1 then
    raise exception 'finished must be 0 or 1' using errcode = 'check_violation';
  end if;
  if p_day is null or p_day not between current_date - 2 and current_date + 2 then
    raise exception 'day must be within two days of today' using errcode = 'check_violation';
  end if;
  insert into public.reading_days as d (profile_id, user_id, day, minutes, books_finished)
  values (p_profile_id, (select auth.uid()), p_day, p_minutes, p_finished)
  on conflict (profile_id, user_id, day) do update
    set minutes = least(1440, d.minutes + excluded.minutes),
        books_finished = least(100, d.books_finished + excluded.books_finished);
end;
$$;

revoke execute on function public.record_reading(uuid, date, integer, integer) from public, anon;
grant execute on function public.record_reading(uuid, date, integer, integer) to authenticated;

-- =============================================================================
-- 20261028001001_index_reading_days_user_id.sql
-- =============================================================================
-- RLS on reading_days filters on user_id; the app loads an account's days by it.
create index concurrently if not exists reading_days_user_id_idx on public.reading_days (user_id);

-- =============================================================================
-- 20261028001002_index_reading_goals_user_id.sql
-- =============================================================================
-- RLS on reading_goals filters on user_id; the app loads an account's goals by it.
create index concurrently if not exists reading_goals_user_id_idx on public.reading_goals (user_id);

-- =============================================================================
-- 20261028001100_book_clubs.sql
-- =============================================================================
-- Book clubs (Phase 12).
--
-- A member starts a club around one LiteraryWorm title, with a finish date the
-- club paces itself to, and shares its invite code. Other members join with the
-- code through join_club(); nobody can find a club any other way. Members see
-- the club, each other's display names and the discussion, which is grouped by
-- chapter so the app can hide posts about chapters a reader hasn't reached.
--
-- Clubs belong to accounts (like the library), not household profiles; the app
-- doesn't offer them to Kids profiles. Leaving a club deletes your posts in it
-- (they're tied to the membership), and deleting a club deletes everything in it.

create table public.book_clubs (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null references public.profiles (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 1 and 60),
  volume_id   text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  starts_on   date not null default current_date,
  finishes_on date not null,
  -- 10 random letters and digits, made by the app; changing it stops the old code working.
  invite_code text not null unique check (invite_code ~ '^[A-Za-z0-9]{10}$'),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check (finishes_on > starts_on and finishes_on <= starts_on + 366)
);

create trigger book_clubs_set_updated_at
  before update on public.book_clubs
  for each row execute function public.set_updated_at();

create table public.club_members (
  club_id   uuid not null references public.book_clubs (id) on delete cascade,
  user_id   uuid not null references public.profiles (id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (club_id, user_id)
);

create table public.club_posts (
  id            uuid primary key default gen_random_uuid(),
  club_id       uuid not null,
  user_id       uuid not null references public.profiles (id) on delete cascade,
  chapter_index smallint not null check (chapter_index between 0 and 999),
  body          text not null check (char_length(btrim(body)) between 1 and 2000),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  -- Only members post; leaving the club removes the membership and these posts.
  foreign key (club_id, user_id) references public.club_members (club_id, user_id) on delete cascade
);

create trigger club_posts_set_updated_at
  before update on public.club_posts
  for each row execute function public.set_updated_at();

-- Is the caller a member of this club? SECURITY DEFINER so policies on
-- club_members can use it without querying club_members under its own RLS
-- (which would recurse). It answers only about the caller, with a yes or no.
create or replace function public.is_club_member(p_club_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.club_members
    where club_id = p_club_id and user_id = (select auth.uid())
  );
$$;
revoke execute on function public.is_club_member(uuid) from public, anon;
grant execute on function public.is_club_member(uuid) to authenticated;

-- The owner joins their own club; limits on clubs per account and posts per hour.
create or replace function private.book_club_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_table_name = 'book_clubs' then
    if (select count(*) from public.book_clubs where owner_id = new.owner_id) > 20 then
      raise exception 'An account can run up to 20 clubs' using errcode = 'check_violation';
    end if;
    insert into public.club_members (club_id, user_id) values (new.id, new.owner_id);
  elsif (select count(*) from public.club_posts
         where user_id = new.user_id and created_at > now() - interval '1 hour') > 60 then
    raise exception 'Too many posts. Wait a little and try again.' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
revoke execute on function private.book_club_rules() from public, anon, authenticated;

create trigger book_clubs_rules
  after insert on public.book_clubs
  for each row execute function private.book_club_rules();

create trigger club_posts_rules
  after insert on public.club_posts
  for each row execute function private.book_club_rules();

-- Joins the club with this invite code and returns its id, or null for a wrong
-- code. SECURITY DEFINER because a non-member can't see the club to join it;
-- it checks the code's shape, the caller, a 50-member cap, and limits tries
-- (20 an hour per account) so codes can't be guessed.
create or replace function public.join_club(p_code text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_club uuid;
begin
  if v_user is null then
    raise exception 'Log in to join a club' using errcode = 'insufficient_privilege';
  end if;
  if not public.check_rate_limit('join_club:' || v_user::text, 20, 3600) then
    raise exception 'Too many tries. Wait an hour and try again.' using errcode = 'check_violation';
  end if;
  if p_code is null or p_code !~ '^[A-Za-z0-9]{10}$' then
    return null;
  end if;
  select id into v_club from public.book_clubs where invite_code = p_code;
  if v_club is null then
    return null;
  end if;
  if not exists (select 1 from public.club_members where club_id = v_club and user_id = v_user) then
    if (select count(*) from public.club_members where club_id = v_club) >= 50 then
      raise exception 'This club is full (50 members)' using errcode = 'check_violation';
    end if;
    insert into public.club_members (club_id, user_id) values (v_club, v_user);
  end if;
  return v_club;
end;
$$;
revoke execute on function public.join_club(text) from public, anon;
grant execute on function public.join_club(text) to authenticated;

alter table public.book_clubs enable row level security;
alter table public.club_members enable row level security;
alter table public.club_posts enable row level security;

create policy "Members see their clubs" on public.book_clubs for select to authenticated
  using (owner_id = (select auth.uid()) or public.is_club_member(id));
create policy "Members start clubs as themselves" on public.book_clubs for insert to authenticated
  with check (owner_id = (select auth.uid()));
create policy "Owners change their clubs" on public.book_clubs for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "Owners delete their clubs" on public.book_clubs for delete to authenticated
  using (owner_id = (select auth.uid()));

create policy "Members see who is in their clubs" on public.club_members for select to authenticated
  using (public.is_club_member(club_id));
-- Leaving: anyone but the owner (who deletes the club instead); owners can also remove members.
create policy "Members leave, owners remove" on public.club_members for delete to authenticated
  using (
    exists (
      select 1 from public.book_clubs c
      where c.id = club_id
        and ((user_id = (select auth.uid()) and c.owner_id <> user_id) or (c.owner_id = (select auth.uid()) and user_id <> c.owner_id))
    )
  );

create policy "Members read their clubs' posts" on public.club_posts for select to authenticated
  using (public.is_club_member(club_id));
create policy "Members post as themselves" on public.club_posts for insert to authenticated
  with check (user_id = (select auth.uid()) and public.is_club_member(club_id));
create policy "Members edit their own posts" on public.club_posts for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Members delete their own posts, owners any in their club" on public.club_posts for delete to authenticated
  using (
    user_id = (select auth.uid())
    or exists (select 1 from public.book_clubs c where c.id = club_id and c.owner_id = (select auth.uid()))
  );

revoke all on public.book_clubs, public.club_members, public.club_posts from anon, authenticated;
grant select, delete on public.book_clubs to authenticated;
-- The app makes the club's id, so it needn't read the new row back before the owner is a member.
grant insert (id, owner_id, name, volume_id, starts_on, finishes_on, invite_code) on public.book_clubs to authenticated;
grant update (name, finishes_on, invite_code) on public.book_clubs to authenticated;
grant select, delete on public.club_members to authenticated;
grant select, delete on public.club_posts to authenticated;
grant insert (club_id, user_id, chapter_index, body) on public.club_posts to authenticated;
grant update (body) on public.club_posts to authenticated;

-- =============================================================================
-- 20261028001101_index_book_clubs_owner_id.sql
-- =============================================================================
-- Index for the foreign key on book_clubs (owner_id).
create index concurrently if not exists book_clubs_owner_id_idx on public.book_clubs (owner_id);

-- =============================================================================
-- 20261028001102_index_club_members_user_id.sql
-- =============================================================================
-- Index for the foreign key on club_members (user_id).
create index concurrently if not exists club_members_user_id_idx on public.club_members (user_id);

-- =============================================================================
-- 20261028001103_index_club_posts_club_id_user_id.sql
-- =============================================================================
-- Index for the foreign key on club_posts (club_id, user_id), and for reading a club's posts.
create index concurrently if not exists club_posts_club_id_user_id_idx on public.club_posts (club_id, user_id);

-- =============================================================================
-- 20261028001104_index_club_posts_user_id.sql
-- =============================================================================
-- Index for the foreign key on club_posts (user_id).
create index concurrently if not exists club_posts_user_id_idx on public.club_posts (user_id);

-- =============================================================================
-- 20261028001200_player_settings_devices.sql
-- =============================================================================
-- The audiobook player's settings, and listening on another device (Phase 13).
--
-- Player settings belong to one household profile, like recent searches, so
-- they live on reader_profiles: volume, mute, how far the skip buttons move,
-- and whether each chapter's spoken introduction and closing announcement are
-- skipped as they come.
--
-- listening_devices: every open copy of the app while a member is signed in.
-- The browser makes the id (one per visit) and checks in every minute through
-- touch_listening_device(), which stamps the database's time. An account keeps
-- its 20 most recently seen devices; the app clears devices not seen for a day.
--
-- playback_handoffs: a book and a place sent from one of the account's devices
-- to another, for one of its profiles. The receiving device offers it (through
-- Supabase Realtime, and a check when the tab comes back) and marks it claimed.
-- Composite foreign keys keep the device and the profile the account's own;
-- clearing the device, the profile or the account clears its handoffs.

alter table public.reader_profiles
  add column player_volume        smallint not null default 100 check (player_volume between 0 and 100),
  add column player_muted         boolean  not null default false,
  add column skip_back_seconds    smallint not null default 15 check (skip_back_seconds in (5, 10, 15, 30, 45, 60)),
  add column skip_forward_seconds smallint not null default 15 check (skip_forward_seconds in (5, 10, 15, 30, 45, 60)),
  add column auto_skip_intro      boolean  not null default false,
  add column auto_skip_outro      boolean  not null default false;

grant select (player_volume, player_muted, skip_back_seconds, skip_forward_seconds, auto_skip_intro, auto_skip_outro)
  on public.reader_profiles to authenticated;
grant update (player_volume, player_muted, skip_back_seconds, skip_forward_seconds, auto_skip_intro, auto_skip_outro)
  on public.reader_profiles to authenticated;


create table public.listening_devices (
  id           uuid primary key,
  user_id      uuid not null references auth.users (id) on delete cascade,
  -- "Chrome on Windows": worked out from the browser, shown in the list.
  label        text not null check (char_length(btrim(label)) between 1 and 60),
  last_seen_at timestamptz not null default now(),
  created_at   timestamptz not null default now(),
  -- Lets handoffs require "this device, of this account".
  unique (id, user_id)
);
-- The index for user_id (the foreign key and RLS) is in the 1201 migration.

alter table public.listening_devices enable row level security;

create policy "Members see their own devices" on public.listening_devices for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Members add their own devices" on public.listening_devices for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Members check in their own devices" on public.listening_devices for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Members clear their own devices" on public.listening_devices for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.listening_devices from anon, authenticated;
grant select, delete on public.listening_devices to authenticated;
grant insert (id, user_id, label) on public.listening_devices to authenticated;
grant update (last_seen_at) on public.listening_devices to authenticated;

-- Says a device is still open, with the database's clock (devices' clocks differ).
create or replace function public.touch_listening_device(p_id uuid)
returns void
language sql
security invoker
set search_path = ''
as $$
  update public.listening_devices set last_seen_at = now()
  where id = p_id and user_id = (select auth.uid());
$$;

revoke execute on function public.touch_listening_device(uuid) from public, anon;
grant execute on function public.touch_listening_device(uuid) to authenticated;

-- An account keeps its 20 most recently seen devices: each visit adds one.
create or replace function public.keep_recent_listening_devices()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  delete from public.listening_devices
  where user_id = new.user_id
    and id not in (
      select d.id from public.listening_devices d
      where d.user_id = new.user_id
      order by d.last_seen_at desc
      limit 20
    );
  return null;
end;
$$;

create trigger listening_devices_keep_recent
  after insert on public.listening_devices
  for each row execute function public.keep_recent_listening_devices();


create table public.playback_handoffs (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null,
  profile_id       uuid not null,
  volume_id        text not null check (char_length(volume_id) between 1 and 64),
  -- Where to carry on, in seconds from the start of the book.
  position_seconds integer not null check (position_seconds between 0 and 360000),
  -- The sending device's name as it was when sent.
  from_label       text not null check (char_length(btrim(from_label)) between 1 and 60),
  to_device_id     uuid not null,
  created_at       timestamptz not null default now(),
  -- Set when the receiving device picks it up or turns it down.
  claimed_at       timestamptz,
  foreign key (to_device_id, user_id) references public.listening_devices (id, user_id) on delete cascade,
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);
-- The foreign keys' indexes are in the 1202 and 1203 migrations.

alter table public.playback_handoffs enable row level security;

create policy "Members see their own handoffs" on public.playback_handoffs for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Members send their own handoffs" on public.playback_handoffs for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Members claim their own handoffs" on public.playback_handoffs for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Members clear their own handoffs" on public.playback_handoffs for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.playback_handoffs from anon, authenticated;
grant select, delete on public.playback_handoffs to authenticated;
grant insert (user_id, profile_id, volume_id, position_seconds, from_label, to_device_id) on public.playback_handoffs to authenticated;
grant update (claimed_at) on public.playback_handoffs to authenticated;

-- The receiving device hears of new handoffs straight away (Realtime applies the RLS above).
alter publication supabase_realtime add table public.playback_handoffs;

-- =============================================================================
-- 20261028001201_index_listening_devices_user_id.sql
-- =============================================================================
-- RLS and the device list filter on user_id, newest check-in first; also indexes the foreign key.
create index concurrently if not exists listening_devices_user_id_last_seen_at_idx on public.listening_devices (user_id, last_seen_at);

-- =============================================================================
-- 20261028001202_index_playback_handoffs_to_device_id.sql
-- =============================================================================
-- A device looks up the handoffs sent to it; also indexes the (to_device_id, user_id) foreign key.
create index concurrently if not exists playback_handoffs_to_device_id_user_id_idx on public.playback_handoffs (to_device_id, user_id);

-- =============================================================================
-- 20261028001203_index_playback_handoffs_profile_id.sql
-- =============================================================================
-- Indexes the (profile_id, user_id) foreign key, so deleting a profile finds its handoffs quickly.
create index concurrently if not exists playback_handoffs_profile_id_user_id_idx on public.playback_handoffs (profile_id, user_id);

-- =============================================================================
-- 20261028001300_reading_stats.sql
-- =============================================================================
-- Reading stats and Year in Review (Phase 17).
--
-- reading_days.listening_minutes: of a day's minutes, how many were spent
-- listening to an audiobook (the rest is reading). Never more than the minutes.
--
-- finished_books: which book a profile finished on which day, so Year in Review
-- can list the year's books, their genres and authors. One row per book and day
-- (finishing a book again on another day is another row). Written only through
-- record_reading(), which now takes the listening minutes and the book.

alter table public.reading_days
  add column listening_minutes smallint not null default 0
    check (listening_minutes between 0 and 1440 and listening_minutes <= minutes);

grant insert (listening_minutes) on public.reading_days to authenticated;
grant update (listening_minutes) on public.reading_days to authenticated;

create table public.finished_books (
  profile_id  uuid not null,
  user_id     uuid not null,
  -- A catalog id or a Google Books volume id, in the format library_items uses.
  volume_id   text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  finished_on date not null check (finished_on >= date '2020-01-01'),
  created_at  timestamptz not null default now(),
  primary key (profile_id, user_id, volume_id, finished_on),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

alter table public.finished_books enable row level security;

create policy "Readers see their own finished books" on public.finished_books for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers record their own finished books" on public.finished_books for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers clear their own finished books" on public.finished_books for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.finished_books from anon, authenticated;
grant select, delete on public.finished_books to authenticated;
grant insert (profile_id, user_id, volume_id, finished_on) on public.finished_books to authenticated;

-- The old four-argument version is replaced: callers that leave out the new
-- arguments (older copies of the app) still work, through the defaults.
drop function public.record_reading(uuid, date, integer, integer);

-- Adds a little reading to a profile's day: at most an hour (of which some may
-- be listening) and one finished book per call, for a day within two days of
-- the database's date. With a finished book's id, also records which book.
-- SECURITY INVOKER: RLS and the grants apply, so a caller can only add to their
-- own profiles' days.
create function public.record_reading(
  p_profile_id uuid,
  p_day date,
  p_minutes integer,
  p_finished integer,
  p_listening_minutes integer default 0,
  p_volume_id text default null
)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if p_minutes is null or p_minutes not between 0 and 60 then
    raise exception 'minutes must be 0 to 60' using errcode = 'check_violation';
  end if;
  if p_listening_minutes is null or p_listening_minutes not between 0 and p_minutes then
    raise exception 'listening minutes must be 0 to the minutes' using errcode = 'check_violation';
  end if;
  if p_finished is null or p_finished not between 0 and 1 then
    raise exception 'finished must be 0 or 1' using errcode = 'check_violation';
  end if;
  if p_day is null or p_day not between current_date - 2 and current_date + 2 then
    raise exception 'day must be within two days of today' using errcode = 'check_violation';
  end if;
  insert into public.reading_days as d (profile_id, user_id, day, minutes, books_finished, listening_minutes)
  values (p_profile_id, (select auth.uid()), p_day, p_minutes, p_finished, p_listening_minutes)
  on conflict (profile_id, user_id, day) do update
    set minutes = least(1440, d.minutes + excluded.minutes),
        books_finished = least(100, d.books_finished + excluded.books_finished),
        listening_minutes = least(least(1440, d.minutes + excluded.minutes), d.listening_minutes + excluded.listening_minutes);
  if p_finished = 1 and p_volume_id is not null then
    insert into public.finished_books (profile_id, user_id, volume_id, finished_on)
    values (p_profile_id, (select auth.uid()), p_volume_id, p_day)
    on conflict do nothing;
  end if;
end;
$$;

revoke execute on function public.record_reading(uuid, date, integer, integer, integer, text) from public, anon;
grant execute on function public.record_reading(uuid, date, integer, integer, integer, text) to authenticated;

-- =============================================================================
-- 20261028001301_index_finished_books_user_id.sql
-- =============================================================================
-- RLS on finished_books filters on user_id; the app loads an account's finished books by it, newest first.
create index concurrently if not exists finished_books_user_id_finished_on_idx on public.finished_books (user_id, finished_on);

-- =============================================================================
-- 20261028001400_club_notifications.sql
-- =============================================================================
-- Club notifications (Phase 19).
--
-- club_members gains each member's last_read_at (when they last opened the
-- club, set by mark_club_read()) and notify (whether new posts alert them).
-- club_unread() counts the posts other members wrote since then, by chapter, so
-- the app can leave out chapters the reader hasn't reached (no spoilers in a
-- count or an alert). New posts reach open copies of the app through Supabase
-- Realtime; RLS means each member hears only their own clubs' posts.

alter table public.club_members
  add column last_read_at timestamptz not null default now(),
  add column notify       boolean     not null default true;

create policy "Members change their own membership" on public.club_members for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

grant update (notify, last_read_at) on public.club_members to authenticated;

-- Marks a club read for the caller, at the database's time.
create function public.mark_club_read(p_club_id uuid)
returns void
language sql
security invoker
set search_path = ''
as $$
  update public.club_members
     set last_read_at = now()
   where club_id = p_club_id and user_id = (select auth.uid());
$$;

-- The caller's unread posts in each of their clubs, by chapter.
create function public.club_unread()
returns table (club_id uuid, chapter_index smallint, posts bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  select p.club_id, p.chapter_index, count(*)
    from public.club_posts p
    join public.club_members m on m.club_id = p.club_id and m.user_id = (select auth.uid())
   where p.created_at > m.last_read_at
     and p.user_id <> (select auth.uid())
   group by p.club_id, p.chapter_index;
$$;

revoke execute on function public.mark_club_read(uuid), public.club_unread() from public, anon;
grant execute on function public.mark_club_read(uuid), public.club_unread() to authenticated;

alter publication supabase_realtime add table public.club_posts;

-- =============================================================================
-- 20261028001401_index_club_posts_club_id_created_at.sql
-- =============================================================================
-- club_unread() and each club's discussion read posts by club, newest after a time.
create index concurrently if not exists club_posts_club_id_created_at_idx on public.club_posts (club_id, created_at);

-- =============================================================================
-- 20261028001500_listen_along.sql
-- =============================================================================
-- Listen along (Phase 20).
--
-- A club member leads a listening session of the club's book; other members
-- join and hear the same place. club_listening holds one session per club: who
-- leads it, where they are and whether they're playing, and the speed. The host
-- updates it as they play, pause and skip (and every half minute, so a
-- session whose host has gone can be told apart); members hear each change
-- through Supabase Realtime and follow.
--
-- A session nobody has updated for two minutes has been left (the host closed
-- the app): any member may take it over by becoming its host. Only the host
-- moves it; the host or the club's owner can end it. Leaving the club, or
-- deleting it, ends the sessions that depended on it.

create table public.club_listening (
  club_id          uuid primary key references public.book_clubs (id) on delete cascade,
  host_id          uuid not null,
  position_seconds double precision not null check (position_seconds >= 0 and position_seconds < 1000000),
  playing          boolean not null default false,
  rate             real not null default 1 check (rate between 0.5 and 3),
  updated_at       timestamptz not null default now(),
  -- The host must be a member: leaving the club ends a session they lead.
  foreign key (club_id, host_id) references public.club_members (club_id, user_id) on delete cascade
);

create trigger club_listening_set_updated_at
  before update on public.club_listening
  for each row execute function public.set_updated_at();

alter table public.club_listening enable row level security;

create policy "Members see their clubs' sessions" on public.club_listening for select to authenticated
  using (public.is_club_member(club_id));
create policy "Members start a session as its host" on public.club_listening for insert to authenticated
  with check (host_id = (select auth.uid()) and public.is_club_member(club_id));
-- The host moves it; any member may take over a session left for two minutes.
create policy "Hosts move their session, members take over a left one" on public.club_listening for update to authenticated
  using (
    host_id = (select auth.uid())
    or (public.is_club_member(club_id) and updated_at < now() - interval '2 minutes')
  )
  with check (host_id = (select auth.uid()) and public.is_club_member(club_id));
create policy "Hosts and club owners end a session" on public.club_listening for delete to authenticated
  using (
    host_id = (select auth.uid())
    or exists (select 1 from public.book_clubs c where c.id = club_id and c.owner_id = (select auth.uid()))
  );

revoke all on public.club_listening from anon, authenticated;
grant select, delete on public.club_listening to authenticated;
grant insert (club_id, host_id, position_seconds, playing, rate) on public.club_listening to authenticated;
grant update (host_id, position_seconds, playing, rate) on public.club_listening to authenticated;

alter publication supabase_realtime add table public.club_listening;

-- =============================================================================
-- 20261028001501_index_club_listening_club_id_host_id.sql
-- =============================================================================
-- Index for the foreign key on club_listening (club_id, host_id) to club_members.
create index concurrently if not exists club_listening_club_id_host_id_idx on public.club_listening (club_id, host_id);

-- =============================================================================
-- 20261028001600_uploaded_books.sql
-- =============================================================================
-- Bring your own books (Phase 21).
--
-- A member uploads an EPUB they own. The browser reads it and keeps only its
-- text, chapter by chapter, as a JSON file in the private user-books bucket,
-- in a folder named after the account (so a member can only ever reach their
-- own files). uploaded_books lists them for the profile that uploaded them,
-- with the chapter titles and word counts the reader needs before the text
-- loads. Its id ("u-" and 32 hex digits) is a valid volume id, so the library,
-- reading progress, bookmarks and highlights work on uploads as on any book.
--
-- Kids profiles can't upload (the content isn't rated). A profile keeps up to
-- 50 uploads; each text file is at most 15 MB.

create table public.uploaded_books (
  id             text primary key check (id ~ '^u-[0-9a-f]{32}$'),
  profile_id     uuid not null,
  user_id        uuid not null,
  title          text not null check (char_length(btrim(title)) between 1 and 200),
  author         text not null default '' check (char_length(author) <= 200),
  chapter_titles text[] not null check (cardinality(chapter_titles) between 1 and 500),
  chapter_words  integer[] not null check (cardinality(chapter_words) = cardinality(chapter_titles)),
  words          integer not null check (words between 1 and 5000000),
  -- The text's place in the user-books bucket: <user_id>/<id>.json.
  storage_path   text not null unique,
  created_at     timestamptz not null default now(),
  check (storage_path = user_id::text || '/' || id || '.json'),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade
);

alter table public.uploaded_books enable row level security;

create policy "Readers see their own uploads" on public.uploaded_books for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers upload to their own profiles" on public.uploaded_books for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers delete their own uploads" on public.uploaded_books for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.uploaded_books from anon, authenticated;
grant select, delete on public.uploaded_books to authenticated;
grant insert (id, profile_id, user_id, title, author, chapter_titles, chapter_words, words, storage_path) on public.uploaded_books to authenticated;

-- Not on Kids profiles, and up to 50 a profile.
create function private.enforce_upload_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select age_rating from public.reader_profiles where id = new.profile_id) = 'kids' then
    raise exception 'Kids profiles can''t upload books' using errcode = 'check_violation';
  end if;
  if (select count(*) from public.uploaded_books where profile_id = new.profile_id) >= 50 then
    raise exception 'A profile can have up to 50 uploaded books' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
revoke execute on function private.enforce_upload_rules() from public, anon, authenticated;

create trigger uploaded_books_rules
  before insert on public.uploaded_books
  for each row execute function private.enforce_upload_rules();

-- The bucket: private, JSON only, 15 MB a file.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('user-books', 'user-books', false, 15728640, array['application/json'])
on conflict (id) do nothing;

-- Members read, add and remove files only in their own folder.
create policy "Members read their own book files" on storage.objects for select to authenticated
  using (bucket_id = 'user-books' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Members add their own book files" on storage.objects for insert to authenticated
  with check (bucket_id = 'user-books' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Members remove their own book files" on storage.objects for delete to authenticated
  using (bucket_id = 'user-books' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- =============================================================================
-- 20261028001601_index_uploaded_books_profile_id_user_id.sql
-- =============================================================================
-- Index for the foreign key on uploaded_books (profile_id, user_id); also the profile's list.
create index concurrently if not exists uploaded_books_profile_id_user_id_idx on public.uploaded_books (profile_id, user_id);

-- =============================================================================
-- 20261028001602_index_uploaded_books_user_id.sql
-- =============================================================================
-- RLS on uploaded_books filters on user_id; the app loads an account's uploads by it.
create index concurrently if not exists uploaded_books_user_id_idx on public.uploaded_books (user_id);

-- =============================================================================
-- 20261028001700_legal_pages.sql
-- =============================================================================
-- Staff roles, and editable legal pages (Phase 22).
--
-- staff_roles gives accounts access beyond being a member: admin (everything,
-- including granting roles), editor (the legal pages), and developer, billing,
-- customer_service and blog (recorded for the tools that will use them). An
-- account can hold several. Roles are granted and removed only by admins,
-- through grant_staff_role() and revoke_staff_role(); a role granted to an
-- email with no account yet waits in staff_invites and is applied when that
-- email signs up. A member sees only their own roles; admins see the team
-- through staff_members().
--
-- legal_pages holds the live copy of each footer page (Terms, Privacy,
-- Cookies, Copyright/DMCA, Accessibility, Children's Privacy, Privacy Choices,
-- Help, Status): anyone reads them; editors and admins change a page's title,
-- summary and sections. Each change stamps who made it and when and keeps the
-- page as it was in legal_page_revisions. Pages aren't added or removed from
-- the browser: the set is fixed with the footer.

create type public.staff_role as enum ('admin', 'developer', 'editor', 'billing', 'customer_service', 'blog');

create table public.staff_roles (
  user_id    uuid not null references auth.users (id) on delete cascade,
  role       public.staff_role not null,
  granted_at timestamptz not null default now(),
  granted_by uuid references auth.users (id) on delete set null,
  primary key (user_id, role)
);

-- Roles for emails that haven't signed up yet.
create table public.staff_invites (
  email      text not null check (email = lower(btrim(email)) and char_length(email) between 3 and 320),
  role       public.staff_role not null,
  invited_at timestamptz not null default now(),
  invited_by uuid references auth.users (id) on delete set null,
  primary key (email, role)
);

alter table public.staff_roles enable row level security;
alter table public.staff_invites enable row level security;
create policy "Members see their own roles" on public.staff_roles for select to authenticated
  using (user_id = (select auth.uid()));
-- No browser access to staff_invites: admins reach it through the functions below.
revoke all on public.staff_roles, public.staff_invites from anon, authenticated;
grant select on public.staff_roles to authenticated;

-- True when the caller holds the role, or is an admin (admins can do everything).
-- SECURITY INVOKER: it reads the caller's own rows.
create function public.has_staff_role(p_role public.staff_role)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select exists (
    select 1 from public.staff_roles
    where user_id = (select auth.uid()) and role in (p_role, 'admin')
  );
$$;
revoke execute on function public.has_staff_role(public.staff_role) from public, anon;
grant execute on function public.has_staff_role(public.staff_role) to authenticated;

-- The team, for admins: every account with a role, and every waiting invitation.
-- SECURITY DEFINER because it reads emails from auth.users; it checks the caller
-- is an admin first.
create function public.staff_members()
returns table (user_id uuid, email text, display_name text, roles public.staff_role[], invited boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.has_staff_role('admin') then
    raise exception 'Only admins can see the team' using errcode = 'insufficient_privilege';
  end if;
  return query
    select s.user_id, lower(u.email)::text, p.display_name, array_agg(s.role order by s.role), false
      from public.staff_roles s
      join auth.users u on u.id = s.user_id
      left join public.profiles p on p.id = s.user_id
     group by s.user_id, u.email, p.display_name
    union all
    select null::uuid, i.email, null::text, array_agg(i.role order by i.role), true
      from public.staff_invites i
     group by i.email
     order by 2;
end;
$$;

-- Gives an account a role, by email. With no account for that email yet, the
-- role waits as an invitation. Returns 'granted' or 'invited'. Admins only.
create function public.grant_staff_role(p_email text, p_role public.staff_role)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(p_email));
  v_user uuid;
begin
  if not public.has_staff_role('admin') then
    raise exception 'Only admins can grant access' using errcode = 'insufficient_privilege';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+$' then
    raise exception 'That isn''t an email address' using errcode = 'check_violation';
  end if;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is null then
    insert into public.staff_invites (email, role, invited_by) values (v_email, p_role, (select auth.uid()))
    on conflict do nothing;
    return 'invited';
  end if;
  insert into public.staff_roles (user_id, role, granted_by) values (v_user, p_role, (select auth.uid()))
  on conflict do nothing;
  return 'granted';
end;
$$;

-- Takes a role away (or withdraws an invitation, by email). Admins only; the
-- last admin can't be removed, so the team can't lock itself out.
create function public.revoke_staff_role(p_email text, p_role public.staff_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(p_email));
  v_user uuid;
begin
  if not public.has_staff_role('admin') then
    raise exception 'Only admins can remove access' using errcode = 'insufficient_privilege';
  end if;
  delete from public.staff_invites where email = v_email and role = p_role;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is null then
    return;
  end if;
  if p_role = 'admin' and (select count(*) from public.staff_roles where role = 'admin') <= 1
     and exists (select 1 from public.staff_roles where user_id = v_user and role = 'admin') then
    raise exception 'LiteraryWorm needs at least one admin' using errcode = 'check_violation';
  end if;
  delete from public.staff_roles where user_id = v_user and role = p_role;
end;
$$;

revoke execute on function public.staff_members(), public.grant_staff_role(text, public.staff_role), public.revoke_staff_role(text, public.staff_role) from public, anon;
grant execute on function public.staff_members(), public.grant_staff_role(text, public.staff_role), public.revoke_staff_role(text, public.staff_role) to authenticated;

-- A new account picks up any roles waiting for its email.
create function private.apply_staff_invites()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.staff_roles (user_id, role, granted_by)
  select new.id, i.role, i.invited_by from public.staff_invites i where i.email = lower(new.email)
  on conflict do nothing;
  delete from public.staff_invites where email = lower(new.email);
  return new;
end;
$$;
revoke execute on function private.apply_staff_invites() from public, anon, authenticated;

create trigger apply_staff_invites
  after insert on auth.users
  for each row execute function private.apply_staff_invites();

create table public.legal_pages (
  slug       text primary key check (slug ~ '^[a-z][a-z0-9-]{1,39}$'),
  position   smallint not null check (position between 0 and 99),
  title      text not null check (char_length(btrim(title)) between 1 and 80),
  summary    text not null check (char_length(btrim(summary)) between 1 and 600),
  -- Each section's shape is checked by the edit trigger below.
  sections   jsonb not null default '[]' check (jsonb_typeof(sections) = 'array' and octet_length(sections::text) <= 200000),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);

create table public.legal_page_revisions (
  id        uuid primary key default gen_random_uuid(),
  slug      text not null references public.legal_pages (slug) on delete cascade,
  title     text not null,
  summary   text not null,
  sections  jsonb not null,
  -- When this version was replaced, and by whom.
  replaced_at timestamptz not null default now(),
  replaced_by uuid references auth.users (id) on delete set null
);

alter table public.legal_pages enable row level security;
alter table public.legal_page_revisions enable row level security;

create policy "Anyone reads the legal pages" on public.legal_pages for select to anon, authenticated
  using (true);
create policy "Editors edit the legal pages" on public.legal_pages for update to authenticated
  using ((select public.has_staff_role('editor'))) with check ((select public.has_staff_role('editor')));
create policy "Editors read earlier versions" on public.legal_page_revisions for select to authenticated
  using ((select public.has_staff_role('editor')));
create policy "Edits record earlier versions" on public.legal_page_revisions for insert to authenticated
  with check ((select public.has_staff_role('editor')) and replaced_by = (select auth.uid()));

revoke all on public.legal_pages, public.legal_page_revisions from anon, authenticated;
grant select on public.legal_pages to anon, authenticated;
grant update (title, summary, sections) on public.legal_pages to authenticated;
grant select on public.legal_page_revisions to authenticated;
grant insert (slug, title, summary, sections, replaced_by) on public.legal_page_revisions to authenticated;

-- Each edit: check the sections, keep the page as it was, then stamp who
-- changed it and when. (The check is here rather than in a constraint so it
-- runs without editors needing the private schema.)
create function private.record_legal_edit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- An array of up to 40 { heading, paragraphs[] }: a heading of 1-120 characters and 1-60
  -- paragraphs of 1-5000 characters each.
  if jsonb_array_length(new.sections) > 40 or exists (
    select 1 from jsonb_array_elements(new.sections) sec
    where jsonb_typeof(sec) <> 'object'
       or jsonb_typeof(sec -> 'heading') is distinct from 'string'
       or char_length(btrim(sec ->> 'heading')) not between 1 and 120
       or jsonb_typeof(sec -> 'paragraphs') is distinct from 'array'
       or jsonb_array_length(sec -> 'paragraphs') not between 1 and 60
       or exists (
         select 1 from jsonb_array_elements(sec -> 'paragraphs') para
         where jsonb_typeof(para) <> 'string' or char_length(btrim(para #>> '{}')) not between 1 and 5000
       )
  ) then
    raise exception 'Each section needs a heading (up to 120 characters) and 1 to 60 paragraphs of up to 5000 characters; up to 40 sections'
      using errcode = 'check_violation';
  end if;
  if (new.title, new.summary, new.sections) is not distinct from (old.title, old.summary, old.sections) then
    return new;
  end if;
  insert into public.legal_page_revisions (slug, title, summary, sections, replaced_by)
  values (old.slug, old.title, old.summary, old.sections, (select auth.uid()));
  new.updated_at := now();
  new.updated_by := (select auth.uid());
  return new;
end;
$$;
revoke execute on function private.record_legal_edit() from public, anon, authenticated;

create trigger legal_pages_record_edit
  before update on public.legal_pages
  for each row execute function private.record_legal_edit();

-- =============================================================================
-- 20261028001701_index_legal_pages_updated_by.sql
-- =============================================================================
-- Index for the foreign key on legal_pages (updated_by).
create index concurrently if not exists legal_pages_updated_by_idx on public.legal_pages (updated_by);

-- =============================================================================
-- 20261028001702_index_legal_page_revisions_slug.sql
-- =============================================================================
-- Index for the foreign key on legal_page_revisions (slug).
create index concurrently if not exists legal_page_revisions_slug_idx on public.legal_page_revisions (slug, replaced_at);

-- =============================================================================
-- 20261028001703_index_legal_page_revisions_replaced_by.sql
-- =============================================================================
-- Index for the foreign key on legal_page_revisions (replaced_by).
create index concurrently if not exists legal_page_revisions_replaced_by_idx on public.legal_page_revisions (replaced_by);

-- =============================================================================
-- 20261028001704_seed_legal_pages.sql
-- =============================================================================
-- The legal pages' first copy, from the app's built-in text (generated by
-- supabase/build-legal-seed.py; don't edit by hand). Admins edit them afterwards.

insert into public.legal_pages (slug, position, title, summary, sections) values
  ($lw$accessibility$lw$, 0, $lw$Accessibility Policy$lw$, $lw$This statement applies to the https://www.literaryworm.com website. LiteraryWorm is committed to ensuring our services are accessible to people with disabilities, so everyone at home can read and listen. We aim to conform with the Web Content Accessibility Guidelines (WCAG) 2.2 at Level AA.$lw$, $lw$[{"heading": "Accessibility features", "paragraphs": ["You should be able to change colors, contrast levels, and fonts; zoom in up to 200% without loss of information or functionality; navigate the website with just a keyboard, including keyboard shortcuts in the player; listen to the website using a screen reader, with labelled controls; use the read-along transcript with audiobooks; stop moving images with reduced motion; and turn on underlined links.", "The accessibility menu at the top of every page changes text size, theme (dark or light), an easier-to-read font, high contrast, underlined links and reduced motion. Your choices last for the visit.", "Language in the accessibility menu shows the app in English, Spanish, French, German, Portuguese, Italian or Dutch; a visit starts in your browser's language when it's one of these, and a member's profile keeps the language it chooses on every device. Book details, What's new and our emails stay in English for now, and so do these policies and Help, where the English version is the one that applies.", "High contrast turns the app black or white, with text at the WCAG AAA level (7:1) and stronger edges on buttons and fields, and links underlined. It's on from the start when your device asks for more contrast (Increase contrast on iPhone, iPad and Mac). With a Windows contrast theme, buttons, switches and progress bars keep their edges and the chosen option is highlighted.", "Every page works with a keyboard alone, and the player has keyboard shortcuts, listed under its controls. Buttons and links are at least 44 pixels square, focus is always visible, and dialogs keep focus inside them and return it when they close.", "Screen readers hear labelled controls, headings that outline each page, and announcements when something changes, such as a saved setting or a new club post. Pictures that carry meaning, like shared quote cards, have text alternatives; decorative covers are hidden from screen readers and their titles are always written nearby.", "In the reader you can choose the font, size, spacing, margins and theme. Fonts include Lexend and OpenDyslexic, a typeface made for readers with dyslexia, and a reading guide can show a ruler on one line or dim everything but a few lines (line focus); it follows your pointer or a tap, and J and K move it a line. Audiobooks have speed control, a sleep timer, skip lengths you choose, and controls on your lock screen and headphones. The player's read-along transcript follows the narration.", "In car mode, the buttons fill a phone or tablet screen at every size and way up, and voice control (off until you turn it on, not on Kids profiles) lets you play, pause, skip and change chapter by saying so.", "Newer features follow the same rules. Mood and pace tags are buttons that say whether they're on, content notes and translations are announced when they arrive, a Kids profile's Time for bed screen works with a keyboard and screen reader, and a shared audio clip has a labelled Play button."]}, {"heading": "Compatibility with assistive technology", "paragraphs": ["Our website is designed to be compatible with screen readers and other assistive technologies, using standard HTML and ARIA, in current versions of Chrome, Edge, Firefox and Safari. We haven't yet completed testing with each screen reader; if yours has trouble, please tell us."]}, {"heading": "Conformance status", "paragraphs": ["Status: partially conformant with WCAG 2.2 Level AA. Partially conformant means that most of the website conforms, with the exceptions listed under \"What we know isn't perfect yet\".", "We conducted our most recent accessibility evaluation in October 2026. For more information, see \"How we test\"."]}, {"heading": "What we know isn't perfect yet", "paragraphs": ["The read-along transcript for some titles is sample text rather than the exact recording, and is hidden while a real recording plays.", "Book details and covers from Google Books, and the LibriVox recordings, come from other services; we can't always fix problems in their content.", "Books you upload show their text only; images and tables in the original EPUB aren't shown.", "Content notes, translations and other AI-written text can be wrong; they're labelled as written by AI.", "The Google Books preview is Google's own viewer, so we can't change how it works with assistive technology."]}, {"heading": "How we test", "paragraphs": ["Every change is tested with a keyboard, at phone and desktop sizes, and with automated accessibility checks (Lighthouse accessibility scores of 100) before it's released."]}, {"heading": "Feedback and contact information", "paragraphs": ["Please let us know if you experience accessibility barriers using our services or need information in an alternative format. Tell us what you were trying to do, which page it was on, and the browser and assistive technology you use.", "Email: accessibility@literaryworm.com (mark the subject line \"Accessibility\").", "We aim to reply within five working days, and always within 15 business days, and to fix problems that block reading or listening first. We keep a record of accessibility feedback and our replies."]}, {"heading": "Enforcement", "paragraphs": ["If you're not satisfied with our response, you can contact the enforcement authority in your country: Germany: BFIT-Bund. France: Défenseur des droits. Ireland: National Disability Authority. Spain: OADIS. Italy: AgID. For other EU countries, contact your national consumer protection authority."]}, {"heading": "Preparation of this statement", "paragraphs": ["This statement was prepared on 28 October 2026 and last updated on 1 November 2026. We review it every year, and whenever we make significant changes to the service.", "For questions about accessibility or this statement, email us at accessibility@literaryworm.com."]}]$lw$::jsonb),
  ($lw$privacy$lw$, 1, $lw$Privacy Policy$lw$, $lw$This Privacy Notice for LiteraryWorm ("we," "us," or "our") describes how and why we might access, collect, store, use, and/or share ("process") your personal information when you use our services ("Services"), including when you visit our website at https://www.literaryworm.com or any website of ours that links to this Privacy Notice, or engage with us in other related ways.$lw$, $lw$[{"heading": "Questions or concerns?", "paragraphs": ["Reading this Privacy Notice will help you understand your privacy rights and choices. We are responsible for making decisions about how your personal information is processed. If you do not agree with our policies and practices, please do not use our Services. If you still have any questions or concerns, please contact us at usprivacy@literaryworm.com."]}, {"heading": "Summary of key points", "paragraphs": ["This summary provides key points from our Privacy Notice; you can find out more details about any of these topics in the numbered sections below.", "What personal information do we process? When you visit, use, or navigate our Services, we may process personal information depending on how you interact with us and the Services, the choices you make, and the products and features you use. See section 1.", "Do we process any sensitive personal information? Some information may be considered \"special\" or \"sensitive\" in certain jurisdictions, for example your racial or ethnic origins, sexual orientation, religious beliefs, biometric or financial data. We don't collect any of those. The only information we hold that some laws treat as sensitive is your account login information.", "Do we collect any information from third parties? Only from Stripe, which tells us whether your payments succeed and how your membership stands. We don't buy information about you or get it from social networks or data brokers.", "How do we process your information? We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes with your consent. We process your information only when we have a valid legal reason to do so. See section 2.", "In what situations and with which parties do we share personal information? Only with the service providers that help us run LiteraryWorm, and in the specific situations described in section 4. We don't sell your personal information or share it for advertising.", "What don't we do? We don't sell your information or share it for advertising, we don't show ads, and we don't use your reading, notes, uploads or posts to train AI models. Our only analytics is Ahrefs Web Analytics: it sets no cookies, runs only if you allow analytics, and never runs for Kids profiles.", "How do we keep your information safe? Connections use HTTPS, our database lets each account read only its own data, passwords and PINs are kept only as one-way hashes, and you can add two-step sign-in or passkeys.", "However, no electronic transmission over the internet or information storage technology can be guaranteed to be 100% secure, so we cannot promise or guarantee that hackers, cybercriminals, or other unauthorized third parties will not be able to defeat our security and improperly collect, access, steal, or modify your information. See section 9.", "What are your rights? Depending on where you are located geographically, the applicable privacy law may mean you have certain rights regarding your personal information. See section 11.", "How do you exercise your rights? The easiest way is in Account, where you can download a copy of your data, change it, or delete it, or by contacting us at usprivacy@literaryworm.com. We will consider and act upon any request in accordance with applicable data protection laws."]}, {"heading": "1. What information do we collect?", "paragraphs": ["Personal information you disclose to us. In Short: We collect personal information that you provide to us.", "We collect personal information that you voluntarily provide to us when you register on the Services, when you participate in activities on the Services, or otherwise when you contact us.", "Personal Information Provided by You. The personal information that we collect depends on the context of your interactions with us and the Services, the choices you make, and the products and features you use. It includes your email address, display name, password, date of birth, contact preferences (marketing emails) and authentication data, and what you read, save and share in the app.", "Section 18 lists exactly what we keep.", "Sensitive Information. We do not collect biometric data, financial data, or other special categories of personal information.", "Payment Data. Payments are handled by Stripe (https://stripe.com/privacy), which collects and stores your card details; we never see or store your full card number. We keep the plan you chose, your billing day, Stripe's ids for your customer record and subscription, and whether each payment succeeded.", "If you buy a gift membership, we keep its code, plan, number of months and price, and whether and when it was redeemed (and, for a gift that starts on a later day, when we reminded the buyer).", "A gift can come with up to 10 LiteraryWorm books the buyer picks: we keep which ones with the code, Stripe receives their ids with the payment, the email we send the recipient names them, and redeeming the gift adds them to the redeemer's library.", "If you ask us to email a gift to someone, Stripe receives their email address and your message with the payment, and we keep both only until the email has gone; only the buyer can see the code, and we record which account redeemed it.", "Social Media Login Data. We don't offer registration or log in with social media accounts.", "All personal information that you provide to us must be true, complete, and accurate, and you must notify us of any changes to such personal information.", "Information automatically collected. In Short: Some information — such as your Internet Protocol (IP) address and browser and device characteristics — is collected automatically when you visit our Services.", "Log and Usage Data. Our hosting and backend providers (Vercel and Supabase) automatically record service-related, diagnostic and performance information when you access the Services, in log files. This may include your IP address, browser type, the date and time of requests, the pages and files requested, and error reports. It is used to keep the Services secure and working, not for advertising, and we don't build profiles from it.", "Location Data. We don't collect your device's location, and we don't use GPS or similar technologies.", "Google API. We use the Google Books API only for book information: our server sends it search words or an ISBN, book ids and the names of authors people follow, never who's asking. Our use of information received from Google APIs will adhere to Google API Services User Data Policy, including the Limited Use requirements."]}, {"heading": "2. How do we process your information?", "paragraphs": ["In Short: We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes only with your prior explicit consent.", "To facilitate account creation and authentication and otherwise manage user accounts. We may process your information so you can create and log in to your account, as well as keep your account and household profiles in working order.", "To deliver and facilitate delivery of services to the user. We may process your information to provide you with the requested service, such as keeping your place in a book across devices, your bookmarks, highlights, journal, saved words, lists, Up next queue, goals and stats.", "To respond to user inquiries/offer support to users. We may process your information to respond to your inquiries and solve any potential issues you might have with the requested service.", "To send administrative information to you. We may process your information to send you details about your account, changes to our terms and policies, and other similar information.", "To enable user-to-user communications. We may process your information if you choose to use any of our offerings that allow for communication with another user, such as reading logs, book clubs and shared lists. A book club's calendar link lets your calendar app read the club's meetings (their names, times and notes) from us; the link is yours, we don't store it, and it stops working if you leave the club.", "To send you marketing and promotional communications, only if you turned on marketing emails. You can turn them off at any time in Account. For more information, see section 11.", "To show you recommendations. Book recommendations and reading stats are worked out in your browser from your own reading; they aren't used for advertising.", "To protect our Services. We may process your information as part of our efforts to keep our Services safe and secure, including fraud monitoring and prevention and limiting how often our features can be used.", "To save or protect an individual's vital interest. We may process your information when necessary to save or protect an individual's vital interest, such as to prevent harm.", "We don't process your information to deliver targeted advertising."]}, {"heading": "3. What legal bases do we rely on to process your information?", "paragraphs": ["In Short: We only process your personal information when we believe it is necessary and we have a valid legal reason (i.e., legal basis) to do so under applicable law, like with your consent, to comply with laws, to provide you with services to enter into or fulfill our contractual obligations, to protect your rights, or to fulfill our legitimate business interests.", "If you are located in the EU or UK, this section applies to you. The General Data Protection Regulation (GDPR) and UK GDPR require us to explain the valid legal bases we rely on in order to process your personal information. As such, we may rely on the following legal bases to process your personal information:", "Consent. We may process your information if you have given us permission (i.e., consent) to use your personal information for a specific purpose, such as marketing emails or a Kids profile. You can withdraw your consent at any time (see section 11).", "Performance of a Contract. We may process your personal information when we believe it is necessary to fulfill our contractual obligations to you, including providing our Services or at your request prior to entering into a contract with you.", "Legitimate Interests. We may process your information when we believe it is reasonably necessary to achieve our legitimate business interests and those interests do not outweigh your interests and fundamental rights and freedoms: to diagnose problems and prevent fraudulent activities, and to keep the Services secure and working.", "Legal Obligations. We may process your information where we believe it is necessary for compliance with our legal obligations, such as to cooperate with a law enforcement body or regulatory agency, exercise or defend our legal rights, or disclose your information as evidence in litigation in which we are involved.", "Vital Interests. We may process your information where we believe it is necessary to protect your vital interests or the vital interests of a third party, such as situations involving potential threats to the safety of any person.", "If you are located in Canada, this section applies to you. We may process your information if you have given us specific permission (i.e., express consent) to use your personal information for a specific purpose, or in situations where your permission can be inferred (i.e., implied consent). You can withdraw your consent at any time.", "In some exceptional cases, we may be legally permitted under applicable law to process your information without your consent, including, for example:", "if collection is clearly in the interests of an individual and consent cannot be obtained in a timely way;", "for investigations and fraud detection and prevention;", "for business transactions provided certain conditions are met;", "if it is contained in a witness statement and the collection is necessary to assess, process, or settle an insurance claim;", "for identifying injured, ill, or deceased persons and communicating with next of kin;", "if we have reasonable grounds to believe an individual has been, is, or may be victim of financial abuse;", "if it is reasonable to expect collection and use with consent would compromise the availability or the accuracy of the information and the collection is reasonable for purposes related to investigating a breach of an agreement or a contravention of the laws of Canada or a province;", "if disclosure is required to comply with a subpoena, warrant, court order, or rules of the court relating to the production of records;", "if it was produced by an individual in the course of their employment, business, or profession and the collection is consistent with the purposes for which the information was produced;", "if the collection is solely for journalistic, artistic, or literary purposes;", "and if the information is publicly available and is specified by the regulations.", "We may disclose de-identified information for approved research or statistics projects, subject to ethics oversight and confidentiality commitments."]}, {"heading": "4. When and with whom do we share your personal information?", "paragraphs": ["In Short: We share information only with the service providers that help us run LiteraryWorm, and in the situations described in this section.", "Service providers. Supabase stores the data above and runs our server functions. Vercel hosts the website.", "Mailgun sends our emails and the book club invitations members send, so it receives the address each email goes to and the email's contents.", "The emails confirm your email address, reset your password, and tell you when a book you set Remind me on is out. There's a weekly list of new books from authors you follow, and a monthly round-up of what's new in LiteraryWorm if you turn it on.", "If you turn it on, a weekly report of how your Kids profiles read: their names, reading and listening time, days read, books finished and any weekly goal.", "A reminder the day before a book club you're in meets, and a note when one of its meetings moves or is cancelled: the club's name and book and the meeting's name, times and note, with the meeting as a calendar file.", "If you turn it on, a daily email of new posts in your book clubs: each club's name and book, the chapters you've reached that have new posts, how many and the display names of who wrote them; never what they wrote.", "A reminder three days before a gift membership you bought for a later day starts (its plan, months and start day; never the code), and a gift membership a member asked us to email to you (its code, plan and months, the buyer's display name and any message they wrote).", "And an email confirming that your account was deleted.", "We turn off Mailgun's open and click tracking.", "Our service providers may use your information only to provide their service to us, except where this section says they handle it under their own policy.", "If you turn on notifications on a device, the notification about a book you set Remind me on (its title and author, and the profile's name) goes through your browser's push service (Google for Chrome and Android, Apple for Safari, Mozilla for Firefox, Microsoft for Edge), encrypted so that only your browser can read it.", "You choose in Account → Preferences which kinds your devices get; besides release days they can be a club meeting in the next day (the club's and meeting's names), new posts in your clubs (the club's name, how many, the chapter and who wrote them; never what they said), an evening reading-streak nudge (a profile's name and run of days; for this we keep each device's time zone) and a grown-up's answer to a Kids book request (the profile's name and the book).", "Stripe processes payments. When you add a payment method, Stripe receives your name, email address, card details and billing address, and handles them under its own privacy notice (https://stripe.com/privacy).", "Termly provides our cookie consent banner and our privacy request forms. Your browser loads the banner from Termly on each visit, so Termly receives those requests, including your IP address, and your consent choice is kept in your browser. Termly handles this under its own privacy policy (https://termly.io/our-privacy-policy/). It never handles payment details: Stripe does.", "Ahrefs Web Analytics counts visits so we can see which pages people use. If you allow analytics in the consent banner, your browser sends Ahrefs (analytics.ahrefs.com) the pages you visit, their titles, the site you came from, your screen size and language, and links you follow to other sites. Ahrefs also receives your IP address and browser details with each request.", "We send page addresses without anything after ? or #, though a form you send, such as a search, can include it. Ahrefs sets no cookies and keeps nothing in your browser. It's off while a Kids profile is in use and on pages whose links carry codes, such as password resets, invitations and unsubscribe links.", "Ahrefs handles this under its own privacy policy (https://ahrefs.com/legal/privacy-policy). To stop it, choose Consent Preferences at the bottom of any page and decline analytics.", "Anthropic (Claude) writes book summaries and content notes, answers Ask the book questions, translates passages you select, writes Who's who, chapter quizzes, Previously… recaps and book clubs' discussion questions (see section 6).", "Google Books answers searches and book details through our server, which sends only the search words or ISBN, book ids and the names of authors people follow, never who's asking. Book covers and the Google Books preview load from books.google.com directly in your browser, and Google sets third-party cookies there (see the Cookie Policy).", "LibriVox recordings stream from the Internet Archive directly from your browser. The app's fonts load from Google Fonts the same way, so Google receives your IP address with those requests.", "Other members. Reading logs are public, with your display name. Book club posts are seen by the club's members. If you invite someone to a club by email, the invitation shows them your display name and the club's name, book and finish date; we send it through Mailgun and keep only a one-way fingerprint of their address for 30 days (so the same address isn't invited again within a week), never the address itself.", "Lists you share can be read by anyone with the link, who can also buy you a gift membership that comes with their LiteraryWorm books. Staff with the right access can see account details to run the service and help you.", "Our support team. To help with a question, LiteraryWorm staff with the customer service role (and admins) can look up an account by its email address.", "They see the name and email, when the account was made, whether the email is confirmed and two-step sign-in is on, the plan and its billing state (never card details), how many profiles there are, this month's listening against the plan, and the devices keeping books offline. They never see your library, reading, notes, highlights or searches. Every lookup is recorded with who made it and when, and the record is deleted after a year.", "Business Transfers. We may share or transfer your information in connection with, or during negotiations of, any merger, sale of company assets, financing, or acquisition of all or a portion of our business to another company."]}, {"heading": "5. Do we use cookies and other tracking technologies?", "paragraphs": ["In Short: We use only essential cookies and similar technologies, described in our Cookie Policy. Because we use the Google Books API, Google sets third-party cookies from books.google.com when book covers and previews load.", "When you first visit, a banner from Termly asks for your cookie choice, and you can change it at any time with Consent Preferences at the bottom of every page. Because we use only essential cookies, declining changes nothing about how the Services work.", "The technologies we use help us maintain the security of our Services and your account, keep you signed in, and let the app work offline.", "We don't permit third parties or service providers to use online tracking technologies on our Services for advertising, and we don't use Google Analytics. With your consent, we count visits with Ahrefs Web Analytics, which sets no cookies and never runs for Kids profiles (see section 4).", "Google Books covers and the Google Books preview load from books.google.com, and Google sets its own third-party cookies there, under Google's Privacy Policy. We don't receive them. To stop them, block third-party cookies in your browser; LiteraryWorm keeps working.", "Specific information about the technologies we use and how you can refuse certain cookies is set out in our Cookie Policy."]}, {"heading": "6. Do we offer artificial intelligence-based products?", "paragraphs": ["In Short: We offer products, features, or tools powered by artificial intelligence, machine learning, or similar technologies.", "As part of our Services, we offer features powered by artificial intelligence (\"AI Products\"). The terms in this Privacy Notice govern your use of the AI Products within our Services.", "Use of AI Technologies. We provide the AI Products through one third-party service provider (\"AI Service Provider\"): Anthropic (Claude). We don't use OpenAI, Hugging Face, Google Cloud AI, DeepSeek or Gemini to process your information. Figma Make was used only to design the app's screens and never receives your information. You must not use the AI Products in any way that violates the terms or policies of the AI Service Provider.", "Our AI Products. Book summaries: short and detailed summaries of books in our catalog, written the first time anyone asks, from the book's details; no personal information is sent.", "Content notes: for each of our titles, how much violence, death, frightening scenes, language, sexual content, alcohol and drugs, prejudice and self-harm it has, written the first time anyone asks, from the book's details; no personal information is sent, and the notes are kept so everyone sees the same ones.", "Ask the book: answers to your questions about a public-domain book. We send your question and the book's text up to your chapter; we don't send your name, email or account details.", "Translate: a passage you select in a public-domain book, in another language. We send only the words you selected (they must be in that chapter), nothing about you, and keep nothing.", "Who's who: the characters you've met in a public-domain book so far. We send only the book's text up to your chapter, nothing about you, and keep the list so the next reader at that chapter gets the same one.", "Previously…: in the player, a recap of a public-domain book up to the chapter you've reached. We send only the text of the chapters before it, nothing about you, and keep the recap so the next listener there gets the same one.", "Discussion questions: on a book club's page, questions about a chapter of a public-domain book you've reached. We send only the book's text up to the end of that chapter, nothing about you or the club, and keep the questions so every club at that chapter gets the same ones.", "Chapter quizzes: a few questions about a chapter of a public-domain book, written for young readers. We send only that chapter's text, nothing about you, and keep the quiz so every reader of that chapter gets the same one; your score is saved with your profile.", "Ask the book, Translate, Who's who and book clubs (with their discussion questions) aren't offered to Kids profiles; summaries, content notes, recaps and quizzes are. Summaries, content notes, answers, translations, Who's who, recaps, quizzes and discussion questions are labelled as written by AI.", "How We Process Your Data Using AI. All personal information processed using our AI Products is handled in line with this Privacy Notice and our agreement with the AI Service Provider. We don't use your reading history, notes, uploads or posts to train AI models."]}, {"heading": "7. How do we handle your social logins?", "paragraphs": ["We don't offer registration or log in using social media accounts. If we add it, we'll update this Privacy Notice first."]}, {"heading": "8. How long do we keep your information?", "paragraphs": ["In Short: We keep your information for as long as necessary to fulfill the purposes outlined in this Privacy Notice unless otherwise required by law.", "We will only keep your personal information for as long as it is necessary for the purposes set out in this Privacy Notice, unless a longer retention period is required or permitted by law (such as tax, accounting, or other legal requirements). No purpose in this notice will require us keeping your personal information for longer than the period of time in which users have an account with us. Section 16 lists how long we keep each kind of information.", "When we have no ongoing legitimate business need to process your personal information, we will either delete or anonymize such information, or, if this is not possible (for example, because your personal information has been stored in backup archives), then we will securely store your personal information and isolate it from any further processing until deletion is possible."]}, {"heading": "9. How do we keep your information safe?", "paragraphs": ["In Short: We aim to protect your personal information through a system of organizational and technical security measures.", "We have implemented appropriate and reasonable technical and organizational security measures designed to protect the security of any personal information we process. For example, connections use HTTPS, and access rules in our database let each account read only its own data.", "Passwords and profile PINs are kept only as one-way hashes. You can turn on two-step sign-in or log in with a passkey, staff can see only what their role needs, and every support lookup is recorded.", "However, despite our safeguards and efforts to secure your information, no electronic transmission over the Internet or information storage technology can be guaranteed to be 100% secure, so we cannot promise or guarantee that hackers, cybercriminals, or other unauthorized third parties will not be able to defeat our security and improperly collect, access, steal, or modify your information.", "Although we will do our best to protect your personal information, transmission of personal information to and from our Services is at your own risk. You should only access the Services within a secure environment."]}, {"heading": "10. Do we collect information from minors?", "paragraphs": ["In Short: We do not knowingly collect data from or market to children under 18 years of age or the equivalent age as specified by law in your jurisdiction, except through Kids profiles that a parent or guardian creates on their own account.", "Account holders must be 18 or older. We do not knowingly collect, solicit data from, or market to children under 18 years of age or the equivalent age as specified by law in your jurisdiction, nor do we knowingly sell such personal information.", "By using the Services, you represent that you are at least 18 or the equivalent age as specified by law in your jurisdiction or that you are the parent or guardian of such a minor and consent to such minor dependent's use of the Services through a Kids profile. The Children's Privacy Notice explains what Kids profiles keep.", "If we learn that personal information from users less than 18 years of age or the equivalent age as specified by law in your jurisdiction has been collected without that consent, we will deactivate the account and take reasonable measures to promptly delete such data from our records. If you become aware of any such data, please contact us at usprivacy@literaryworm.com."]}, {"heading": "11. What are your privacy rights?", "paragraphs": ["In Short: Depending on your state of residence in the US or in some regions, such as the European Economic Area (EEA), United Kingdom (UK), Switzerland, and Canada, you have rights that allow you greater access to and control over your personal information. You may review, change, or terminate your account at any time, depending on your country, province, or state of residence.", "In some regions (like the EEA, UK, Switzerland, and Canada), you have certain rights under applicable data protection laws.", "These may include the right (i) to request access and obtain a copy of your personal information, (ii) to request rectification or erasure; (iii) to restrict the processing of your personal information; (iv) if applicable, to data portability; and (v) not to be subject to automated decision-making.", "If a decision that produces legal or similarly significant effects is made solely by automated means, we will inform you, explain the main factors, and offer a simple way to request human review. In certain circumstances, you may also have the right to object to the processing of your personal information. You can make such a request by contacting us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below.", "We will consider and act upon any request in accordance with applicable data protection laws.", "If you are located in the UK and are unhappy with how we have handled your personal information, you can make a complaint directly to us at usprivacy@literaryworm.com. This is in addition to the rights you have under the UK General Data Protection Regulation and the Data Protection Act 2018.", "What happens after you complain: we will acknowledge your complaint within 30 days of receiving it, investigate without unjustifiable or excessive delay, keep you informed of progress and explain the outcome.", "If you are not happy with our final response, you can refer your complaint to the Information Commissioner's Office, the UK supervisory authority. Website: ico.org.uk/make-a-complaint. Helpline: 0303 123 1113. Post: Information Commissioner's Office, Wycliffe House, Water Lane, Wilmslow, Cheshire, SK9 5AF.", "If you are located in the EEA or UK and you believe we are unlawfully processing your personal information, you also have the right to complain to your Member State data protection authority or UK data protection authority.", "If you are located in Switzerland, you may contact the Federal Data Protection and Information Commissioner.", "Withdrawing your consent: If we are relying on your consent to process your personal information, which may be express and/or implied consent depending on the applicable law, you have the right to withdraw your consent at any time. You can withdraw your consent at any time in Account (for marketing emails and Kids profiles) or by contacting us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below.", "However, please note that this will not affect the lawfulness of the processing before its withdrawal nor, when applicable law allows, will it affect the processing of your personal information conducted in reliance on lawful processing grounds other than consent.", "Opting out of marketing and promotional communications: You can unsubscribe from our marketing and promotional communications at any time by turning off marketing emails in Account, by clicking on the unsubscribe link in the emails that we send, or by contacting us.", "We may still communicate with you, for example to send you service-related messages that are necessary for the administration and use of your account (each kind of email can be turned off in Account → Preferences, and the monthly What's new email, the weekly Kids reading report, book club meeting emails and club post emails also have a one-click unsubscribe link that works without signing in), to respond to service requests, or for other non-marketing purposes.", "Account Information. If you would at any time like to review or change the information in your account or terminate your account, you can log in and go to Account. There you can change your details, download a copy of your data, and delete profiles or your whole account. Deleting your account deletes its information from our databases straight away; copies in our providers' backups are removed when those backups expire.", "Cookies and similar technologies: we use only essential cookies, so declining cookies in Consent Preferences changes nothing about how the Services work. Blocking third-party cookies in your browser stops Google's cookies, and LiteraryWorm keeps working.", "Clearing LiteraryWorm's site data signs you out and removes books saved for offline. The Cookie Policy explains each one.", "If you have questions or comments about your privacy rights, you may email us at usprivacy@literaryworm.com."]}, {"heading": "12. Controls for Do-Not-Track features", "paragraphs": ["Most web browsers and some mobile operating systems and mobile applications include a Do-Not-Track (\"DNT\") feature or setting you can activate to signal your privacy preference not to have data about your online browsing activities monitored and collected. At this stage, no uniform technology standard for recognizing and implementing DNT signals has been finalized.", "As such, we do not currently respond to DNT browser signals. We do honour Global Privacy Control, described below. We don't track you across other websites in any case. If a standard for online tracking is adopted that we must follow in the future, we will inform you about that practice in a revised version of this Privacy Notice.", "California law requires us to let you know how we respond to web browser DNT signals. Because there currently is not an industry or legal standard for recognizing or honoring DNT signals, we do not respond to them at this time.", "Global Privacy Control: We recognize and honor Global Privacy Control (GPC) signals. If you use a browser or extension that supports GPC, we will treat this as a valid request to opt out of the sale or sharing of your personal information for targeted advertising purposes under applicable state privacy laws, including the California Consumer Privacy Act (CCPA).", "We don't sell or share personal information, so nothing more needs to change for you. For more information about GPC and how to enable it, visit globalprivacycontrol.org."]}, {"heading": "13. Do United States residents have specific privacy rights?", "paragraphs": ["In Short: If you are a resident of California, Colorado, Connecticut, Delaware, Florida, Indiana, Iowa, Kentucky, Maryland, Minnesota, Montana, Nebraska, New Hampshire, New Jersey, Oregon, Rhode Island, Tennessee, Texas, Utah, or Virginia, you may have the right to request access to and receive details about the personal information we maintain about you and how we have processed it, correct inaccuracies, get a copy of, or delete your personal information.", "You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law. More information is provided below.", "Categories of Personal Information We Collect. These are the categories of personal information we have collected in the past twelve (12) months. For a full list of what we process, see sections 1 and 18.", "A. Identifiers (such as name, alias, online identifier, Internet Protocol address, email address, and account name): YES. Your email address, display name, account id, and IP address in our providers' logs.", "B. Personal information as defined in the California Customer Records statute (name, contact information, education, employment, employment history, and financial information): YES, your display name and email address only.", "C. Protected classification characteristics under state or federal law (gender, age, date of birth, race and ethnicity, national origin, marital status, and other demographic data): YES, your date of birth only, to confirm you're 18 or over.", "D. Commercial information (transaction information, purchase history, financial details, and payment information): YES. Your plan, billing day and payment history (amounts, dates and whether each payment succeeded), gift memberships you bought or redeemed (plan, months, price and when redeemed), with Stripe's ids for your customer record and subscription. Card details are held by Stripe, not us.", "E. Biometric information (fingerprints and voiceprints): NO.", "F. Internet or other similar network activity (browsing history, search history, online behavior, interest data, and interactions with our and other websites, applications, systems, and advertisements): YES, within LiteraryWorm only: your searches and reading activity on our Services. Not your activity on other websites.", "G. Geolocation data (device location): NO.", "H. Audio, electronic, sensory, or similar information (images and audio, video or call recordings): NO.", "I. Professional or employment-related information: NO.", "J. Education Information (student records and directory information): NO.", "K. Inferences drawn from collected personal information (a profile or summary of an individual's preferences and characteristics): YES. Book recommendations, worked out in your browser from your own reading and not used for advertising.", "L. Sensitive personal information: YES, account login information only. No biometric data.", "We will use and retain the personal information in each category for as long as the user has an account with us.", "We only collect sensitive personal information, as defined by applicable privacy laws or the purposes allowed by law or with your consent. Sensitive personal information may be used, or disclosed to a service provider or contractor, for additional, specified purposes. You may have the right to limit the use or disclosure of your sensitive personal information. We do not collect or process sensitive personal information for the purpose of inferring characteristics about you.", "We may also collect other personal information outside of these categories when you receive help through our customer support channels, or to deliver our Services and respond to your inquiries.", "Sources of Personal Information. See section 1. How We Use and Share Personal Information. See sections 2 and 4.", "Will your information be shared with anyone else? We may disclose your personal information with our service providers pursuant to a written contract between us and each service provider. See section 4.", "We have not disclosed, sold, or shared any personal information to third parties for a business or commercial purpose in the preceding twelve (12) months. We will not sell or share personal information in the future belonging to website visitors, users, and other consumers.", "Your Rights. You have rights under certain US state data protection laws. However, these rights are not absolute, and in certain cases, we may decline your request as permitted by law.", "These rights include:", "the right to know whether or not we are processing your personal data;", "to access your personal data;", "to correct inaccuracies in your personal data;", "to request the deletion of your personal data;", "to obtain a copy of the personal data you previously shared with us;", "to non-discrimination for exercising your rights;", "and to opt out of the processing of your personal data if it is used for targeted advertising (or sharing as defined under California's privacy law), the sale of personal data, or profiling in furtherance of decisions that produce legal or similarly significant effects (\"profiling\").", "Depending upon the state where you live, you may also have the right:", "to access the categories of personal data being processed (including in Minnesota);", "to obtain a list of the categories of third parties to which we have disclosed personal data (including in California, Delaware, and Maryland);", "to obtain a list of specific third parties to which we have disclosed personal data (including in Minnesota and Oregon);", "to obtain a list of third parties to which we have sold personal data (including in Connecticut);", "to review, understand, question, and depending on where you live, correct how personal data has been profiled (including in Connecticut and Minnesota);", "to limit use and disclosure of sensitive personal data (including in California);", "and to opt out of the collection of sensitive data and personal data collected through the operation of a voice or facial recognition feature (including in Florida).", "How to Exercise Your Rights. To exercise these rights, you can use Account (to download, change or delete your data), email us at usprivacy@literaryworm.com, or use the contact details at the bottom of this document. We will honor your opt-out preferences if you enact the Global Privacy Control (GPC) opt-out signal on your browser.", "Under certain US state data protection laws, you can designate an authorized agent to make a request on your behalf. We may deny a request from an authorized agent that does not submit proof that they have been validly authorized to act on your behalf in accordance with applicable laws.", "Request Verification. Upon receiving your request, we will need to verify your identity to determine you are the same person about whom we have the information in our system. We will only use personal information provided in your request to verify your identity or authority to make the request.", "However, if we cannot verify your identity from the information already maintained by us, we may request that you provide additional information for the purposes of verifying your identity and for security or fraud-prevention purposes.", "If you submit the request through an authorized agent, we may need to collect additional information to verify your identity before processing your request and the agent will need to provide a written and signed permission from you to submit such request on your behalf.", "Appeals. Under certain US state data protection laws, if we decline to take action regarding your request, you may appeal our decision by emailing us at usprivacy@literaryworm.com. We will inform you in writing of any action taken or not taken in response to the appeal, including a written explanation of the reasons for the decisions. If your appeal is denied, you may submit a complaint to your state attorney general.", "California \"Shine The Light\" Law. California Civil Code Section 1798.83, also known as the \"Shine The Light\" law, permits our users who are California residents to request and obtain from us, once a year and free of charge, information about categories of personal information (if any) we disclosed to third parties for direct marketing purposes and the names and addresses of all third parties with which we shared personal information in the immediately preceding calendar year.", "We don't disclose personal information to third parties for their direct marketing. If you are a California resident and would like to make such a request, please submit your request in writing to us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below."]}, {"heading": "14. Do other regions have specific privacy rights?", "paragraphs": ["In Short: You may have additional rights based on the country you reside in.", "Australia and New Zealand. We collect and process your personal information under the obligations and conditions set by Australia's Privacy Act 1988 and New Zealand's Privacy Act 2020 (Privacy Act).", "This Privacy Notice satisfies the notice requirements defined in both Privacy Acts, in particular: what personal information we collect from you, from which sources, for which purposes, and other recipients of your personal information.", "If you do not wish to provide the personal information necessary to fulfill their applicable purpose, it may affect our ability to provide our services, in particular to offer you the products or services that you want, respond to or help with your requests, manage your account with us, and confirm your identity and protect your account.", "At any time, you have the right to request access to or correction of your personal information. You can make such a request by contacting us by using the contact details provided in section 20.", "If you believe we are unlawfully processing your personal information, you have the right to submit a complaint about a breach of the Australian Privacy Principles to the Office of the Australian Information Commissioner and a breach of New Zealand's Privacy Principles to the Office of New Zealand Privacy Commissioner.", "Republic of South Africa. At any time, you have the right to request access to or correction of your personal information. You can make such a request by contacting us by using the contact details provided in section 20.", "If you are unsatisfied with the manner in which we address any complaint with regard to our processing of personal information, you can contact the office of the regulator, the Information Regulator (South Africa). General enquiries: enquiries@inforegulator.org.za. Complaints (complete POPIA/PAIA form 5): PAIAComplaints@inforegulator.org.za and POPIAComplaints@inforegulator.org.za."]}, {"heading": "15. Licensing and selling your information", "paragraphs": ["We don't sell, rent or license your personal information, and we don't share it for advertising. We use it only to run LiteraryWorm for you.", "Content you post (reading logs and club posts) stays yours. The Terms of Service explain the limited licence you give us to show it where you posted it.", "We don't use your reading history, notes, uploads or posts to train AI models."]}, {"heading": "16. How long we keep each kind of information", "paragraphs": ["We keep your information while your account is open, and some of it for less time, as this list shows.", "Your account, household and reading: until you delete them. Deleting a profile deletes its data, including its uploaded books.", "Deleting your account deletes everything at once, including your uploads; public logs and club posts go with it. Copies in our providers' backups go when those backups expire.", "Counts of requests, kept to protect the service from abuse and keyed by a one-way hash of your account or network address: cleared within a day.", "A gift recipient's email address and the buyer's message: until the gift email has gone.", "The one-way fingerprint of an address you invited to a book club: 30 days. New books we find by authors you follow: 60 days.", "The record of each support lookup: a year. Your cookie choice, kept in your browser by Termly: up to 12 months.", "Notifications on a device: until you turn them off there or log out on it."]}, {"heading": "17. Your choices and rights", "paragraphs": ["In Account you can download a copy of your data, change your display name, choose which emails and notifications you get, and delete profiles or your whole account. The Your Privacy Choices page sums these up. You can remove any log, post, highlight or upload yourself.", "You can also use the request form linked at the bottom of every page (Do Not Sell or Share My Personal information; Limit the Use Of My Sensitive Personal Information), provided by Termly.", "We honour Global Privacy Control. Children's data is covered by the Children's Privacy Notice, and what we keep in your browser by the Cookie Policy."]}, {"heading": "18. What we collect", "paragraphs": ["Your account: your email address, display name, password, date of birth (to confirm you're 18 or over), when you accepted the Terms, and your plan.", "Your email choices: marketing emails, emails when a book you set Remind me on is out, weekly emails about new books from authors you follow, and book club meeting emails (reminders, and when a meeting moves or is cancelled; on until you turn them off).", "The monthly What's new email, the weekly Kids reading report and the daily email of new club posts are off until you turn them on.", "Your password is handled by our sign-in provider and kept only as a one-way hash; we never see it. If you add passkeys, our sign-in provider keeps each one's public key, its name and when it was added and last used; the private key stays on your device, browser or password manager, and your face or fingerprint never leaves your device.", "You can rename or remove passkeys in Account → Sign-in, and Download my data lists them. If you use two-step sign-in, we also note which passkeys were added after you entered your code, so logging in with one of them doesn't ask for the code again.", "If you turn on notifications on a device, we keep that browser's push address and keys, a name for the device (like Chrome on Windows) and when it last got a notification, until you turn them off there or log out on it. Grown-up and teen profiles can put catalog books on a family shelf for the household; we keep which books, which profile added each and when, until they're taken off or the account is deleted.", "In a book club, if you turn on Show my place to this club, its members see the chapter you've reached in the club's book, how far through it you are and when you last read; turning it off hides it again.", "If you share one of your highlights with a book club, its members see the passage, its chapter and colour, your display name and, if you choose, your note, until you stop sharing it, delete the highlight or leave the club.", "Your household: each profile's name, avatar, age rating, favourite genres, daily limit, weekly goal, bedtime and wake-up time (Kids profiles) and player settings, the app language it chose, and whether it's set aside. A profile PIN is kept only as a one-way hash. For Kids profiles, we keep a record of the parent's consent, and the books a Kids profile asks a grown-up for, with the answer.", "Your reading: your library, reading progress, bookmarks, highlights and notes (with when each highlight is next due for review).", "What you keep about books: the words you save from the dictionary (with the sentence you met them in and when each is next due for review), your private reading journal (dated entries about a book that only your account sees), ratings, the moods and pace you tag books with, favourites and lists, and your Up next queue.", "Who and what you follow: the authors and narrators you follow (their pages show how many readers follow them, never who; and, for 60 days, the new books we find by the authors you follow), release reminders and recent searches.", "Your goals and time: reading goals, the household challenges your profiles start or join, time read and listened each day, and the time each profile spends with each book on each day and where in the book the day started and ended (for the book page's Your time with this book).", "Reading sprints: when a sprint started and how long it ran, which of your profiles joined, and the pages each turned in the reader during it, kept for 90 days. A household sees its profiles' names; in a book club, members see each other's display names and pages, never which profile read.", "Invitations: your invitation code, and for each friend who signed up with it, who invited them, when, and the month credited to each of you (with Stripe's reference for the credit). You see how many friends signed up and how many months you've earned, never who they are; a friend sees only their own month.", "Your plans and progress: reading plans (the day a profile chose to finish a book by, and where it was in the book when the plan started), your reading pace (words a minute, used to show the time left in a chapter), chapter quiz scores, and the books you finish.", "If you turn on your reader page (it's off until you do), the reading logs you've already made public are listed together on one public page under your display name, and other members can follow it; who follows whom is never shown, and turning the page off removes its followers. Exports of your highlights and notes are made in your browser and downloaded to your device; they're never uploaded.", "So are library exports for Goodreads and StoryGraph (a CSV of your books, shelves, star ratings, dates, and the moods and pace you tagged); we don't send them to either site. Audio clips you share are links to a stretch of a public-domain LibriVox recording, played from the Internet Archive; we don't record or keep them, or who shared them.", "Things you share or add: reading logs (public, with your display name), book club posts, whether you're coming to a club's meetings and your votes in its polls (seen by the club's members), lists you choose to share by link, and books you upload (private to the profile that added them; we keep their text, title, author and the year the file says it was published, never the file itself; if you start a book club around one, the club's members see its title and author, never its text).", "Devices: while you're signed in, a short label for each browser you use the app in (such as \"Chrome on Windows\") so you can send a book to another device. For each device that keeps books with Read offline, the same kind of label and when it was last used, so your plan's offline devices can be counted and you can free one.", "LiteraryWorm never asks for access to your local network (the other devices on your home Wi-Fi) and doesn't need it for anything, including Listen on another device and playing on a speaker or TV. If your browser asks, choose Block.", "Voice control in car mode: off until you turn it on, and not offered to Kids profiles. While car mode is open and on screen, your browser listens through the microphone and its own speech service turns what you say into words (Google's in Chrome and Edge, Apple's in Safari), under that company's terms. The app only reads the words for a command: we never get the sound, and we keep nothing."]}, {"heading": "19. Do we make updates to this notice?", "paragraphs": ["In Short: Yes, we will update this notice as necessary to stay compliant with relevant laws.", "We may update this Privacy Notice from time to time. The updated version will be indicated by an updated \"Last updated\" date at the top of this Privacy Notice. If we make material changes to this Privacy Notice, we may notify you either by prominently posting a notice of such changes or by directly sending you a notification. We encourage you to review this Privacy Notice frequently to be informed of how we are protecting your information."]}, {"heading": "20. How can you contact us about this notice?", "paragraphs": ["If you have questions or comments about this notice, you may email us at usprivacy@literaryworm.com."]}, {"heading": "21. How can you review, update, or delete the data we collect from you?", "paragraphs": ["Based on the applicable laws of your country or state of residence in the US, you may have the right to request access to the personal information we collect from you, details about how we have processed it, correct inaccuracies, or delete your personal information. You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law.", "To review, update, or delete your personal information, go to Account, where you can download a copy of your data, change it, or delete it, or email us at usprivacy@literaryworm.com."]}]$lw$::jsonb),
  ($lw$cookies$lw$, 2, $lw$Cookie Policy$lw$, $lw$What LiteraryWorm keeps in your browser, the few cookies set when you use it, and how to control them. We use no advertising or analytics cookies.$lw$, $lw$[{"heading": "In short", "paragraphs": ["We use no advertising or analytics cookies, and we don't track you across other websites.", "If you allow analytics in the consent banner, Ahrefs Web Analytics counts the pages you visit without setting cookies. It never runs for Kids profiles.", "Two kinds of cookie are set when you use LiteraryWorm, both by other companies: Cloudflare's bot check on our backend, and Google's cookies from books.google.com when Google Books covers and previews load.", "Your browser also keeps your sign-in, which device it is, your cookie choice, the app's own files and any books you save for offline. The list below says what each one is and how long it stays."]}, {"heading": "About this policy", "paragraphs": ["This Cookie Policy covers cookies and the similar things your browser keeps for LiteraryWorm, such as local storage and the app's offline caches. The Privacy Policy explains how we use the information itself.", "Some of what your browser keeps, such as your sign-in session, is linked to your account, so we treat it as personal information."]}, {"heading": "What are cookies?", "paragraphs": ["Cookies are small data files that are placed on your computer or mobile device when you visit a website. Cookies are widely used by website owners in order to make their websites work, or to work more efficiently, as well as to provide reporting information.", "Cookies set by the website owner (in this case, LiteraryWorm) are called \"first-party cookies.\" Cookies set by parties other than the website owner are called \"third-party cookies.\" Third-party cookies enable third-party features or functionality to be provided on or through the website (e.g., advertising, interactive content, and analytics).", "The parties that set these third-party cookies can recognize your computer both when it visits the website in question and also when it visits certain other websites."]}, {"heading": "Everything at a glance", "paragraphs": ["Here is everything that's set or kept in your browser when you use LiteraryWorm, who sets it and how long it stays. Each is explained further down.", "__cf_bm (a cookie, set by Cloudflare on .supabase.co, our backend): keeps out bots. Stays 30 minutes.", "Google's cookies (set by Google on books.google.com): set when Google Books covers and previews load, because we use the Google Books API. Google decides how long they stay; we can't read them.", "literaryworm-session (local storage): keeps you signed in. Stays until you log out.", "literaryworm-device (local storage): which of your devices this browser is, as a random id and your account id. Stays until you log out.", "TERMLY_API_CACHE (local storage, kept by Termly): your cookie choice. Stays up to 12 months.", "The app's files (the lw-shell cache): so the app opens quickly and offline. Replaced when the app updates.", "Books saved for offline (the lw-books cache): stay until you remove them, with a small note of your offline place and any listening schedule.", "Books you uploaded and opened, or searched by keywords (the lw-uploads cache): stay until you delete the book or log out.", "A push subscription, only if you turn on notifications on this device: stays until you turn them off or log out."]}, {"heading": "Why do we use cookies?", "paragraphs": ["Some cookies are required for technical reasons in order for our Website to operate, and we refer to these as \"essential\" or \"strictly necessary\" cookies. LiteraryWorm uses only essential cookies and similar technologies, including the third-party cookies Google sets from books.google.com when Google Books covers and previews load, because we use the Google Books API.", "We don't use cookies to track or target your interests, and we don't let third parties serve cookies through our Website for advertising or analytics. This is described in more detail below."]}, {"heading": "How can I control cookies?", "paragraphs": ["You have the right to decide whether to accept or reject cookies. Essential cookies cannot be rejected as they are strictly necessary to provide you with services.", "When you first visit, a banner from Termly, our consent provider, asks for your choice, and you can change it at any time with Consent Preferences at the bottom of every page. LiteraryWorm uses only essential cookies, so declining changes nothing about how the site works: book covers, audiobooks and your account work either way. If we ever add cookies that aren't essential, they'll only be used with your consent, and we'll update this page.", "You may also set or amend your web browser controls to accept or refuse cookies. Blocking third-party cookies stops Google's cookies, and LiteraryWorm keeps working. Clearing LiteraryWorm's site data signs you out and removes books saved for offline.", "The cookies set when you use our Website, and what each one does, are described below. Which ones are set can depend on the pages you visit: Google's, for example, only when a Google Books cover or preview loads."]}, {"heading": "Essential website cookies", "paragraphs": ["These cookies are strictly necessary to provide you with services available through our Website and to use some of its features, such as access to secure areas.", "__cf_bm. Purpose: Cloudflare places the cookie on end-user devices that access customer sites protected by Bot Management or Bot Fight Mode. Provider: .supabase.co (our backend, Supabase, which is protected by Cloudflare). Service: Cloudflare (see Cloudflare's privacy policy). Type: server cookie. Expires in: 30 minutes.", "Google Books cookies. Purpose: LiteraryWorm uses the Google Books API to find books and show their details. So the covers of books from Google Books, and the Google Books preview on some book pages (only when you open it), load in your browser from books.google.com, and Google sets and reads its own third-party cookies there.", "Provider: books.google.com (Google). Service: Google Books (see Google's Privacy Policy at policies.google.com/privacy). Type: third-party cookies, set by Google, not by LiteraryWorm; we can't read them.", "We mark Google Books covers and the preview as essential, so they show even if you decline other cookies in Consent Preferences. To stop Google's cookies, block third-party cookies in your browser's settings: LiteraryWorm keeps working, and covers still show. Kids profiles show only LiteraryWorm's own titles, so they don't load Google Books.", "The audiobook recordings streamed from the Internet Archive load from that service too, and it may set or read its own cookies under its own policy."]}, {"heading": "Similar technologies: what we keep in your browser", "paragraphs": ["Signed in: when you log in, your browser keeps your sign-in session (in local storage, under literaryworm-session) so you stay signed in after a refresh. It's strictly necessary for your account to work, and it's removed when you log out.", "Next to it the app keeps which of your devices this browser is (under literaryworm-device: a random id and your account's id, nothing else), so a refresh or a second tab isn't listed as a new device in Listen on another device; it's removed when you log out too. Passkeys you add are kept by your device, browser or password manager, not by LiteraryWorm in your browser's storage, and logging out doesn't remove them.", "Your cookie choice: Termly keeps the choice you make in the banner, a random identifier for this browser and a count of visits in local storage (under TERMLY_API_CACHE), for up to 12 months, so the banner doesn't ask again on every visit. It sets no cookies. Your browser loads the banner from Termly (app.termly.io) on each visit, so Termly receives those requests, including your IP address, under its own privacy policy.", "The app itself: so LiteraryWorm opens quickly and without a connection, your browser keeps a copy of the app's own files (its pages, code, icons and app manifest). This holds nothing about you. If you turn on notifications in Account → Preferences, your browser also keeps a push subscription for LiteraryWorm; turning them off or logging out removes it.", "Books you save for offline: when you choose Read offline, the book's text, and its audio if you ask, are kept on your device until you remove them from the book's page.", "If you turn on Listen offline on a schedule for an audiobook, the app also keeps a small note of that choice (how many chapters, Wi-Fi only, whether to remove finished ones) with the books, and saves or removes chapters as you listen; it goes when you turn it off or the books are cleared.", "Next to them the app keeps a small note of which account's offline place this device holds (a random id, not your name or email), so the place can be freed from another device; it goes when the books do.", "Books you upload: once you've opened one, or searched your uploads by keywords, its text is kept on that device so it keeps working if your connection drops. It's removed when you delete the book or log out.", "Everything else, such as reader settings, playback speed, the demo household and uploads made in the demo, stays in the open tab only and is gone when you refresh or close it.", "Your library, reading progress, bookmarks, highlights, saved words, lists, Up next queue, ratings, reading time and pace, quiz scores, player settings, club activity and uploaded books are saved with your account on our servers (Supabase), not in browser cookies. The Privacy Policy says how we use them, and Account lets you download or delete them.", "Listening on a speaker or TV uses your browser's own Chromecast or AirPlay picker: it loads no script, sets no cookie and keeps nothing in your browser, and the speaker plays the recording straight from the Internet Archive."]}, {"heading": "What else your browser loads from other sites", "paragraphs": ["Some parts of LiteraryWorm load straight from other companies' servers, so your browser sends them requests, with your IP address, and they handle them under their own policies.", "Google Fonts (fonts.googleapis.com and fonts.gstatic.com) serves the app's typefaces. Google Books (books.google.com) serves covers and the preview, and sets the cookies described above.", "The Internet Archive (archive.org) streams LibriVox recordings and audio clips. Termly (app.termly.io) serves the consent banner.", "When you pay, you go to Stripe's own checkout page, where Stripe sets its own cookies under its privacy policy. We never see your card details.", "OpenDyslexic, the reading font, is part of the app itself, so choosing it sends nothing to anyone.", "Ahrefs (analytics.ahrefs.com) serves our visit counter, which loads only if you allow analytics. It sets no cookies and keeps nothing in your browser, and it's off for Kids profiles and on pages whose links carry codes. The Privacy Policy, section 4, says what it receives."]}, {"heading": "Do my choices apply on all my devices?", "paragraphs": ["No. Cookie settings you make in your browser, and anything you clear there, apply to that browser on that device only. You'll need to make them again on a different device or browser, and a private or incognito window deletes what it kept when you close it.", "Clearing LiteraryWorm's site data signs you out, and books saved for offline will need saving again."]}, {"heading": "How can I control cookies on my browser?", "paragraphs": ["As the means by which you can refuse cookies through your web browser controls vary from browser to browser, you should visit your browser's help menu for more information.", "That's true of the most popular browsers: Chrome, Firefox, Safari, Edge and Opera. In each, you can block third-party cookies for every site, or clear the cookies and site data of one site.", "We don't use advertising networks, so there's nothing to opt out of here. If you'd like to opt out of targeted advertising elsewhere, most advertising networks offer a way to: see the Digital Advertising Alliance, the Digital Advertising Alliance of Canada or the European Interactive Digital Advertising Alliance."]}, {"heading": "Local network access", "paragraphs": ["Your browser may ask whether LiteraryWorm can reach devices on your local network, such as others on your home Wi-Fi.", "Choose Block: the app never needs it, and allowing it can stop logging in from working in that browser. If you allowed it, turn it off in the site's settings (in Chrome and Edge, select the icon beside the address, then Site settings, and set Local network access to Block)."]}, {"heading": "What about other tracking technologies, like web beacons?", "paragraphs": ["Cookies are not the only way to recognize or track visitors to a website. Web beacons (sometimes called \"tracking pixels\" or \"clear gifs\") are tiny graphics files that contain a unique identifier that lets a website recognize when someone has visited it or opened an email including them.", "LiteraryWorm doesn't use web beacons or tracking pixels on the Website or in its emails. We send our emails with Mailgun's open and click tracking turned off."]}, {"heading": "Do you serve targeted advertising?", "paragraphs": ["No. We don't serve advertising on our Website, and we don't allow third parties to place cookies or web beacons on your computer or mobile device through our Website to serve or measure advertising. Google's cookies from books.google.com are set under Google's own policies; we don't use them, and we don't receive them."]}, {"heading": "How often will you update this Cookie Policy?", "paragraphs": ["We may update this Cookie Policy from time to time in order to reflect, for example, changes to the cookies we use or for other operational, legal, or regulatory reasons. Please therefore revisit this Cookie Policy regularly to stay informed about our use of cookies and related technologies.", "The Last updated date at the top of this Cookie Policy shows when it last changed. When a change matters, we'll also say so on What's new."]}, {"heading": "Where can I get further information?", "paragraphs": ["If you have any questions about our use of cookies or other technologies, please email us at support@literaryworm.com. For privacy requests, email usprivacy@literaryworm.com."]}]$lw$::jsonb),
  ($lw$childrens-privacy$lw$, 3, $lw$Children's Privacy Notice$lw$, $lw$For parents and guardians: what a Kids profile collects, why, who can see it, what we never collect, and how you stay in control. A Kids profile exists only with your consent, and you can see, download or delete everything it keeps.$lw$, $lw$[{"heading": "In short", "paragraphs": ["A Kids profile lives inside your account. Only you, the account holder, can create one, and only after you consent.", "It keeps what it needs to work: a first name or nickname, an avatar and the child's reading. We never ask a child for an email address, full name, photo, location or any way to contact them.", "Its reading is private to your account. It isn't shown to other members, it isn't used for advertising, and it is never sold, rented or licensed.", "You can see it, download it, change its limits or delete it at any time from Account."]}, {"heading": "Your consent comes first", "paragraphs": ["Only the account holder, who must be 18 or older, can create a Kids profile or move a profile to Kids. You do it after reading this notice, and you confirm it with the account password.", "We keep a record of that consent: when it was given, how, and which version of this notice it was for.", "Moving the profile to another age rating, or deleting it, withdraws that consent, and we record that too."]}, {"heading": "What a Kids profile collects", "paragraphs": ["The profile: its first name or nickname, its avatar, its age rating, and any daily reading limit, weekly reading goal and bedtime you set.", "Its reading: the books in its library, where it is in each book, its bookmarks, highlights and notes, its Up next queue, ratings, the moods and pace it tags books with, favourites and lists, the authors and narrators it follows, and its release reminders.", "Its time: how long it reads and listens each day, in total and for each book (shown on the book's page), the books it finishes, its reading goals and pace, and any reading plan it makes (the day it chose to finish by and where it was when the plan started).", "Its learning: the words it saves from the dictionary and when they're next due for review, its private reading journal, and its chapter quiz scores.", "Its family activity: the books it asks a grown-up for and your answers, the household challenges it starts or joins, and the reading sprints it joins at home with the pages it turned (kept 90 days), which the other profiles on your account can see. Kids profiles can't join a book club's sprints.", "Badges are worked out on the device from this reading and are never stored. Books saved for offline reading stay on that device."]}, {"heading": "What we never collect", "paragraphs": ["We don't ask a child for their email address, full name, home address, school, phone number, photo, voice, location or any other way to contact them.", "A Kids profile can't write anything that other members see, so it can't share personal details with them.", "There's no advertising on LiteraryWorm and no advertising trackers. Our visit counter, Ahrefs Web Analytics, is switched off while a Kids profile is in use, so nothing a child does there is sent to it.", "Kids profiles show only LiteraryWorm's own titles, so Google Books covers and previews, and the third-party cookies Google sets from books.google.com with them, don't load there."]}, {"heading": "What a Kids profile can't do", "paragraphs": ["Kids profiles see only books rated for children. A grown-up can say yes to a book above that rating when the child asks for it.", "They can't write public reading logs, join or start book clubs, follow other readers, share lists by link, upload or import books, search Google Books, ask the book's AI assistant, translate passages or use Who's who.", "They can't make purchases or change account settings. A grown-up's password is needed to open Account or to allow extra time past a daily limit."]}, {"heading": "AI features", "paragraphs": ["A Kids profile can read AI-written book summaries and content notes, hear a recap of earlier chapters (Previously…) and take chapter quizzes. These are written by Claude, made by Anthropic.", "Kids profiles aren't offered voice control in car mode, because what's said would go to the browser's speech service (Google's or Apple's). Car mode's buttons work as usual.", "We send Anthropic only the book's details or its own text and which chapter it's about, never the child's name, answers, scores or anything else about them. The summaries, content notes, recaps and quizzes are kept and shared with every reader of that book, so they say nothing about who asked."]}, {"heading": "Who sees it", "paragraphs": ["You do: Account → Family shows each Kids profile's last 7 days, its weekly goal, its book requests and its quiz scores.", "If you turn on the weekly Kids reading report, we email last week's reading to your account's email address. Mailgun sends it for us. It's off until you turn it on.", "Our hosting providers, Supabase and Vercel, store and serve it only to run LiteraryWorm for you.", "Our support team can see how many profiles an account has, but not a profile's name, library, reading, notes or journal."]}, {"heading": "How long we keep it", "paragraphs": ["We keep a Kids profile's information for as long as the profile exists.", "Deleting the profile, or your whole account, deletes everything it collected from our database straight away. Copies in our providers' backups are removed when those backups expire."]}, {"heading": "Your choices as a parent", "paragraphs": ["From Account you can see the profile's activity, download a copy of your data, change its daily limit, weekly goal, bedtime and age rating, and answer its book requests.", "You can add a PIN to the other profiles so a child can't open them.", "You can stop us collecting anything more at any time by deleting the profile, which deletes everything it collected. Moving it to another age rating also ends the Kids protections, but keeps its reading under its new rating."]}, {"heading": "Keeping it safe", "paragraphs": ["A Kids profile's information is stored with access rules, so only your account can read it. Our support team can't see a profile's name, library or reading.", "You can protect the account with two-step sign-in or a passkey, and lock other profiles with a PIN, which we keep only as a one-way hash."]}, {"heading": "Changes to this notice", "paragraphs": ["We keep the version of this notice you agreed to with each Kids profile. If we change what a Kids profile collects, we'll update this notice and say so on What's new."]}, {"heading": "Questions", "paragraphs": ["If you have a question about your child's information, or think a child is using LiteraryWorm without a parent's consent, email usprivacy@literaryworm.com. We'll answer, and we'll delete information collected without consent.", "The Privacy Policy explains how we handle everyone's information, including your rights where you live."]}]$lw$::jsonb),
  ($lw$privacy-choices$lw$, 4, $lw$Your Privacy Choices$lw$, $lw$The choices you have about your information on LiteraryWorm. We don't sell it or share it for advertising, and you control your emails, notifications, cookies and data from Account.$lw$, $lw$[{"heading": "In short", "paragraphs": ["We don't sell, rent or license your personal information, and we don't share it for advertising. There's nothing to opt out of there, and Global Privacy Control is honoured.", "You decide which emails and notifications you get, what your browser keeps, what other members see, and whether your data stays. You can change each of these in Account at any time."]}, {"heading": "Selling and sharing", "paragraphs": ["We don't sell, rent or license your personal information, and we don't share it for cross-context behavioural advertising.", "If your browser sends a Global Privacy Control signal, we treat it as a request to opt out. Nothing changes, because we already don't do either."]}, {"heading": "Emails", "paragraphs": ["In Account → Preferences, turn each kind of email on or off: books you set Remind me on coming out, new books from authors you follow, club meeting reminders and changes, a daily email of new club posts, the weekly Kids reading report, the monthly What's new, and marketing emails. Several are off until you turn them on.", "Each of these emails has an unsubscribe link that works in one click. Emails about your account, such as confirming your address or resetting your password, always arrive."]}, {"heading": "Notifications on your devices", "paragraphs": ["Notifications on this device, in Account → Preferences, are off until you turn them on, and are set for each device. Choose which ones you get: books coming out, club meetings, new club posts up to your chapter, the evening streak nudge and answers to Kids book requests.", "Logging out on a device turns them off there. Each book club also has its own alerts switch on its page."]}, {"heading": "Cookies and browser storage", "paragraphs": ["We set no advertising or analytics cookies. Our backend's host, Cloudflare, sets one cookie to keep out bots, and Google sets third-party cookies from books.google.com when Google Books covers and previews load, because we use the Google Books API.", "Analytics: if you allow it in the consent banner, Ahrefs Web Analytics counts the pages you visit, without cookies. To turn it off, choose Consent Preferences at the bottom of any page and decline analytics. It never runs for Kids profiles.", "Change your cookie choice with Consent Preferences at the bottom of every page, and block third-party cookies in your browser to stop Google's. The Cookie Policy lists everything your browser keeps and how to clear it."]}, {"heading": "What other members see", "paragraphs": ["Your library, progress, notes, highlights, journal, moods and saved words are private to your household. Reading logs you publish show on the book's page with your display name.", "Your reader page, which gathers your public reading logs, is off until you turn it on, and turning it off removes its followers. In each book club, Show my place is off until you turn it on."]}, {"heading": "Your data", "paragraphs": ["In Account you can download a copy of your data, correct your display name, and delete profiles or your whole account.", "Reading logs, club posts, shared highlights, saved words, journal entries and uploads can each be deleted whenever you like. The Privacy Policy explains what we keep and for how long."]}, {"heading": "Questions", "paragraphs": ["Email usprivacy@literaryworm.com with any question about your privacy choices, or to make a request under the law where you live."]}]$lw$::jsonb),
  ($lw$terms$lw$, 5, $lw$Terms of Service$lw$, $lw$We are LiteraryWorm ("Company," "we," "us," "our"). We operate the website https://www.literaryworm.com (the "Site"), as well as any other related products and services that refer or link to these legal terms (the "Legal Terms") (collectively, the "Services"). These Legal Terms cover who can have an account, how membership works, what you may do with the books, who owns what, and the license you give us for what you post. You can contact us by email at support@literaryworm.com.$lw$, $lw$[{"heading": "Agreement to our legal terms", "paragraphs": ["These Legal Terms constitute a legally binding agreement made between you, whether personally or on behalf of an entity (\"you\"), and LiteraryWorm, concerning your access to and use of the Services. You agree that by accessing the Services, you have read, understood, and agreed to be bound by all of these Legal Terms. IF YOU DO NOT AGREE WITH ALL OF THESE LEGAL TERMS, THEN YOU ARE EXPRESSLY PROHIBITED FROM USING THE SERVICES AND YOU MUST DISCONTINUE USE IMMEDIATELY.", "Supplemental terms and conditions or documents that may be posted on the Services from time to time, such as our End User License Agreement (https://www.literaryworm.com/legal/eula), are hereby expressly incorporated herein by reference. We may change these Legal Terms from time to time. We'll tell you before changing them in ways that matter, and we'll update the \"Last updated\" date.", "You will be subject to, and will be deemed to have accepted, the changes in any revised Legal Terms by your continued use of the Services after the date such revised Legal Terms are posted.", "Account holders must be at least 18 years old. People under 18 may use the Services only through a profile, such as a Kids profile, that a parent or guardian adds to their own account and is responsible for.", "We recommend that you print a copy of these Legal Terms for your records."]}, {"heading": "In short", "paragraphs": ["This summary helps you find your way around these Legal Terms. It doesn't replace them.", "You must be 18 or older to have an account. Kids and Teen profiles are added by the account holder, who is responsible for them.", "Memberships renew monthly or yearly until you cancel. Cancel at least 48 hours before your billing date to stop the next charge, and know that payments are final (section 30 and the Return Policy).", "You may read and listen for yourself and your household, but not copy, share or sell the books (section 31).", "You own what you write, and you give us a licence only to show it where you posted it (section 33). Upload only books you have the right to read (section 34).", "Follow the Acceptable Use Policy. We may suspend or close accounts that break these Legal Terms (section 16).", "AI-written content is labelled and may be wrong, and the Services are provided as they are (sections 21 and 22). Disputes go to informal negotiation first (section 19)."]}, {"heading": "1. Our services", "paragraphs": ["The information provided when using the Services is not intended for distribution to or use by any person or entity in any jurisdiction or country where such distribution or use would be contrary to law or regulation or which would subject us to any registration requirement within such jurisdiction or country.", "Accordingly, those persons who choose to access the Services from other locations do so on their own initiative and are solely responsible for compliance with local laws, if and to the extent local laws are applicable.", "The Services are not tailored to comply with industry-specific regulations (Health Insurance Portability and Accountability Act (HIPAA), Federal Information Security Management Act (FISMA), etc.), so if your interactions would be subjected to such laws, you may not use the Services. You may not use the Services in a way that would violate the Gramm-Leach-Bliley Act (GLBA)."]}, {"heading": "2. Intellectual property rights", "paragraphs": ["Our intellectual property. We are the owner or the licensee of all intellectual property rights in our Services, including all source code, databases, functionality, software, website designs, audio, video, text, photographs, and graphics in the Services (collectively, the \"Content\"), as well as the trademarks, service marks, and logos contained therein (the \"Marks\"). Section 32 explains which books are in the public domain and who owns the rest.", "Our Content and Marks are protected by copyright and trademark laws (and various other intellectual property rights and unfair competition laws) and treaties in the United States and around the world.", "The Content and Marks are provided in or through the Services \"AS IS\" for your personal, non-commercial use only.", "Your use of our Services. Subject to your compliance with these Legal Terms, including the \"Prohibited activities\" section below, we grant you a non-exclusive, non-transferable, revocable license to access the Services, solely for your personal, non-commercial use. What you may do with the books is set out in section 31.", "Except as set out in this section or elsewhere in our Legal Terms, no part of the Services and no Content or Marks may be copied, reproduced, aggregated, republished, uploaded, posted, publicly displayed, encoded, translated, transmitted, distributed, sold, licensed, or otherwise exploited for any commercial purpose whatsoever, without our express prior written permission.", "If you wish to make any use of the Services, Content, or Marks other than as set out in this section or elsewhere in our Legal Terms, please address your request to: support@literaryworm.com.", "If we ever grant you the permission to post, reproduce, or publicly display any part of our Services or Content, you must identify us as the owners or licensors of the Services, Content, or Marks and ensure that any copyright or proprietary notice appears or is visible on posting, reproducing, or displaying our Content.", "We reserve all rights not expressly granted to you in and to the Services, Content, and Marks. Being able to see source code we publish doesn't give you a license to use it.", "Any breach of these Intellectual Property Rights will constitute a material breach of our Legal Terms and your right to use our Services will terminate immediately.", "Your submissions. By directly sending us any question, comment, suggestion, idea, feedback, or other information about the Services (\"Submissions\"), you agree to assign to us all intellectual property rights in such Submission. You agree that we shall own this Submission and be entitled to its unrestricted use and dissemination for any lawful purpose, commercial or otherwise, without acknowledgment or compensation to you.", "Your contributions. What you post in the Services (reading logs, club posts, ratings, list names and descriptions, notes and highlights) are \"Contributions\", covered by sections 9, 10 and 33. You own them, and the license you give us is the limited one in section 33. Contributions you make public may be seen by anyone, including through links you share outside the Services.", "You are responsible for what you post or upload. By sending us Submissions and/or posting Contributions, you:", "confirm that you have read and agree with our \"Prohibited activities\" and will not post, send, publish, upload, or transmit through the Services any Submission nor post any Contribution that is illegal, harassing, hateful, harmful, defamatory, obscene, bullying, abusive, discriminatory, threatening to any person or group, sexually explicit, false, inaccurate, deceitful, or misleading;", "warrant that any such Submission and/or Contributions are original to you or that you have the necessary rights and licenses to submit them and full authority to grant us the rights in these Legal Terms;", "and warrant and represent that your Submissions and/or Contributions do not constitute confidential information.", "You are solely responsible for your Submissions and/or Contributions and you expressly agree to reimburse us for any and all losses that we may suffer because of your breach of (a) this section, (b) any third party's intellectual property rights, or (c) applicable law.", "We may remove your Contributions. Although we have no obligation to monitor any Contributions, we shall have the right to remove any Contributions at any time without notice if in our reasonable opinion we consider such Contributions harmful or in breach of these Legal Terms. If we remove any such Contributions, we may also suspend or disable your account and report you to the authorities.", "Copyright infringement. We respect the intellectual property rights of others. If you believe that any material available on or through the Services infringes upon any copyright you own or control, please refer to section 15 and our Copyright/DMCA page."]}, {"heading": "3. User representations", "paragraphs": ["By using the Services, you represent and warrant that:", "(1) all registration information you submit will be true, accurate, current, and complete;", "(2) you will maintain the accuracy of such information and promptly update such registration information as necessary;", "(3) you have the legal capacity and you agree to comply with these Legal Terms;", "(4) if you hold an account, you are at least 18 and not a minor in the jurisdiction in which you reside;", "(5) you will not access the Services through automated or non-human means, whether through a bot, script or otherwise;", "(6) you will not use the Services for any illegal or unauthorized purpose;", "and (7) your use of the Services will not violate any applicable law or regulation.", "If you provide any information that is untrue, inaccurate, not current, or incomplete, we have the right to suspend or terminate your account and refuse any and all current or future use of the Services (or any portion thereof)."]}, {"heading": "4. User registration", "paragraphs": ["You need to register to use most of the Services. You agree to keep your password confidential and will be responsible for all use of your account and password. We reserve the right to remove, reclaim, or change a display name or profile name you select if we determine, in our sole discretion, that it is inappropriate, obscene, or otherwise objectionable."]}, {"heading": "5. Purchases and payment", "paragraphs": ["LiteraryWorm is a live service: when you choose a plan, you're billed monthly or yearly (as you choose) through Stripe until you cancel. Add a payment method in Account → Plan and billing to continue your membership.", "We accept the following forms of payment: Visa, Mastercard, American Express and Discover.", "You agree to provide current, complete, and accurate purchase and account information for all purchases made via the Services. You further agree to promptly update account and payment information, including email address, payment method, and payment card expiration date, so that we can complete your transactions and contact you as needed. Sales tax will be added to the price of purchases as deemed required by us. We may change prices at any time. All payments shall be in US dollars.", "You agree to pay all charges at the prices then in effect for your purchases, and you authorize us to charge your chosen payment provider for any such amounts upon placing your order. We reserve the right to correct any errors or mistakes in pricing, even if we have already requested or received payment.", "We reserve the right to refuse any order placed through the Services. We may, in our sole discretion, limit or cancel quantities purchased per person, per household, or per order. These restrictions may include orders placed by or under the same customer account or the same payment method. We reserve the right to limit or prohibit orders that, in our sole judgment, appear to be placed by dealers, resellers, or distributors."]}, {"heading": "6. Subscriptions", "paragraphs": ["Billing and renewal. Your subscription will continue and automatically renew each month on your billing day (or, if you pay yearly, each year on the date your year started) unless canceled. You consent to our charging your payment method on a recurring basis without requiring your prior approval for each recurring charge, until such time as you cancel. You can change your billing day to any day from the 1st to the 28th in Account.", "Cancellation and pausing. You can pause, resume or cancel your subscription at any time from Account. A pause stops billing until you resume. To stop the next charge, cancel at least 48 hours before your next billing date: your cancellation then takes effect at the end of the current paid term.", "If you cancel less than 48 hours before your billing date, that charge still goes through and your cancellation takes effect at the end of the term it pays for. No refunds are given for any part of a term. If you have any questions or are unsatisfied with our Services, please email us at support@literaryworm.com.", "Fee changes. We may, from time to time, make changes to the subscription fee and will communicate any price changes to you in accordance with applicable law."]}, {"heading": "7. Software", "paragraphs": ["Our End User License Agreement (https://www.literaryworm.com/legal/eula) governs your use of the LiteraryWorm app, in the browser or installed on a device. Any other software we provide in connection with our Services is licensed to you on a non-exclusive, revocable, personal, and non-transferable basis, solely in connection with our Services and in accordance with these Legal Terms.", "Any software and any related documentation is provided \"AS IS\" without warranty of any kind, either express or implied, including, without limitation, the implied warranties of merchantability, fitness for a particular purpose, or non-infringement. You accept any and all risk arising out of use or performance of any software. You may not reproduce or redistribute any software except in accordance with the EULA or these Legal Terms."]}, {"heading": "8. Prohibited activities", "paragraphs": ["You may not access or use the Services for any purpose other than that for which we make the Services available. The Services may not be used in connection with any commercial endeavors except those that are specifically endorsed or approved by us.", "As a user of the Services, you agree not to:", "1. Systematically retrieve data or other content from the Services to create or compile, directly or indirectly, a collection, compilation, database, or directory without written permission from us.", "2. Trick, defraud, or mislead us and other users, especially in any attempt to learn sensitive account information such as user passwords or profile PINs.", "3. Circumvent, disable, or otherwise interfere with security-related features of the Services, including features that prevent or restrict the use or copying of any Content or enforce limitations on the use of the Services and/or the Content contained therein, such as daily reading limits and age ratings.", "4. Disparage, tarnish, or otherwise harm, in our opinion, us and/or the Services.", "5. Use any information obtained from the Services in order to harass, abuse, or harm another person.", "6. Make improper use of our support services or submit false reports of abuse or misconduct.", "7. Use the Services in a manner inconsistent with any applicable laws or regulations.", "8. Engage in unauthorized framing of or linking to the Services.", "9. Upload or transmit (or attempt to upload or to transmit) viruses, Trojan horses, or other material, including excessive use of capital letters and spamming (continuous posting of repetitive text), that interferes with any party's uninterrupted use and enjoyment of the Services or modifies, impairs, disrupts, alters, or interferes with the use, features, functions, operation, or maintenance of the Services.", "10. Engage in any automated use of the system, such as using scripts to send comments or messages, or using any data mining, robots, or similar data gathering and extraction tools.", "11. Delete the copyright or other proprietary rights notice from any Content.", "12. Attempt to impersonate another user or person or use the display name of another user.", "13. Upload or transmit (or attempt to upload or to transmit) any material that acts as a passive or active information collection or transmission mechanism, including without limitation, clear graphics interchange formats (\"gifs\"), 1×1 pixels, web bugs, cookies, or other similar devices (sometimes referred to as \"spyware\" or \"passive collection mechanisms\" or \"pcms\").", "14. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services, including by trying to get around the limits on AI summaries, content notes, Ask the book, Translate, Who's who, Previously… recaps, chapter quizzes and discussion questions.", "15. Harass, annoy, intimidate, or threaten any of our employees or agents engaged in providing any portion of the Services to you.", "16. Attempt to bypass any measures of the Services designed to prevent or restrict access to the Services, or any portion of the Services.", "17. Copy or adapt the Services' software, including but not limited to HTML, JavaScript, or other code.", "18. Except as permitted by applicable law, decipher, decompile, disassemble, or reverse engineer any of the software comprising or in any way making up a part of the Services.", "19. Except as may be the result of standard search engine or Internet browser usage, or the Services' own Read offline feature, use, launch, develop, or distribute any automated system, including without limitation, any spider, robot, cheat utility, scraper, or offline reader that accesses the Services, or use or launch any unauthorized script or other software.", "20. Use a buying agent or purchasing agent to make purchases on the Services.", "21. Make any unauthorized use of the Services, including collecting display names and/or email addresses of users by electronic or other means for the purpose of sending unsolicited email, or creating user accounts by automated means or under false pretenses.", "22. Use the Services as part of any effort to compete with us or otherwise use the Services and/or the Content for any revenue-generating endeavor or commercial enterprise.", "23. Sell or otherwise transfer your account or a profile.", "24. Use the Services to advertise or offer to sell goods and services."]}, {"heading": "9. User generated contributions", "paragraphs": ["The Services invite you to post Contributions: reading logs (shown on a book's public page with your display name), book club posts (seen by the club's members), highlights you share with a club (seen by its members), ratings, lists you choose to share by link, and private notes and highlights. Contributions you make public may be viewable by other users of the Services and by anyone you share a link with. When you create or make available any Contributions, you thereby represent and warrant that:", "1. The creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party.", "2. You are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Services, and other users of the Services to use your Contributions in any manner contemplated by the Services and these Legal Terms.", "3. You have the written consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Services and these Legal Terms.", "4. Your Contributions are not false, inaccurate, or misleading.", "5. Your Contributions are not unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation.", "6. Your Contributions are not obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, or otherwise objectionable (as determined by us).", "7. Your Contributions do not ridicule, mock, disparage, intimidate, or abuse anyone.", "8. Your Contributions are not used to harass or threaten (in the legal sense of those terms) any other person and to promote violence against a specific person or class of people.", "9. Your Contributions do not violate any applicable law, regulation, or rule.", "10. Your Contributions do not violate the privacy or publicity rights of any third party.", "11. Your Contributions do not violate any applicable law concerning child sexual abuse material, or otherwise intended to protect the health or well-being of minors.", "12. Your Contributions do not include any offensive comments that are connected to race, national origin, gender, sexual preference, or physical handicap.", "13. Your Contributions do not otherwise violate, or link to material that violates, any provision of these Legal Terms, or any applicable law or regulation.", "Any use of the Services in violation of the foregoing violates these Legal Terms and may result in, among other things, termination or suspension of your rights to use the Services."]}, {"heading": "10. Contribution license", "paragraphs": ["We do not assert any ownership over your Contributions. You retain full ownership of all of your Contributions and any intellectual property rights or other proprietary rights associated with your Contributions. The only license you give us is the one in section 33: to store, copy and display them where and to whom you posted them, so we can run the features you use.", "We are not liable for any statements or representations in your Contributions provided by you in any area on the Services. You are solely responsible for your Contributions to the Services and you expressly agree to exonerate us from any and all responsibility and to refrain from any legal action against us regarding your Contributions.", "We have the right, in our sole and absolute discretion, to remove or hide any Contributions at any time and for any reason, without notice. We have no obligation to monitor your Contributions."]}, {"heading": "11. Guidelines for reviews", "paragraphs": ["You can rate books and write about them in reading logs. When you do, you must comply with the following criteria:", "(1) you should have firsthand experience with the book you're reviewing;", "(2) your reviews should not contain offensive profanity, or abusive, racist, offensive, or hateful language;", "(3) your reviews should not contain discriminatory references based on religion, race, gender, national origin, age, marital status, sexual orientation, or disability;", "(4) your reviews should not contain references to illegal activity;", "(5) you should not be affiliated with competitors if posting negative reviews;", "(6) you should not make any conclusions as to the legality of conduct;", "(7) you may not post any false or misleading statements;", "and (8) you may not organize a campaign encouraging others to post reviews, whether positive or negative.", "We may remove reviews in our sole discretion. We have absolutely no obligation to screen reviews or to delete reviews, even if anyone considers reviews objectionable or inaccurate. Reviews are not endorsed by us, and do not necessarily represent our opinions or the views of any of our affiliates or partners. We do not assume liability for any review or for any claims, liabilities, or losses resulting from any review. Reviews are Contributions, so you keep them, and the license you give us is the one in section 33."]}, {"heading": "12. Third-party websites and content", "paragraphs": ["The Services contain (or you may be sent via the Site) links to other websites (\"Third-Party Websites\"), such as Google Books, the Internet Archive, LibriVox and Project Gutenberg, as well as articles, photographs, text, graphics, pictures, designs, music, sound, video, information, applications, software, and other content or items belonging to or originating from third parties (\"Third-Party Content\"), such as book details and covers from Google Books and recordings from LibriVox.", "Such Third-Party Websites and Third-Party Content are not investigated, monitored, or checked for accuracy, appropriateness, or completeness by us, and we are not responsible for any Third-Party Websites accessed through the Services or any Third-Party Content posted on, available through, or installed from the Services, including the content, accuracy, offensiveness, opinions, reliability, privacy practices, or other policies of or contained in the Third-Party Websites or the Third-Party Content.", "Inclusion of, linking to, or permitting the use or installation of any Third-Party Websites or any Third-Party Content does not imply approval or endorsement thereof by us. If you decide to leave the Services and access the Third-Party Websites or to use or install any Third-Party Content, you do so at your own risk, and you should be aware these Legal Terms no longer govern.", "You should review the applicable terms and policies, including privacy and data gathering practices, of any website to which you navigate from the Services or relating to any applications you use or install from the Services.", "Any purchases you make through Third-Party Websites will be through other websites and from other companies, and we take no responsibility whatsoever in relation to such purchases which are exclusively between you and the applicable third party.", "You agree and acknowledge that we do not endorse the products or services offered on Third-Party Websites and you shall hold us blameless from any harm caused by your purchase of such products or services. Additionally, you shall hold us blameless from any losses sustained by you or harm caused to you relating to or resulting in any way from any Third-Party Content or any contact with Third-Party Websites."]}, {"heading": "13. Services management", "paragraphs": ["We reserve the right, but not the obligation, to:", "(1) monitor the Services for violations of these Legal Terms;", "(2) take appropriate legal action against anyone who, in our sole discretion, violates the law or these Legal Terms, including without limitation, reporting such user to law enforcement authorities;", "(3) in our sole discretion and without limitation, refuse, restrict access to, limit the availability of, or disable (to the extent technologically feasible) any of your Contributions or any portion thereof;", "(4) in our sole discretion and without limitation, notice, or liability, to remove from the Services or otherwise disable all files and content that are excessive in size or are in any way burdensome to our systems;", "and (5) otherwise manage the Services in a manner designed to protect our rights and property and to facilitate the proper functioning of the Services."]}, {"heading": "14. Privacy policy", "paragraphs": ["We care about data privacy and security. Please review our Privacy Policy: https://www.literaryworm.com/legal/privacy. By using the Services, you agree to be bound by our Privacy Policy, which is incorporated into these Legal Terms. Please be advised the Services are hosted in the United States.", "If you access the Services from any other region of the world with laws or other requirements governing personal data collection, use, or disclosure that differ from applicable laws in the United States, then through your continued use of the Services, you are transferring your data to the United States, and you expressly consent to have your data transferred to and processed in the United States."]}, {"heading": "15. Copyright infringements", "paragraphs": ["We respect the intellectual property rights of others. If you believe that any material available on or through the Services infringes upon any copyright you own or control, please follow the steps on our Copyright/DMCA page (a \"Notification\"). We will tell the member who posted the material that it was removed.", "Please be advised that pursuant to applicable law you may be held liable for damages if you make material misrepresentations in a Notification. Thus, if you are not sure that material located on or linked to by the Services infringes your copyright, you should consider first contacting an attorney."]}, {"heading": "16. Term and termination", "paragraphs": ["These Legal Terms shall remain in full force and effect while you use the Services. You can end them at any time by deleting your account from Account.", "WITHOUT LIMITING ANY OTHER PROVISION OF THESE LEGAL TERMS, WE RESERVE THE RIGHT TO, IN OUR SOLE DISCRETION AND WITHOUT NOTICE OR LIABILITY, DENY ACCESS TO AND USE OF THE SERVICES (INCLUDING BLOCKING CERTAIN IP ADDRESSES), TO ANY PERSON FOR ANY REASON OR FOR NO REASON, INCLUDING WITHOUT LIMITATION FOR BREACH OF ANY REPRESENTATION, WARRANTY, OR COVENANT CONTAINED IN THESE LEGAL TERMS OR OF ANY APPLICABLE LAW OR REGULATION.", "WE MAY TERMINATE YOUR USE OR PARTICIPATION IN THE SERVICES OR DELETE YOUR ACCOUNT AND ANY CONTENT OR INFORMATION THAT YOU POSTED AT ANY TIME, WITHOUT WARNING, IN OUR SOLE DISCRETION.", "If we terminate or suspend your account for any reason, you are prohibited from registering and creating a new account under your name, a fake or borrowed name, or the name of any third party, even if you may be acting on behalf of the third party. In addition to terminating or suspending your account, we reserve the right to take appropriate legal action, including without limitation pursuing civil, criminal, and injunctive redress."]}, {"heading": "17. Modifications and interruptions", "paragraphs": ["We reserve the right to change, modify, or remove the contents of the Services at any time or for any reason at our sole discretion without notice. However, we have no obligation to update any information on our Services. We will not be liable to you or any third party for any modification, price change, suspension, or discontinuance of the Services.", "We cannot guarantee the Services will be available at all times. We may experience hardware, software, or other problems or need to perform maintenance related to the Services, resulting in interruptions, delays, or errors. Our Status page shows whether the Services are working.", "We reserve the right to change, revise, update, suspend, discontinue, or otherwise modify the Services at any time or for any reason without notice to you. You agree that we have no liability whatsoever for any loss, damage, or inconvenience caused by your inability to access or use the Services during any downtime or discontinuance of the Services.", "Nothing in these Legal Terms will be construed to obligate us to maintain and support the Services or to supply any corrections, updates, or releases in connection therewith."]}, {"heading": "18. Governing law", "paragraphs": ["These Legal Terms and your use of the Services are governed by and construed in accordance with the laws of the State of Illinois applicable to agreements made and to be entirely performed within the State of Illinois, without regard to its conflict of law principles."]}, {"heading": "19. Dispute resolution", "paragraphs": ["Informal negotiations. To expedite resolution and control the cost of any dispute, controversy, or claim related to these Legal Terms (each a \"Dispute\" and collectively, the \"Disputes\") brought by either you or us (individually, a \"Party\" and collectively, the \"Parties\"), the Parties agree to first attempt to negotiate any Dispute (except those Disputes expressly provided below) informally for at least thirty (30) days before initiating arbitration. Such informal negotiations commence upon written notice from one Party to the other Party.", "Binding arbitration. If the Parties are unable to resolve a Dispute through informal negotiations, the Dispute (except those Disputes expressly excluded below) will be finally and exclusively resolved by binding arbitration. YOU UNDERSTAND THAT WITHOUT THIS PROVISION, YOU WOULD HAVE THE RIGHT TO SUE IN COURT AND HAVE A JURY TRIAL.", "The arbitration shall be commenced and conducted under the Commercial Arbitration Rules of the American Arbitration Association (\"AAA\") and, where appropriate, the AAA's Supplementary Procedures for Consumer Related Disputes (\"AAA Consumer Rules\"), both of which are available at the American Arbitration Association (AAA) website.", "Your arbitration fees and your share of arbitrator compensation shall be governed by the AAA Consumer Rules and, where appropriate, limited by the AAA Consumer Rules. The arbitration may be conducted in person, through the submission of documents, by phone, or online. The arbitrator will make a decision in writing, but need not provide a statement of reasons unless requested by either Party.", "The arbitrator must follow applicable law, and any award may be challenged if the arbitrator fails to do so. Except where otherwise required by the applicable AAA rules or applicable law, the arbitration will take place in Cook County, Illinois.", "Except as otherwise provided herein, the Parties may litigate in court to compel arbitration, stay proceedings pending arbitration, or to confirm, modify, vacate, or enter judgment on the award entered by the arbitrator.", "If for any reason, a Dispute proceeds in court rather than arbitration, the Dispute shall be commenced or prosecuted in the state and federal courts located in Cook County, Illinois, and the Parties hereby consent to, and waive all defenses of lack of personal jurisdiction, and forum non conveniens with respect to venue and jurisdiction in such state and federal courts.", "Application of the United Nations Convention on Contracts for the International Sale of Goods and the Uniform Computer Information Transaction Act (UCITA) are excluded from these Legal Terms.", "In no event shall any Dispute brought by either Party related in any way to the Services be commenced more than one (1) year after the cause of action arose.", "If this provision is found to be illegal or unenforceable, then neither Party will elect to arbitrate any Dispute falling within that portion of this provision found to be illegal or unenforceable and such Dispute shall be decided by a court of competent jurisdiction within the courts listed for jurisdiction above, and the Parties agree to submit to the personal jurisdiction of that court.", "Restrictions. The Parties agree that any arbitration shall be limited to the Dispute between the Parties individually.", "To the full extent permitted by law, (a) no arbitration shall be joined with any other proceeding; (b) there is no right or authority for any Dispute to be arbitrated on a class-action basis or to utilize class action procedures; and (c) there is no right or authority for any Dispute to be brought in a purported representative capacity on behalf of the general public or any other persons.", "Exceptions to informal negotiations and arbitration. The Parties agree that the following Disputes are not subject to the above provisions concerning informal negotiations and binding arbitration: (a) any Disputes seeking to enforce or protect, or concerning the validity of, any of the intellectual property rights of a Party; (b) any Dispute related to, or arising from, allegations of theft, piracy, invasion of privacy, or unauthorized use; and (c) any claim for injunctive relief.", "If this provision is found to be illegal or unenforceable, then neither Party will elect to arbitrate any Dispute falling within that portion of this provision found to be illegal or unenforceable and such Dispute shall be decided by a court of competent jurisdiction within the courts listed for jurisdiction above, and the Parties agree to submit to the personal jurisdiction of that court."]}, {"heading": "20. Corrections", "paragraphs": ["There may be information on the Services that contains typographical errors, inaccuracies, or omissions, including descriptions, pricing, availability, and various other information. We reserve the right to correct any errors, inaccuracies, or omissions and to change or update the information on the Services at any time, without prior notice."]}, {"heading": "21. Disclaimer", "paragraphs": ["THE SERVICES ARE PROVIDED ON AN AS-IS AND AS-AVAILABLE BASIS. YOU AGREE THAT YOUR USE OF THE SERVICES WILL BE AT YOUR SOLE RISK. TO THE FULLEST EXTENT PERMITTED BY LAW, WE DISCLAIM ALL WARRANTIES, EXPRESS OR IMPLIED, IN CONNECTION WITH THE SERVICES AND YOUR USE THEREOF, INCLUDING, WITHOUT LIMITATION, THE IMPLIED WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NON-INFRINGEMENT.", "WE MAKE NO WARRANTIES OR REPRESENTATIONS ABOUT THE ACCURACY OR COMPLETENESS OF THE SERVICES' CONTENT (INCLUDING BOOK DETAILS FROM GOOGLE BOOKS AND SUMMARIES, CONTENT NOTES, TRANSLATIONS AND ANSWERS WRITTEN BY AI) OR THE CONTENT OF ANY WEBSITES OR MOBILE APPLICATIONS LINKED TO THE SERVICES AND WE WILL ASSUME NO LIABILITY OR RESPONSIBILITY FOR ANY:", "(1) ERRORS, MISTAKES, OR INACCURACIES OF CONTENT AND MATERIALS,", "(2) PERSONAL INJURY OR PROPERTY DAMAGE, OF ANY NATURE WHATSOEVER, RESULTING FROM YOUR ACCESS TO AND USE OF THE SERVICES,", "(3) ANY UNAUTHORIZED ACCESS TO OR USE OF OUR SECURE SERVERS AND/OR ANY AND ALL PERSONAL INFORMATION STORED THEREIN,", "(4) ANY INTERRUPTION OR CESSATION OF TRANSMISSION TO OR FROM THE SERVICES,", "(5) ANY BUGS, VIRUSES, TROJAN HORSES, OR THE LIKE WHICH MAY BE TRANSMITTED TO OR THROUGH THE SERVICES BY ANY THIRD PARTY,", "AND/OR (6) ANY ERRORS OR OMISSIONS IN ANY CONTENT AND MATERIALS OR FOR ANY LOSS OR DAMAGE OF ANY KIND INCURRED AS A RESULT OF THE USE OF ANY CONTENT POSTED, TRANSMITTED, OR OTHERWISE MADE AVAILABLE VIA THE SERVICES.", "WE DO NOT WARRANT, ENDORSE, GUARANTEE, OR ASSUME RESPONSIBILITY FOR ANY PRODUCT OR SERVICE OFFERED BY A THIRD PARTY THROUGH THE SERVICES OR ANY HYPERLINKED WEBSITE, AND WE WILL NOT BE A PARTY TO OR IN ANY WAY BE RESPONSIBLE FOR MONITORING ANY TRANSACTION BETWEEN YOU AND ANY THIRD-PARTY PROVIDERS OF PRODUCTS OR SERVICES.", "AS WITH THE PURCHASE OF A PRODUCT OR SERVICE THROUGH ANY MEDIUM OR IN ANY ENVIRONMENT, YOU SHOULD USE YOUR BEST JUDGMENT AND EXERCISE CAUTION WHERE APPROPRIATE."]}, {"heading": "22. Limitations of liability", "paragraphs": ["IN NO EVENT WILL WE OR OUR DIRECTORS, EMPLOYEES, OR AGENTS BE LIABLE TO YOU OR ANY THIRD PARTY FOR ANY DIRECT, INDIRECT, CONSEQUENTIAL, EXEMPLARY, INCIDENTAL, SPECIAL, OR PUNITIVE DAMAGES, INCLUDING LOST PROFIT, LOST REVENUE, LOSS OF DATA, OR OTHER DAMAGES ARISING FROM YOUR USE OF THE SERVICES, EVEN IF WE HAVE BEEN ADVISED OF THE POSSIBILITY OF SUCH DAMAGES.", "NOTWITHSTANDING ANYTHING TO THE CONTRARY CONTAINED HEREIN, OUR LIABILITY TO YOU FOR ANY CAUSE WHATSOEVER AND REGARDLESS OF THE FORM OF THE ACTION, WILL AT ALL TIMES BE LIMITED TO THE AMOUNT PAID, IF ANY, BY YOU TO US DURING THE SIX (6) MONTH PERIOD PRIOR TO ANY CAUSE OF ACTION ARISING.", "CERTAIN US STATE LAWS AND INTERNATIONAL LAWS DO NOT ALLOW LIMITATIONS ON IMPLIED WARRANTIES OR THE EXCLUSION OR LIMITATION OF CERTAIN DAMAGES. IF THESE LAWS APPLY TO YOU, SOME OR ALL OF THE ABOVE DISCLAIMERS OR LIMITATIONS MAY NOT APPLY TO YOU, AND YOU MAY HAVE ADDITIONAL RIGHTS."]}, {"heading": "23. Indemnification", "paragraphs": ["You agree to defend, indemnify, and hold us harmless, including our subsidiaries, affiliates, and all of our respective officers, agents, partners, and employees, from and against any loss, damage, liability, claim, or demand, including reasonable attorneys' fees and expenses, made by any third party due to or arising out of:", "(1) your Contributions;", "(2) use of the Services;", "(3) breach of these Legal Terms;", "(4) any breach of your representations and warranties set forth in these Legal Terms;", "(5) your violation of the rights of a third party, including but not limited to intellectual property rights;", "or (6) any overt harmful act toward any other user of the Services with whom you connected via the Services.", "Notwithstanding the foregoing, we reserve the right, at your expense, to assume the exclusive defense and control of any matter for which you are required to indemnify us, and you agree to cooperate, at your expense, with our defense of such claims. We will use reasonable efforts to notify you of any such claim, action, or proceeding which is subject to this indemnification upon becoming aware of it."]}, {"heading": "24. User data", "paragraphs": ["We will maintain certain data that you transmit to the Services for the purpose of managing the performance of the Services, as well as data relating to your use of the Services, as our Privacy Policy describes. You can download a copy of your data at any time from Account (Download my data).", "To the extent permitted by law, you are responsible for keeping your own copy of anything you can't afford to lose, and you agree that we shall have no liability to you for any loss or corruption of any such data."]}, {"heading": "25. Electronic communications, transactions, and signatures", "paragraphs": ["Visiting the Services, sending us emails, and completing online forms constitute electronic communications. You consent to receive electronic communications, and you agree that all agreements, notices, disclosures, and other communications we provide to you electronically, via email and on the Services, satisfy any legal requirement that such communication be in writing.", "YOU HEREBY AGREE TO THE USE OF ELECTRONIC SIGNATURES, CONTRACTS, ORDERS, AND OTHER RECORDS, AND TO ELECTRONIC DELIVERY OF NOTICES, POLICIES, AND RECORDS OF TRANSACTIONS INITIATED OR COMPLETED BY US OR VIA THE SERVICES.", "You hereby waive any rights or requirements under any statutes, regulations, rules, ordinances, or other laws in any jurisdiction which require an original signature or delivery or retention of non-electronic records, or to payments or the granting of credits by any means other than electronic means."]}, {"heading": "26. SMS text messaging", "paragraphs": ["LiteraryWorm doesn't send text messages (SMS) and doesn't ask for your phone number. If we ever start a text messaging program, we'll add its terms here, including how to opt out, before it begins."]}, {"heading": "27. California users and residents", "paragraphs": ["If any complaint with us is not satisfactorily resolved, you can contact the Complaint Assistance Unit of the Division of Consumer Services of the California Department of Consumer Affairs in writing at 1625 North Market Blvd., Suite N 112, Sacramento, California 95834 or by telephone at (800) 952-5210 or (916) 445-1254."]}, {"heading": "28. Miscellaneous", "paragraphs": ["These Legal Terms and any policies or operating rules posted by us on the Services or in respect to the Services constitute the entire agreement and understanding between you and us. Our failure to exercise or enforce any right or provision of these Legal Terms shall not operate as a waiver of such right or provision. These Legal Terms operate to the fullest extent permissible by law.", "We may assign any or all of our rights and obligations to others at any time. We shall not be responsible or liable for any loss, damage, delay, or failure to act caused by any cause beyond our reasonable control.", "If any provision or part of a provision of these Legal Terms is determined to be unlawful, void, or unenforceable, that provision or part of the provision is deemed severable from these Legal Terms and does not affect the validity and enforceability of any remaining provisions.", "There is no joint venture, partnership, employment or agency relationship created between you and us as a result of these Legal Terms or use of the Services. You agree that these Legal Terms will not be construed against us by virtue of having drafted them.", "You hereby waive any and all defenses you may have based on the electronic form of these Legal Terms and the lack of signing by the parties hereto to execute these Legal Terms."]}, {"heading": "29. Your account", "paragraphs": ["Account holders must be 18 or older. You may add profiles for people in your household, including Kids profiles with your consent, and you're responsible for how they're used.", "Keep your password private. You can change it, and delete your account, from Account at any time."]}, {"heading": "30. Membership", "paragraphs": ["Plans renew automatically each month on your billing day until you cancel, which you can do online at any time; reading continues until the end of the period you've paid for. Cancel at least 48 hours before your billing date to stop the next charge; cancelling later means one more monthly charge, and then the membership ends. No refunds.", "You can change your billing day (the 1st to the 28th), and pause and resume, from Account. Yearly plans cost ten times the monthly price, start the day you pay and renew on that date each year until you cancel; we remind you in the app 30 days before. The same 48 hours' notice applies, so cancelling later means one more yearly charge.", "Moving from monthly to yearly starts the year at once, with the unused part of the month taken off its price; moving a yearly plan to a bigger plan charges the difference for the rest of the year straight away, and to a smaller one takes effect at renewal with no credit. Yearly plans can't be paused or change their billing day.", "You can choose monthly billing at any time, and it starts on your renewal date, with nothing charged or refunded before then.", "This is not a demo app anymore: your LiteraryWorm account is a live account. You'll be billed monthly, or yearly if you choose, until you cancel. Add a payment method in Account → Plan and billing to continue your membership. On monthly billing you can change your billing day to any day from the 1st to the 28th, and start, pause or cancel billing at any time in Account; a yearly plan can be cancelled at any time, but not paused.", "Plan limits. Each plan includes the audiobook listening, profiles and offline devices shown on the Plans page: Basic, 5 hours a month, 1 profile and 1 device; Standard, 30 hours, 3 profiles and 10 devices; Premium, unlimited listening, 12 profiles and 24 devices. Listening is counted for the whole household on every device.", "When a month's hours are used up, audiobooks pause until the 1st of the next month; reading carries on, and you can change plan at any time. To move to a plan with fewer profiles or offline devices, first set aside or remove the profiles and free the devices it has no room for.", "A household that already has more profiles than its plan now allows, because the plan changed, keeps them in use but can't add more until it fits. A profile set aside keeps its shelf, history and settings, doesn't count towards the plan, and comes back when there's room. While a yearly membership waits to move to a smaller plan at renewal, it has that plan's room already.", "Each device that saves books with Read offline holds one of the plan's places: free one in Account → Plan and billing to use another device, and the freed device's offline books are removed the next time it opens LiteraryWorm.", "Staff memberships. People with a LiteraryWorm staff role (admin, editor, developer, billing, customer service, blog or sales) have a complimentary Premium membership for as long as they hold a role. It's never billed and can't be paused or cancelled; it ends when their last staff role is removed, and they can then choose a plan like any member.", "Inviting friends. Each member has a link to share from Account. When someone who hasn't had a LiteraryWorm account before signs up with it and makes their first payment, we add a month of their plan as a credit on their account, and a month of your own plan as a credit on yours. Credits come off your next invoices.", "You can earn up to 2 free months from inviting friends in all; the friends you invite after that still get their month. Credits have no cash value, can't be moved to another account, and aren't refunded when a membership ends. Staff memberships aren't billed, so they don't earn or receive credits.", "Invitations are for people you know. We may withhold or remove credits earned by signing up yourself again, by using made-up accounts, or by posting your link where it reaches people who didn't ask for it, and we may change or end the offer with notice in What's new; credits already added stay."]}, {"heading": "31. Your licence to read and listen", "paragraphs": ["While your membership is active, we give you a personal, non-exclusive, non-transferable, revocable licence to read and listen to the books in LiteraryWorm for your own and your household's non-commercial use, in the app.", "You may not copy, sell, share, broadcast or publicly perform the books, remove or get around any protection on them, or use them to train AI models. Books saved for offline reading stay in the app on your device.", "This licence doesn't apply to public-domain works themselves, which anyone may use freely; it covers our app, our edition and our service."]}, {"heading": "32. Who owns the books and the app", "paragraphs": ["Public-domain titles: the texts come from Project Gutenberg and the recordings from LibriVox, whose volunteers release their recordings into the public domain. These works are in the public domain in the United States; they may not be everywhere, so check your country's rules before using them outside LiteraryWorm.", "Other LiteraryWorm titles show sample pages, not the published books. Book details and covers from Google Books belong to their publishers and rights holders and are shown under Google's terms.", "Summaries, content notes, Ask the book answers, translations, Who's who, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude) and labelled so. They may be wrong; they're provided for your own reading and may not be republished as LiteraryWorm's.", "The LiteraryWorm name, logo, design and software belong to LiteraryWorm. Using the service doesn't give you any rights in them beyond these Terms."]}, {"heading": "33. What you post, and the license you give us", "paragraphs": ["You own what you write: reading logs, club posts, list names and descriptions, notes and highlights.", "So we can run the features you use, you give LiteraryWorm a worldwide, non-exclusive, royalty-free licence to store, copy and display what you post, only where and to whom you posted it (logs on the book's public page with your display name, club posts to the club, shared lists to anyone with the link). The licence ends when you delete the content or your account, except for copies already made by others, such as someone else's screenshot.", "Notes, highlights, saved words and private lists are never shown to anyone else."]}, {"heading": "34. Books you upload", "paragraphs": ["Upload only books you have the right to read in this way, such as DRM-free books you've bought or works in the public domain. Don't upload books you don't have rights to, and don't remove DRM to upload them.", "Your uploads stay private to the profile that added them. We store their text only to show it to you, claim no rights in them, and delete them when you do or when you delete the profile or account.", "You can start a book club around a book you uploaded. Its members see only the title and author; each of them reads their own copy, which they must also have the right to read, and nobody's upload is shared with anyone else."]}, {"heading": "35. Rules, changes and ending", "paragraphs": ["Don't post anything unlawful, hateful, harassing or infringing, impersonate others, spam clubs, or try to break or overload the service. We may remove content that breaks these rules and suspend accounts that keep doing so, including repeat copyright infringers (see Copyright/DMCA).", "LiteraryWorm is provided as is. We'll tell you before changing these Terms in ways that matter, and you can cancel or delete your account at any time."]}, {"heading": "36. Contact us", "paragraphs": ["In order to resolve a complaint regarding the Services or to receive further information regarding use of the Services, please contact us at: LiteraryWorm, support@literaryworm.com."]}]$lw$::jsonb),
  ($lw$eula$lw$, 6, $lw$End User License Agreement$lw$, $lw$LiteraryWorm is licensed to You (End-User) by LiteraryWorm ("Licensor"), for use only under the terms of this License Agreement. By using the Licensed Application at https://www.literaryworm.com, or installing it on a device from your browser, and any update to it, You agree to be bound by all of the terms and conditions of this License Agreement. It sits alongside our Terms of Service; where they cover the same thing, the Terms of Service apply.$lw$, $lw$[{"heading": "In short", "paragraphs": ["This License Agreement covers the LiteraryWorm app itself, in your browser or installed from it. Our Terms of Service cover your membership, and where both cover the same thing, the Terms of Service apply.", "You may use the app on your own devices for yourself and your household. Don't copy, change, resell or take apart the app, or use it to break the law or anyone's rights.", "We look after the app and its updates, and you can reach us at support@literaryworm.com."]}, {"heading": "1. The application", "paragraphs": ["LiteraryWorm (\"Licensed Application\") is a piece of software created to read and listen to books online. It runs in a web browser and can be installed from the browser on phones, tablets and computers (\"Devices\"). It is used to read ebooks and listen to audiobooks, keep a library and goals for each person at home, read along with book clubs, and review books and share opinions with other readers.", "The books we offer in full are in the public domain and have no DRM. Members can also read DRM-free EPUBs they upload.", "The Licensed Application is not tailored to comply with industry-specific regulations (Health Insurance Portability and Accountability Act (HIPAA), Federal Information Security Management Act (FISMA), etc.), so if your interactions would be subjected to such laws, you may not use this Licensed Application. You may not use the Licensed Application in a way that would violate the Gramm-Leach-Bliley Act (GLBA).", "The Licensed Application isn't sold through an app store, and no app store or other third party is a party to this License Agreement. LiteraryWorm is solely responsible for the Licensed Application and its content."]}, {"heading": "2. Scope of license", "paragraphs": ["2.1 You are given a non-transferable, non-exclusive, non-sublicensable license to use the Licensed Application on any Devices that You (End-User) own or control, with the exception that people in your household may use it through the profiles on your account, as the Terms of Service allow.", "2.2 This license will also govern any updates of the Licensed Application provided by Licensor that replace, repair, and/or supplement the first Licensed Application, unless a separate license is provided for such update, in which case the terms of that new license will govern.", "2.3 You may not share or make the Licensed Application available to third parties (except through features the Licensed Application offers, such as shared lists and book clubs, or with LiteraryWorm's prior written consent), sell, rent, lend, lease or otherwise redistribute the Licensed Application.", "2.4 You may not reverse engineer, translate, disassemble, integrate, decompile, remove, modify, combine, create derivative works or updates of, adapt, or attempt to derive the source code of the Licensed Application, or any part thereof, except with LiteraryWorm's prior written consent or where the law allows it. Being able to see source code we publish doesn't give You a license to use it.", "2.5 You may not copy (excluding when expressly authorized by this license) or alter the Licensed Application or portions thereof. Books You save for offline reading are kept in the Licensed Application on that Device only. You may not remove any intellectual property notices. If you sell or give away a Device, sign out of LiteraryWorm on it first; signing out removes books you uploaded from that Device, and you can clear books saved for offline from the Licensed Application or your browser.", "2.6 Violations of the obligations mentioned above, as well as the attempt of such infringement, may be subject to prosecution and damages.", "2.7 Licensor reserves the right to modify the terms and conditions of licensing. We'll tell you before changing them in ways that matter.", "2.8 Nothing in this license should be interpreted to restrict third-party terms. When using the Licensed Application, You must ensure that You comply with applicable third-party terms and conditions."]}, {"heading": "3. Technical requirements", "paragraphs": ["3.1 The Licensed Application requires a current version of Chrome, Edge, Firefox or Safari and an internet connection, except for books saved for offline reading. Licensor recommends keeping your browser up to date.", "3.2 Licensor attempts to keep the Licensed Application updated so that it works with new versions of browsers and new hardware. You are not granted rights to claim such an update.", "3.3 You acknowledge that it is Your responsibility to confirm and determine that the Device on which You intend to use the Licensed Application satisfies the technical specifications mentioned above.", "3.4 Licensor reserves the right to modify the technical specifications as it sees appropriate at any time."]}, {"heading": "4. Maintenance and support", "paragraphs": ["4.1 The Licensor is solely responsible for providing any maintenance and support services for this Licensed Application. You can reach the Licensor at support@literaryworm.com.", "4.2 No app store or other third party has any obligation to provide maintenance and support services for the Licensed Application."]}, {"heading": "5. Use of data", "paragraphs": ["You acknowledge that Licensor stores and can access Your account, Your profiles and what You read, save and share in the Licensed Application, so that it can provide it to You, and that Licensor's use of that information is subject to Your legal agreements with Licensor and Licensor's privacy policy: https://www.literaryworm.com/legal/privacy.", "You acknowledge that the Licensor and its hosting providers may collect technical data, such as your browser type, IP address and error reports, to keep the Licensed Application secure and working and to offer product support, and a short label for each Device you're signed in on (such as \"Chrome on Windows\") so you can send a book to another Device. Licensor doesn't use this information for advertising."]}, {"heading": "6. User-generated contributions", "paragraphs": ["The Licensed Application invites you to contribute content: reading logs (shown on a book's public page with your display name), book club posts (seen by the club's members), ratings, lists you choose to share by link, and private notes and highlights (collectively, \"Contributions\"). Contributions you make public may be viewable by anyone, including through links shared outside the Licensed Application. When you create or make available any Contributions, you thereby represent and warrant that:", "1. The creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party.", "2. You are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Licensed Application, and other users of the Licensed Application to use your Contributions in any manner contemplated by the Licensed Application and this License Agreement.", "3. You have the written consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Licensed Application and this License Agreement.", "4. Your Contributions are not false, inaccurate, or misleading.", "5. Your Contributions are not unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation.", "6. Your Contributions are not obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, or otherwise objectionable (as determined by us).", "7. Your Contributions do not ridicule, mock, disparage, intimidate, or abuse anyone.", "8. Your Contributions are not used to harass or threaten (in the legal sense of those terms) any other person and to promote violence against a specific person or class of people.", "9. Your Contributions do not violate any applicable law, regulation, or rule.", "10. Your Contributions do not violate the privacy or publicity rights of any third party.", "11. Your Contributions do not violate any applicable law concerning child sexual abuse material, or otherwise intended to protect the health or well-being of minors.", "12. Your Contributions do not include any offensive comments that are connected to race, national origin, gender, sexual preference, or physical handicap.", "13. Your Contributions do not otherwise violate, or link to material that violates, any provision of this License Agreement, or any applicable law or regulation.", "Any use of the Licensed Application in violation of the foregoing violates this License Agreement and may result in, among other things, termination or suspension of your rights to use the Licensed Application."]}, {"heading": "7. Contribution license", "paragraphs": ["You own your Contributions. By posting them, you give LiteraryWorm the license described in the Terms of Service (\"What you post, and the licence you give us\"): a worldwide, non-exclusive, royalty-free license to store, copy and display your Contributions, only where and to whom you posted them, so we can run the features you use.", "The license ends when you delete the Contribution or your account, except for copies already made by others. Notes, highlights, saved words and private lists are never shown to anyone else.", "We are not liable for any statements or representations in your Contributions. You are solely responsible for your Contributions to the Licensed Application and you expressly agree to exonerate us from any and all responsibility and to refrain from any legal action against us regarding your Contributions.", "We may remove Contributions that break this License Agreement or the Terms of Service, at any time and without notice. We have no obligation to monitor your Contributions."]}, {"heading": "8. Liability", "paragraphs": ["8.1 Licensor's responsibility in the case of violation of obligations and tort shall be limited to intent and gross negligence. Only in case of a breach of essential contractual duties (cardinal obligations), Licensor shall also be liable in case of slight negligence. In any case, liability shall be limited to the foreseeable, contractually typical damages. The limitation mentioned above does not apply to injuries to life, limb, or health.", "8.2 Licensor takes no accountability or responsibility for any damages caused due to a breach of duties according to Section 2 of this License Agreement. To avoid data loss, You can download a copy of your data at any time from Account (Download my data). You are aware that in case of alterations or manipulations of the Licensed Application, You may not have access to the Licensed Application."]}, {"heading": "9. Warranty", "paragraphs": ["9.1 Licensor warrants that the Licensed Application is free of spyware, trojan horses, viruses, or any other malware at the time You use it. Licensor warrants that the Licensed Application works as described in Help.", "9.2 No warranty is provided for the Licensed Application that is not executable on the Device, that has been unauthorizedly modified, handled inappropriately or culpably, combined or installed with inappropriate hardware or software, used with inappropriate accessories, regardless if by Yourself or by third parties, or if there are any other reasons outside of LiteraryWorm's sphere of influence that affect the executability of the Licensed Application.", "9.3 Please notify LiteraryWorm about issues You discover without delay by email at support@literaryworm.com. The defect report will be taken into consideration and further investigated if it has been emailed within a period of seven (7) days after discovery.", "9.4 If we confirm that the Licensed Application is defective, LiteraryWorm reserves a choice to remedy the situation either by means of solving the defect or substitute delivery.", "9.5 Payments for LiteraryWorm memberships are non-refundable, as our Return Policy explains (https://www.literaryworm.com/legal/returns).", "9.6 If the user is an entrepreneur, any claim based on faults expires after a statutory period of limitation amounting to twelve (12) months after the Licensed Application was made available to the user. The statutory periods of limitation given by law apply for users who are consumers."]}, {"heading": "10. Product claims", "paragraphs": ["LiteraryWorm is responsible for addressing any claims of the End-User or any third party relating to the Licensed Application or the End-User's possession and/or use of that Licensed Application, including, but not limited to: (i) product liability claims; (ii) any claim that the Licensed Application fails to conform to any applicable legal or regulatory requirement; and (iii) claims arising under consumer protection, privacy, or similar legislation."]}, {"heading": "11. Legal compliance", "paragraphs": ["You represent and warrant that You are not located in a country that is subject to a US Government embargo, or that has been designated by the US Government as a \"terrorist supporting\" country; and that You are not listed on any US Government list of prohibited or restricted parties."]}, {"heading": "12. Contact information", "paragraphs": ["For general inquiries, complaints, questions or claims concerning the Licensed Application, please email support@literaryworm.com."]}, {"heading": "13. Termination", "paragraphs": ["The license is valid until terminated by LiteraryWorm or by You. You can end it at any time by deleting your account from Account. Your rights under this license will terminate automatically and without notice from LiteraryWorm if You fail to adhere to any term(s) of this license. Upon License termination, You shall stop all use of the Licensed Application, and remove it and any books saved for offline reading from Your Devices."]}, {"heading": "14. Third-party terms of agreements", "paragraphs": ["LiteraryWorm represents and warrants that LiteraryWorm will comply with applicable third-party terms of agreement when using the Licensed Application, including those of the services it relies on: Supabase, Vercel, Mailgun, Anthropic, Google Books, the Internet Archive, LibriVox and Project Gutenberg."]}, {"heading": "15. Intellectual property rights", "paragraphs": ["LiteraryWorm and the End-User acknowledge that, in the event of any third-party claim that the Licensed Application or the End-User's possession and use of that Licensed Application infringes on the third party's intellectual property rights, LiteraryWorm will be solely responsible for the investigation, defense, settlement, and discharge of any such intellectual property infringement claims. Who owns the books and the app is set out in the Terms of Service."]}, {"heading": "16. Applicable law", "paragraphs": ["This License Agreement is governed by the laws of the State of Illinois excluding its conflicts of law rules."]}, {"heading": "17. Miscellaneous", "paragraphs": ["17.1 If any of the terms of this agreement should be or become invalid, the validity of the remaining provisions shall not be affected. Invalid terms will be replaced by valid ones formulated in a way that will achieve the primary purpose.", "17.2 Collateral agreements, changes and amendments are only valid if laid down in writing. The preceding clause can only be waived in writing."]}]$lw$::jsonb),
  ($lw$acceptable-use$lw$, 7, $lw$Acceptable Use Policy$lw$, $lw$This Acceptable Use Policy ("Policy") is part of our Terms of Service ("Legal Terms") and should therefore be read alongside our main Legal Terms: https://www.literaryworm.com/legal/terms. It sets out what you may and may not do on LiteraryWorm, what you may post, how to use our AI features responsibly, and how to report anything that breaks it.$lw$, $lw$[{"heading": "In short", "paragraphs": ["Use LiteraryWorm lawfully and kindly. Don't harass anyone, post anything illegal or hateful, upload books you don't have the right to read, or try to break or overload the Services.", "Use the AI features as reading aids, and don't try to make them produce harmful content. Reading logs and reviews should be honest and your own.", "Report anything that breaks this Policy to report@literaryworm.com. We may remove content or suspend accounts that break it."]}, {"heading": "Agreement to this policy", "paragraphs": ["When you use the AI-powered services provided by LiteraryWorm (\"AI Products\"), you warrant that you will comply with this document, our Legal Terms and all applicable laws and regulations governing AI. Our AI Products are book summaries, content notes, Ask the book, Translate, Who's who, chapter quizzes, Previously… recaps and book clubs' discussion questions. They're written by Claude, an AI model made by Anthropic, and labelled as written by AI.", "Your usage of our AI Products signifies your agreement to engage with our platform in a lawful, ethical, and responsible manner that respects the rights and dignity of all individuals. If you do not agree with these Legal Terms, please refrain from using our Services. Your continued use of our Services implies acceptance of these Legal Terms.", "Please carefully review this Policy which applies to any and all:", "(a) uses of our Services (as defined in \"Legal Terms\");", "(b) forms, materials, consent tools, comments, posts, and all other content available on the Services (\"Content\");", "(c) material which you contribute to the Services, including any upload, post, reading log, rating, book club post, shared list or comment (\"Contribution\");", "(d) responsible implementation and management of AI Products within our Services."]}, {"heading": "Who we are", "paragraphs": ["We are LiteraryWorm (\"Company,\" \"we,\" \"us,\" or \"our\"). We operate the website https://www.literaryworm.com (the \"Site\"), as well as any other related products and services that refer or link to this Policy (collectively, the \"Services\")."]}, {"heading": "Use of the Services", "paragraphs": ["When you use the Services, you warrant that you will comply with this Policy and with all applicable laws.", "You also acknowledge that you may not:", "1. Systematically retrieve data or other content from the Services to create or compile, directly or indirectly, a collection, compilation, database, or directory without written permission from us.", "2. Make any unauthorized use of the Services, including collecting display names and/or email addresses of users by electronic or other means for the purpose of sending unsolicited email, or creating user accounts by automated means or under false pretenses.", "3. Circumvent, disable, or otherwise interfere with security-related features of the Services, including features that prevent or restrict the use or copying of any Content or enforce limitations on the use of the Services and/or the Content contained therein, such as profile PINs, daily reading limits and age ratings.", "4. Engage in unauthorized framing of or linking to the Services.", "5. Trick, defraud, or mislead us and other users, especially in any attempt to learn sensitive account information such as user passwords.", "6. Make improper use of our Services, including our support services, or submit false reports of abuse or misconduct.", "7. Engage in any automated use of the Services, such as using scripts to send comments or messages, or using any data mining, robots, or similar data gathering and extraction tools.", "8. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services.", "9. Attempt to impersonate another user or person or use the display name of another user.", "10. Use any information obtained from the Services in order to harass, abuse, or harm another person.", "11. Use the Services as part of any effort to compete with us or otherwise use the Services and/or the Content for any revenue-generating endeavor or commercial enterprise.", "12. Decipher, decompile, disassemble, or reverse engineer any of the software comprising or in any way making up a part of the Services, except as expressly permitted by applicable law.", "13. Attempt to bypass any measures of the Services designed to prevent or restrict access to the Services, or any portion of the Services.", "14. Harass, annoy, intimidate, or threaten any of our employees or agents engaged in providing any portion of the Services to you.", "15. Delete the copyright or other proprietary rights notice from any Content.", "16. Copy or adapt the Services' software, including but not limited to HTML, JavaScript, or other code.", "17. Upload or transmit (or attempt to upload or to transmit) viruses, Trojan horses, or other material, including excessive use of capital letters and spamming (continuous posting of repetitive text), that interferes with any party's uninterrupted use and enjoyment of the Services or modifies, impairs, disrupts, alters, or interferes with the use, features, functions, operation, or maintenance of the Services.", "18. Upload or transmit (or attempt to upload or to transmit) any material that acts as a passive or active information collection or transmission mechanism, including without limitation, clear graphics interchange formats (\"gifs\"), 1×1 pixels, web bugs, cookies, or other similar devices (sometimes referred to as \"spyware\" or \"passive collection mechanisms\" or \"pcms\").", "19. Except as may be the result of standard search engine or Internet browser usage, or the Services' own Read offline feature, use, launch, develop, or distribute any automated system, including without limitation, any spider, robot, cheat utility, scraper, or offline reader that accesses the Services, or use or launch any unauthorized script or other software.", "20. Disparage, tarnish, or otherwise harm, in our opinion, us and/or the Services.", "21. Use the Services in a manner inconsistent with any applicable laws or regulations.", "22. Use a buying agent or purchasing agent to make purchases on the Services.", "23. Sell or otherwise transfer your account or a profile."]}, {"heading": "Subscriptions", "paragraphs": ["If you subscribe to our Services, you understand, acknowledge, and agree that you may not, except if expressly permitted:", "1. Engage in any use, including modification, copying, redistribution, publication, display, performance, or retransmission, of any portions of any Services, other than as expressly permitted by this Policy, without the prior written consent of LiteraryWorm, which consent LiteraryWorm may grant or refuse in its sole and absolute discretion.", "2. Reconstruct or attempt to discover any source code or algorithms of the Services, or any portion thereof, by any means whatsoever. Being able to see source code we publish doesn't give you a license to use it.", "3. Provide, or otherwise make available, the Services to any third party, other than the people in your household who use the profiles on your account.", "4. Intercept any data not intended for you.", "5. Damage, reveal, or alter any user's data, or any other hardware, software, or information relating to another person or entity."]}, {"heading": "AI Products", "paragraphs": ["When you use the AI Products provided by LiteraryWorm, you warrant that you will not:", "1. Try to make the AI Products produce content that this Policy forbids, or that breaks Anthropic's usage policies.", "2. Deploy AI techniques that utilize subliminal, manipulative, or deceptive methods designed to distort behavior and impair informed decision-making, particularly when such actions cause significant harm to individuals.", "3. Exploit vulnerabilities related to age, disability, or socio-economic circumstances through AI in a way that distorts behavior or decision-making, especially if this results in significant harm to the individual.", "4. Use AI systems for biometric categorization that infer sensitive attributes such as race, political opinions, trade union membership, religious or philosophical beliefs, sex life, or sexual orientation, except in limited cases, such as labeling or filtering lawfully acquired datasets, or specific law enforcement activities.", "5. Implement AI-based social scoring systems that evaluate or classify individuals or groups based on their social behavior or personal traits in a manner that causes harm, discrimination, or unfair treatment.", "6. Assess the risk of an individual committing criminal offenses based solely on profiling, personality traits, or other non-behavioral factors, except in narrowly defined circumstances where legal safeguards are in place.", "7. Compile facial recognition databases through untargeted scraping of facial images from the internet, social media, or CCTV footage, unless it is part of a legally compliant and narrowly defined purpose.", "8. Use AI to infer emotions in sensitive environments such as workplaces, educational institutions, or any other context where such analysis could lead to discrimination, unfair treatment, or privacy violations.", "9. Engage in real-time remote biometric identification in public places for law enforcement purposes, except in specific situations where there are strong legal justifications and oversight mechanisms."]}, {"heading": "Artificial intelligence", "paragraphs": ["We recognize the significant impact AI can have on our users and society, and we are dedicated to ensuring that our AI Products are designed and operated in a manner that aligns with comprehensive ethical standards. We aim to use AI to enhance user experiences while upholding fairness, transparency, and accountability principles.", "That's why everything our AI Products write is labelled as written by AI, and why Ask the book and Who's who are only given the text up to your place in the book, and a quiz only the chapter it's about. A Previously… recap gets only the chapters before yours, and discussion questions only the book up to the end of their chapter. Translate is given only the words you selected, and content notes only the book's details.", "This Policy applies to all AI-powered features, services, and systems in our Services. It governs the development, deployment, and use of AI technologies to protect users' rights and maintain transparency in all AI operations. This Policy applies to all stakeholders, including employees, third-party vendors, and partners who contribute to or interact with our AI Products.", "Enforcement. Any misuse of our AI Products or failure to adhere to the standards outlined in this Policy will result in appropriate actions to ensure the integrity of our platform and the protection of our users. The specific consequences for misuse of AI may vary depending on the nature and severity of the violation and the user's history with our Services.", "Violations may include, but are not limited to:", "1. Engaging the AI Products in ways that violate user privacy, manipulate data, disregard ethical guidelines, or are against AI service providers' terms of use (for our AI Products, Anthropic's).", "2. Deploying AI in a manner that introduces or causes bias, leading to unfair treatment of users or groups.", "3. Improper handling, storage, or use of data by AI Products, leading to breaches of user trust and legal compliance.", "4. Using AI in a way that compromises the privacy and security of our systems, data, or users.", "Depending on the violation, LiteraryWorm may take one or more of the following actions:", "Warnings: The responsible party may receive a formal warning and be required to cease violating practices.", "Temporary Suspension: In cases of repeated or more severe violations, the responsible individual's access to AI Products or certain features of our platform may be temporarily suspended while the issue is investigated.", "Termination of Access: Serious violations, particularly those that result in harm to users or breach privacy or other regulations, may lead to the permanent termination of access to our AI Products and Services.", "Legal Action: In cases where the misuse of AI leads to significant harm, data breaches, or legal violations, we may pursue legal action against the party responsible. This could include reporting the incident to law enforcement or regulatory bodies.", "Public Disclosure: For incidents that impact public trust or involve severe ethical breaches, we reserve the right to publicly disclose the violation and the actions taken in response to maintain transparency and accountability.", "Commitment to Responsible AI. In addition to the consequences outlined above, we are deeply committed to repairing any harm caused by the misuse of AI. This commitment is a testament to our dedication to our users and our responsibility as a company. We will correct biased outcomes and implement additional safeguards to prevent future violations.", "At LiteraryWorm, we are committed to the ongoing refinement and enhancement of our Policy. As technology evolves and regulatory environments shift, we recognize the importance of keeping our policies up to date to ensure that they remain relevant, effective, and aligned with best practices in AI ethics.", "We will regularly review and update our Policy to reflect technological advancements and legal changes in local, national, and international regulations related to AI. Our Policy will be updated as needed to comply with new laws and guidelines, ensuring that our practices remain legally sound and socially responsible."]}, {"heading": "Contributions", "paragraphs": ["In this Policy, the term \"Contributions\" means: any data, information, text, messages or other materials that you post, share, upload, submit, or otherwise provide in any manner on or through the Services, such as reading logs, ratings, book club posts, list names and descriptions, notes and highlights, and books you upload; or any other content, materials, or data you provide to LiteraryWorm or use with the Services.", "Some areas of the Services allow users to upload, transmit, or post Contributions. We may but are under no obligation to review or moderate the Contributions made on the Services, and we expressly exclude our liability for any loss or damage resulting from any of our users' breach of this Policy. Please report any Contribution that you believe breaches this Policy; however, we will determine, in our sole discretion, whether a Contribution is indeed in breach of this Policy.", "You warrant that:", "1. you are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Services, and other users of the Services to use your Contributions in any manner contemplated by the Services and this Policy;", "2. all your Contributions comply with applicable laws and are original and true (if they represent your opinion or facts);", "3. the creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party; and", "4. you have the verifiable consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Services and this Policy.", "You also agree that you will not post, transmit, or upload any (or any part of a) Contribution that:", "1. is in breach of applicable laws, regulation, court order, contractual obligation, this Policy, our Legal Terms, a legal duty, or that promotes or facilitates fraud or illegal activities;", "2. is defamatory, obscene, offensive, hateful, insulting, intimidating, bullying, abusive, or threatening, to any person or group;", "3. is false, inaccurate, or misleading;", "4. includes child sexual abuse material, or violates any applicable law intended to protect minors;", "5. contains any material that solicits personal information from anyone under the age of 18 or exploits people under the age of 18 in a sexual or violent manner;", "6. promotes violence, advocates the violent overthrow of any government, or incites, encourages, or threatens physical harm against another;", "7. is obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, contains sexually explicit material, or is otherwise objectionable (as determined by us);", "8. is discriminatory based on race, sex, religion, nationality, disability, sexual orientation, or age;", "9. bullies, intimidates, humiliates, or insults any person;", "10. promotes, facilitates, or assists anyone in promoting and facilitating acts of terrorism;", "11. infringes, or assists anyone in infringing, a third party's intellectual property rights or publicity or privacy rights;", "12. is deceitful, misrepresents your identity or affiliation with any person and/or misleads anyone as to your relationship with us or implies that the Contribution was made by someone else than you;", "13. contains unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation that has been \"paid for,\" whether with monetary compensation or in kind; or", "14. misrepresents your identity or who the Contribution is from."]}, {"heading": "Reviews and ratings", "paragraphs": ["When your Contribution is a review or rating of a book, such as a rating or a reading log, you also agree that:", "1. you have firsthand experience with the book being reviewed;", "2. your Contribution is true to your experience;", "3. you are not affiliated with competitors if posting negative reviews (or linked in any way to, e.g., by being the author or publisher of, a book if posting positive reviews);", "4. you cannot make or offer any conclusions as to the legality of conduct;", "5. you cannot post any false or misleading statements; and", "6. you do not and will not organize a campaign encouraging others to post reviews, whether positive or negative."]}, {"heading": "Reporting a breach of this policy", "paragraphs": ["We may but are under no obligation to review or moderate the Contributions made on the Services and we expressly exclude our liability for any loss or damage resulting from any of our users' breach of this Policy.", "If you consider that any Service, Content, or Contribution breaches this Policy, please email us at report@literaryworm.com to let us know which Service, Content, or Contribution is in breach of this Policy and why.", "If you consider that any Service, Content, or Contribution infringes any third-party intellectual property rights, please email us at report@literaryworm.com. For a formal notice under the Digital Millennium Copyright Act, follow the steps on our Copyright/DMCA page.", "You can also send detailed feedback on your interactions with our AI Products by emailing report@literaryworm.com. Please include specific details about the AI interaction, such as the book, the context, the nature of the concern, and any relevant screenshots or documentation.", "We will reasonably determine whether a Service, Content, or Contribution breaches this Policy."]}, {"heading": "Consequences of breaching this policy", "paragraphs": ["The consequences for violating our Policy will vary depending on the severity of the breach and the user's history on the Services, by way of example:", "We may, in some cases, give you a warning and/or remove the infringing Contribution, however, if your breach is serious or if you continue to breach our Legal Terms and this Policy, we have the right to suspend or terminate your access to and use of our Services and, if applicable, disable your account. We may also notify law enforcement or issue legal proceedings against you when we believe that there is a genuine risk to an individual or a threat to public safety.", "We exclude our liability for all action we may take in response to any of your breaches of this Policy."]}, {"heading": "Complaints and removal of legitimate content", "paragraphs": ["If you consider that some Content or Contribution has been mistakenly removed or blocked from the Services, please email us at report@literaryworm.com and we will promptly review our decision to remove such Content or Contribution. The Content or Contribution may stay \"down\" whilst we conduct the review process. If it was removed after a copyright notice, you can also send a counter-notice, as our Copyright/DMCA page explains."]}, {"heading": "Disclaimer", "paragraphs": ["LiteraryWorm is under no obligation to monitor users' activities, and we disclaim any responsibility for any user's misuse of the Services. LiteraryWorm has no responsibility for any user or other Content or Contribution created, maintained, stored, transmitted, or accessible on or through the Services, and is not obligated to monitor or exercise any editorial control over such material.", "If LiteraryWorm becomes aware that any such Content or Contribution violates this Policy, LiteraryWorm may, in addition to removing such Content or Contribution and blocking your account, report such breach to the police or appropriate regulatory authority.", "Unless otherwise stated in this Policy, LiteraryWorm disclaims any obligation to any person who has not entered into an agreement with LiteraryWorm for the use of the Services."]}, {"heading": "How can you contact us about this policy?", "paragraphs": ["If you have any further questions or comments or wish to report any problematic Content or Contribution, you may contact us by email: report@literaryworm.com."]}]$lw$::jsonb),
  ($lw$returns$lw$, 8, $lw$Return Policy$lw$, $lw$How billing, cancelling and refunds work for LiteraryWorm memberships and gift memberships, and who to contact with questions.$lw$, $lw$[{"heading": "In short", "paragraphs": ["Memberships renew monthly or yearly until you cancel. Cancel at least 48 hours before your billing date to stop the next charge.", "Payments, including gift memberships, are final and aren't refunded, except where the law where you live says otherwise."]}, {"heading": "How billing works", "paragraphs": ["Your LiteraryWorm membership is billed through Stripe, monthly or yearly, until you cancel. Manage it in Account → Plan and billing, where you can also add or change your payment method.", "On monthly billing you can choose any billing day from the 1st to the 28th, and pause or cancel at any time. A yearly membership can be cancelled at any time, but not paused."]}, {"heading": "Cancelling", "paragraphs": ["Cancel at least 48 hours before your next billing date, and your plan stays active until the end of the period you've paid for, with no further charge.", "If you cancel less than 48 hours before your billing date, that charge still goes through and isn't refunded. A monthly plan then ends at the end of the month it pays for, and a yearly plan at the end of the year it pays for.", "Pausing a monthly membership stops billing until you resume. Your library, profiles and progress stay as they are."]}, {"heading": "Refunds", "paragraphs": ["All sales are final. No refunds are issued for memberships, renewals or time you didn't use.", "This doesn't affect any rights you have under the law where you live."]}, {"heading": "Gift memberships", "paragraphs": ["Gift memberships are paid once and are final too.", "A gift code doesn't expire, works once (from the day the gift starts, if the buyer chose a later day up to a year ahead; if the buyer asked us to email it to the person it's for, we send it once it can be redeemed, and otherwise we remind the buyer three days before a later start), and can't be exchanged for cash or refunded.", "Redeeming one gives its months free on the gift's plan; when they end, the membership ends unless a card has been added, and then it renews monthly until you cancel. Books that come with a gift are added to the library as Want to read when it's redeemed; they're LiteraryWorm titles, so reading and listening to them is part of the membership, not a separate purchase."]}, {"heading": "Questions", "paragraphs": ["If you have any questions about this Return Policy, please contact us at support@literaryworm.com."]}]$lw$::jsonb),
  ($lw$copyright$lw$, 9, $lw$Copyright/DMCA$lw$, $lw$How LiteraryWorm respects copyright, which works are in the public domain, and how a rights holder can report content they believe infringes, under the Digital Millennium Copyright Act (DMCA).$lw$, $lw$[{"heading": "In short", "paragraphs": ["The books you can read and hear in full here are in the public domain in the United States. Other titles show sample pages and details from Google Books.", "If you think something on LiteraryWorm infringes your copyright, send our designated agent a notice with the details listed below, and we'll act on it promptly."]}, {"heading": "Our books and their licences", "paragraphs": ["Public-domain titles use texts from Project Gutenberg and recordings from LibriVox, which LibriVox volunteers release into the public domain. These works are in the public domain in the United States, where LiteraryWorm operates. Our copies leave out Project Gutenberg's own header, footer and licence text.", "Other titles show sample pages written for LiteraryWorm, not the published books, and book details and covers come from Google Books under Google's terms.", "If you believe any of this is wrong, for example that a work isn't in the public domain, tell us using the steps below and we'll look into it promptly."]}, {"heading": "What people post or upload", "paragraphs": ["Reading logs, club posts and shared lists are written by members, who keep their rights in them. Books members upload are private to their own profile and aren't shown to anyone else (a book club started around one shows only its title and author); members must have the right to read them that way (see the Terms of Service).", "Audio clips members share are links to a short stretch of a public-domain LibriVox recording, played from the Internet Archive. Nothing is copied, cut or stored to make them."]}, {"heading": "Reporting content", "paragraphs": ["Users can report user-generated content and copyright infringement, and get information about the Acceptable Use Policy, by emailing report@literaryworm.com."]}, {"heading": "Reporting infringement", "paragraphs": ["If you believe something on LiteraryWorm infringes your copyright, send our designated agent a written notice that includes:", "your physical or electronic signature;", "the work you believe is infringed;", "the material on LiteraryWorm you want removed and where it is (a link helps);", "your name, address, phone number and email;", "a statement that you believe in good faith the use isn't authorised by the copyright owner, its agent or the law;", "and a statement, under penalty of perjury, that the notice is accurate and that you are, or are authorised to act for, the owner.", "Our designated agent's name, postal address, phone number and email, as registered with the U.S. Copyright Office, will be listed here before launch.", "We remove or disable access to the material, tell the member who posted it, and keep a record of the notice."]}, {"heading": "Counter-notices", "paragraphs": ["If your content was removed and you believe that was a mistake or that you had the right to post it, you may send a counter-notice with:", "your signature;", "what was removed and where it was;", "a statement, under penalty of perjury, that you believe in good faith it was removed by mistake or misidentification;", "your name, address and phone number;", "and your consent to the jurisdiction of the federal court for your address (or, outside the United States, any district where LiteraryWorm may be found) and to accept service from the person who sent the notice.", "We forward it to the person who sent the notice and may restore the content in 10 to 14 business days unless they tell us they've filed a court action."]}, {"heading": "Repeat infringers and false claims", "paragraphs": ["We close the accounts of members who repeatedly infringe copyright.", "Knowingly misrepresenting that material infringes, or that it was removed by mistake, can make you liable for damages under the DMCA, so please be sure before you send a notice or counter-notice."]}]$lw$::jsonb),
  ($lw$disclaimer$lw$, 10, $lw$Disclaimer$lw$, $lw$The information provided by LiteraryWorm ("we," "us," or "our") on https://www.literaryworm.com (the "Site") is for general informational purposes only. This page explains what we can and can't promise about it, and about the other websites the Site links to.$lw$, $lw$[{"heading": "Website disclaimer", "paragraphs": ["All information on the Site is provided in good faith, however we make no representation or warranty of any kind, express or implied, regarding the accuracy, adequacy, validity, reliability, availability, or completeness of any information on the Site. This includes book details and covers from Google Books, and everything written by AI, which is labelled as such (see below).", "UNDER NO CIRCUMSTANCE SHALL WE HAVE ANY LIABILITY TO YOU FOR ANY LOSS OR DAMAGE OF ANY KIND INCURRED AS A RESULT OF THE USE OF THE SITE OR RELIANCE ON ANY INFORMATION PROVIDED ON THE SITE. YOUR USE OF THE SITE AND YOUR RELIANCE ON ANY INFORMATION ON THE SITE IS SOLELY AT YOUR OWN RISK."]}, {"heading": "AI-written content disclaimer", "paragraphs": ["Book summaries, content notes, Ask the book answers, translations, Who's who, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude, made by Anthropic) and labelled as written by AI.", "They can be wrong, leave things out, or miss what matters to you. Use them as a reading aid, not as a source of fact.", "Content notes in particular are a guide, not a guarantee. If a topic matters to you or a child at home, check the book itself before choosing it."]}, {"heading": "External links disclaimer", "paragraphs": ["The Site may contain (or you may be sent through the Site) links to other websites or content belonging to or originating from third parties, such as Google Books, the Internet Archive, LibriVox and Project Gutenberg. The Site doesn't show advertising. Such external links are not investigated, monitored, or checked for accuracy, adequacy, validity, reliability, availability, or completeness by us.", "WE DO NOT WARRANT, ENDORSE, GUARANTEE, OR ASSUME RESPONSIBILITY FOR THE ACCURACY OR RELIABILITY OF ANY INFORMATION OFFERED BY THIRD-PARTY WEBSITES LINKED THROUGH THE SITE. WE WILL NOT BE A PARTY TO OR IN ANY WAY BE RESPONSIBLE FOR MONITORING ANY TRANSACTION BETWEEN YOU AND THIRD-PARTY PROVIDERS OF PRODUCTS OR SERVICES."]}, {"heading": "Testimonials disclaimer", "paragraphs": ["The Site doesn't show testimonials at the moment. Reading logs and book club posts are written by members and belong to them; they don't reflect our views and opinions.", "If we add testimonials by users of our products and/or services, they will reflect the real-life experiences and opinions of such users. However, the experiences are personal to those particular users, and may not necessarily be representative of all users of our products and/or services. We do not claim, and you should not assume, that all users will have the same experiences. YOUR INDIVIDUAL RESULTS MAY VARY.", "Testimonials will be reviewed by us before being posted, and will appear on the Site verbatim as given by the users, except for the correction of grammar or typing errors. Some testimonials may be shortened for the sake of brevity where the full testimonial contained extraneous information not relevant to the general public.", "The views and opinions contained in testimonials belong solely to the individual user and do not reflect our views and opinions. Users will not be paid or otherwise compensated for their testimonials, and we'll say so if anyone who gives one is connected to us."]}]$lw$::jsonb),
  ($lw$help$lw$, 11, $lw$Help$lw$, $lw$Answers to common questions about where the books come from, reading and listening, your library, your household, book clubs, your plan and logging in, and how to report a problem.$lw$, $lw$[{"heading": "Where do the books come from?", "paragraphs": ["LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.", "Search finds books by title, or choose Author, Keywords or ISBN. Keywords looks for every word you type anywhere: the title, author, narrator, description, genres or series, so time travel romance finds books about both. Keyword searches have the same filters as a title search.", "Those covers, and the Google Books preview on some book pages, load from books.google.com, so Google sets its own third-party cookies on our website when they load. The Cookie Policy explains them, and blocking third-party cookies in your browser stops them without stopping LiteraryWorm.", "The books you can read and listen to in full are public-domain classics: texts from Project Gutenberg and recordings from LibriVox. Other LiteraryWorm titles show sample pages."]}, {"heading": "Can I read my own books?", "paragraphs": ["Yes. In My Library → Uploads, add EPUBs you own that have no DRM: up to 20 at a time, each up to 50 MB (a profile keeps up to 50). For example, buy a book that the publisher sells DRM-free on Google Play Books, download its EPUB from your Google Play Books library, then upload it to LiteraryWorm. Many publishers and stores sell DRM-free books, and public-domain EPUBs are free from Project Gutenberg and Standard Ebooks.", "Your upload opens in the reader with your place, bookmarks and highlights, and once you've opened it on a device, it keeps working there if your connection drops. Books with DRM can't be uploaded, and removing DRM to upload a book isn't allowed (see the Terms of Service).", "To find one of your uploads, search them in My Library → Uploads by title, author, keywords or ISBN. Keywords also looks through the books' text and shows where the words are, each place a link to that page, on your device. An ISBN is looked up on Google Books and matched to your uploads by title and author."]}, {"heading": "Reading and listening", "paragraphs": ["Open a book from its page with Read or Listen. Your place is shared between the two and across your devices. The mini-player keeps a book playing while you browse, and its controls also work from your lock screen and headphones.", "Choose Language in the accessibility menu (the figure at the top of every page) to see the app in English, Spanish, French, German, Portuguese, Italian or Dutch. Your profile keeps the language you choose, so it opens the same way on your other devices. Book details, What's new and our emails, the policies and Help stay in English.", "To read or listen without a connection, choose Read offline on a public-domain book's page. Each book's page has My journal for private, dated notes only you see; they're exported with your highlights from My Library → Notes. Words you keep from the dictionary come back for review in My words, after 1, 3, 7, 14, 30 and 60 days while you know them. Your reading streak has two rest days a month, used automatically when you miss a day.", "In the reader, Display has OpenDyslexic among the fonts, and Reading guide: a reading ruler on one line, or line focus, which dims everything but three lines. It follows your pointer or a tap; J and K move it down or up a line.", "In the player (and the mini-player's More), Previously… catches you up on a public-domain book from the second chapter on: the story so far and the last chapter, written by AI from the chapters before yours only.", "On an audiobook's page, Read offline has Listen offline on a schedule: this device keeps the chapter you're on and the next 1, 3, 5 or 10 as you listen, on Wi-Fi only if you like, and can remove chapters you've finished. It counts as one of your plan's offline devices.", "In a public-domain book, select some words and choose Translate to read them in English, French, German, Spanish, Italian, Portuguese or Dutch. Only the words you selected are sent. Not on Kids profiles.", "In the player, or the mini-player's More menu, Share a clip makes a link to the last 15, 30 or 60 seconds you heard of a LibriVox recording. Anyone with the link can play that stretch.", "Car mode (in the player and the mini-player's More) fills a phone or tablet with big buttons and keeps the screen on. Voice control there, off until you turn it on, lets you say Play, Pause, Back, Forward, Next chapter, Previous chapter or Exit car mode, with a length if you like (back 30 seconds). Your browser's speech service hears the words. Not on Kids profiles."]}, {"heading": "Your library and reading tools", "paragraphs": ["A book's status can be Want to read, Reading, Finished or Didn't finish, for a book you put down; Didn't finish has its own tab in My Library, and recommendations stop suggesting books like it.", "To read a finished book again, choose Read again on its page. It goes back to Reading from the start, and finishing it again counts as another read, so the page says Your 2nd read or Read twice. Exports for Goodreads and StoryGraph carry the read count and dates.", "Under How did it feel? on a book's page, tag up to three moods, such as funny, hopeful, dark or tense, and a pace. My Library can show the books with one mood, Search lists the moods you've used, and Feel-good picks, a smart list and a row on Discover, gathers the cheerful ones.", "My Library → Smart lists fill themselves: Almost there (past halfway), Waiting for you (started, not opened for 30 days), From authors you follow and Loved it.", "A book's page shows Your time with this book once you've read or listened to it: time spent, the days, your pace through it and your biggest days.", "On a book's page, Reading plan lets you pick a day to finish by: it works out about how many minutes (at your own pace) or pages a day get you there, and says whether you're on track, ahead or behind; Home lists your plans.", "My Library → Notes has Review for highlights: each comes back the day after you make it, then after 1, 3, 7, 14, 30 and 60 days while it still matters, up to 10 a day, and Home says when some are due.", "To take your library elsewhere, choose Export for Goodreads or Export for StoryGraph in My Library: you get a CSV of your books, shelves, star ratings (Love it 5, Like it 4, Not for me 2) and dates, made on your device, to import there."]}, {"heading": "Profiles, Kids and family", "paragraphs": ["Each person at home can have their own profile, with its own library and recommendations. Lock a profile with a PIN, set daily limits for younger readers, and change your plan, password or emails in Account. You can cancel or pause online at any time.", "A Kids profile can ask for a book that isn't on its shelf; a grown-up says yes or no in Account → Family with the account password, and a yes opens that one book for that profile.", "A grown-up can give a Kids profile a bedtime in its profile editor, with the account password: from 7pm to 10pm, and when reading starts again in the morning. Between them, on that device's clock, books and audiobooks show Time for bed and the place is saved; the password allows 15 more minutes.", "Grown-up and teen profiles can put a book on the family shelf from its page; it shows on Home for everyone at home, and Kids profiles see only the books their rating already allows.", "Each LiteraryWorm title's page has Content notes, written by AI: how much violence, death, frightening scenes, language, sexual content, alcohol and drugs, prejudice and self-harm it has, without spoilers. Grown-ups see them under a Kids profile's book requests too. They can miss things, so check anything that matters to you."]}, {"heading": "Book clubs and buddy reads", "paragraphs": ["On a book club's page, Where everyone is shows the chapter each member has reached, for members who turn on Show my place to this club; it's off until you turn it on.", "Under a club's discussion, Shared highlights shows passages members marked in the book; ones from chapters you haven't reached stay hidden until you choose to see them. Share one of yours from the list there, with or without its note, and stop sharing it whenever you like.", "On a public-domain book, Discussion questions under a club's discussion gives five to eight questions about a chapter you've reached, written by AI from the book up to the end of that chapter only. Choose Start a post with this to begin a post with one.", "A club can read a LiteraryWorm title or a book you uploaded, such as a DRM-free EPUB you bought. When you start a club in My Library → Clubs, choose LiteraryWorm books or My uploads under Book from, then find the book by title, author, keywords or ISBN in one box. Keywords also look through descriptions and genres, and an ISBN is looked up on Google Books and matched by title and author.", "Sort the list by title, author, numbers first or series in reading order, and filter it to one series.", "Uploads stay private, so members don't get your file. The club shows the book's title and author, and each member uploads their own copy and chooses it on the club's page (Choose your copy). Posts, where everyone is and shared highlights then follow each member's place in their own copy, so nothing past their chapter is spoiled. An uploaded book has no recording, so there's no listening along.", "To read a book with one friend, choose Read with a friend on its page. A buddy read is a book club for two: send your friend its code, and you get spoiler-safe posts by chapter, meetings and shared highlights.", "A club's owner can ask What to read next on the club's page: offer two to five LiteraryWorm books and members vote. Everyone in the club sees the votes and can change theirs until the owner closes the poll. The book with the most votes wins (a tie goes to the one offered first), and Start a club with it begins a club for it."]}, {"heading": "Your plan, notifications and gifts", "paragraphs": ["Your plan includes some hours of audiobooks a month for the household (Premium has no limit) and a number of devices that can keep books offline. Account → Plan and billing shows how much you've used this month and which devices hold offline places, and lets you free one.", "To hear when a book you set Remind me on comes out, turn on Notifications on this device in Account → Preferences. Once it's on, choose there which notifications you get: books you're waiting for, club meetings, new club posts up to your chapter, an evening streak nudge, and answers to Kids book requests. On iPhone and iPad, add LiteraryWorm to your Home Screen first (Share, then Add to Home Screen) and turn them on in the app.", "When you buy a gift on Gifts, you can add up to 10 LiteraryWorm books to it (find a title, or add one of your lists); they're waiting in the recipient's library when they redeem it.", "A list you share by link is a wishlist too: its page has Give this list as a gift, which opens Gifts with up to 10 of its LiteraryWorm books already picked. Share a list in My Library → Lists to let family and friends know what you'd like."]}, {"heading": "Logging in and keeping your account safe", "paragraphs": ["In Account → Sign-in you can add a passkey to log in with your face, fingerprint, screen lock or a security key instead of your password, and rename or remove passkeys you no longer use."]}, {"heading": "Trouble logging in?", "paragraphs": ["If Log in or Log in with a passkey does nothing, check that your browser isn't letting LiteraryWorm access your local network. LiteraryWorm never needs that permission, and allowing it can stop logging in from working. In Chrome and Edge, select the icon beside the address, choose Site settings, set Local network access to Block, then reload the page and log in again. If your browser asks whether LiteraryWorm can find devices on your local network, choose Block.", "Still stuck? Try a private or incognito window. If that works, a browser extension or something saved in your usual window is in the way. Otherwise, email support@literaryworm.com with your device and browser."]}, {"heading": "Report a problem", "paragraphs": ["Tell us what you were doing, the page you were on, and your device and browser, by email to support@literaryworm.com.", "For accessibility problems, email accessibility@literaryworm.com. To report a post, an upload or a copyright problem, email report@literaryworm.com. For privacy questions, email usprivacy@literaryworm.com."]}]$lw$::jsonb),
  ($lw$status$lw$, 12, $lw$Status$lw$, $lw$All systems are working normally.$lw$, $lw$[{"heading": "Services", "paragraphs": ["Website and app: working normally.", "Accounts, libraries and reading progress: working normally.", "Book search and details (Google Books): working normally.", "Audiobook recordings (Internet Archive): working normally.", "Summaries, Ask the book, Who's who and chapter quizzes (AI): working normally."]}, {"heading": "If something isn't working", "paragraphs": ["Your reading progress is saved on your device first and sent when the connection returns, so you won't lose your place. Books saved for offline keep working without a connection."]}]$lw$::jsonb)
on conflict (slug) do nothing;

