-- =============================================================================
-- 20261101006588_review_fixes.sql
-- =============================================================================
-- Fixes from the Copilot review of the 2026-11-01 release (PR #2).
--
-- 1. Reading plans are saved with an upsert (saveReadingPlan()), and PostgREST's ON CONFLICT DO UPDATE
--    sets every column it was sent, the key columns too, so members need UPDATE on them. RLS (own rows)
--    and the foreign key to reader_profiles (profile_id, account_id) still hold every row to its owner.
-- 2. The 20-plan limit runs in a BEFORE INSERT trigger, which fires for an upsert before its conflict
--    turns it into an update: changing the date of an existing plan at 20 was refused. The count now
--    leaves out the plan being saved.
-- 3. fit_profiles_to_plan() no longer sets profiles aside when a running membership only moves between
--    active and past_due, so a Standard household over the new room of 3 keeps its profiles after a
--    failed payment, as the Terms promise.

grant update (profile_id, user_id, volume_id) on public.reading_plans to authenticated;

create or replace function private.reading_plans_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- The browser sends its own day; allow a day either side of the server's for time zones.
  if new.finish_by < current_date - 1 or new.finish_by > current_date + 731 then
    raise exception 'Choose a day from today to two years ahead' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    -- An upsert of a plan that exists becomes an update, so it doesn't count towards the 20.
    if (select count(*) from public.reading_plans p
        where p.profile_id = new.profile_id and p.user_id = new.user_id and p.volume_id <> new.volume_id) >= 20
       and not exists (select 1 from public.reading_plans p
        where p.profile_id = new.profile_id and p.user_id = new.user_id and p.volume_id = new.volume_id) then
      raise exception 'A profile can have up to 20 reading plans' using errcode = 'check_violation';
    end if;
    if new.started_on not between current_date - 1 and current_date + 1 then
      raise exception 'A plan starts today' using errcode = 'check_violation';
    end if;
    new.created_at := now();
  end if;
  return new;
end;
$$;
revoke execute on function private.reading_plans_guard() from public, anon, authenticated;

create or replace function private.fit_profiles_to_plan()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  allowed smallint;
  in_use  integer;
begin
  if new.status not in ('active', 'past_due') then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtext('reader_profiles:' || new.user_id::text));
  allowed := private.profile_room(new.user_id);
  select count(*) into in_use from public.reader_profiles where account_id = new.user_id and set_aside_at is null;

  -- A running membership that only moves between active and past_due (a failed or recovered
  -- payment) keeps the profiles it has: a household already over its plan's room because the plan
  -- changed (Standard went from 5 to 3, migration 6585) isn't fitted until it changes plan or restarts.
  if in_use > allowed and tg_op = 'UPDATE' and old.status in ('active', 'past_due')
     and old.plan_id is not distinct from new.plan_id and old.switch_to_monthly is not distinct from new.switch_to_monthly then
    return null;
  end if;

  if in_use > allowed then
    update public.reader_profiles r set set_aside_at = now()
    where r.id in (
      select id from public.reader_profiles
      where account_id = new.user_id and set_aside_at is null
        -- Never the oldest: the account keeps at least one profile in use.
        and id <> (select id from public.reader_profiles where account_id = new.user_id order by created_at, id limit 1)
      order by created_at desc, id desc
      limit in_use - allowed
    );
  elsif in_use < allowed then
    update public.reader_profiles r set set_aside_at = null
    where r.id in (
      select id from public.reader_profiles
      where account_id = new.user_id and set_aside_at is not null
      order by set_aside_at, created_at
      limit allowed - in_use
    );
  end if;
  return null;
end;
$$;
revoke execute on function private.fit_profiles_to_plan() from public, anon, authenticated;

-- =============================================================================
-- 20261101006589_club_upload_books.sql
-- =============================================================================
-- Book clubs around a book members uploaded (DRM-free EPUBs, including ones bought elsewhere).
--
-- An upload is a private copy, so it's never shared: the club keeps the book's title and author
-- (book_clubs.book_title, book_author, copied from the owner's upload by a trigger, never sent by the
-- browser), and each member links their own upload of it (club_members.own_copy, which must be one of
-- that member's uploaded_books). Everything that follows a member's place in the club's book uses the
-- member's own copy for an upload club: private.member_volume() gives it, and club_places(), the post
-- digest and push claims and shared highlights now go through it. Catalog clubs work as before.

alter table public.book_clubs
  add column book_title  text check (book_title is null or char_length(btrim(book_title)) between 1 and 200),
  add column book_author text check (book_author is null or char_length(book_author) <= 200);
alter table public.book_clubs
  add constraint book_clubs_upload_named check ((volume_id ~ '^u-[0-9a-f]{32}$') = (book_title is not null));

alter table public.club_members
  add column own_copy text references public.uploaded_books (id) on delete set null;
grant update (own_copy) on public.club_members to authenticated;

-- The volume a member reads for a club: the club's catalog title, or for an uploaded book the
-- member's own copy (null until they link one).
create or replace function private.member_volume(p_volume text, p_own_copy text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when p_volume ~ '^u-[0-9a-f]{32}$' then p_own_copy else p_volume end;
$$;
revoke execute on function private.member_volume(text, text) from public, anon, authenticated;

-- A new club on an upload: the upload must be the owner's; its title and author are copied.
create or replace function private.club_book_fill()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_upload public.uploaded_books%rowtype;
begin
  if new.volume_id ~ '^u-[0-9a-f]{32}$' then
    select * into v_upload from public.uploaded_books u where u.id = new.volume_id and u.user_id = new.owner_id;
    if not found then
      raise exception 'Choose one of your own uploaded books' using errcode = 'check_violation';
    end if;
    new.book_title := v_upload.title;
    new.book_author := nullif(v_upload.author, '');
  else
    new.book_title := null;
    new.book_author := null;
  end if;
  return new;
end;
$$;
revoke execute on function private.club_book_fill() from public, anon, authenticated;

create trigger book_clubs_book_fill
  before insert on public.book_clubs
  for each row execute function private.club_book_fill();

-- A member's own copy: only for a club on an uploaded book, and only one of the member's own uploads.
create or replace function private.club_copy_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.own_copy is not null then
    if not exists (select 1 from public.book_clubs c where c.id = new.club_id and c.volume_id ~ '^u-[0-9a-f]{32}$') then
      raise exception 'Only a club reading an uploaded book uses your own copy' using errcode = 'check_violation';
    end if;
    if not exists (select 1 from public.uploaded_books u where u.id = new.own_copy and u.user_id = new.user_id) then
      raise exception 'Choose one of your own uploaded books' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;
revoke execute on function private.club_copy_check() from public, anon, authenticated;

create trigger club_members_copy_check
  before insert or update of own_copy on public.club_members
  for each row execute function private.club_copy_check();

create or replace function private.book_club_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_table_name = 'book_clubs' then
    if (select count(*) from public.book_clubs where owner_id = new.owner_id) > 20 then
      raise exception 'An account can run up to 20 clubs' using errcode = 'check_violation';
    end if;
    -- An uploaded book's club starts with the owner's own copy linked.
    insert into public.club_members (club_id, user_id, own_copy)
    values (new.id, new.owner_id, case when new.volume_id ~ '^u-[0-9a-f]{32}$' then new.volume_id end);
  elsif (select count(*) from public.club_posts
         where user_id = new.user_id and created_at > now() - interval '1 hour') > 60 then
    raise exception 'Too many posts. Wait a little and try again.' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

create or replace function public.club_places(p_club uuid)
returns table (user_id uuid, display_name text, chapter_index smallint, fraction numeric, finished boolean, updated_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'Log in to do that.' using errcode = '42501';
  end if;
  if not public.second_step_done() then
    raise exception 'Enter the code from your authenticator app first.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.club_members m where m.club_id = p_club and m.user_id = v_user) then
    raise exception 'Only the club''s members can see where everyone is.' using errcode = '42501';
  end if;
  return query
  select m.user_id, p.display_name, rp.chapter_index, rp.position, rp.finished, rp.updated_at
  from public.club_members m
  join public.book_clubs c on c.id = m.club_id
  join public.reading_progress rp on rp.user_id = m.user_id and rp.volume_id = private.member_volume(c.volume_id, m.own_copy)
  left join public.profiles p on p.id = m.user_id
  where m.club_id = p_club and m.share_place
  order by rp.position desc, p.display_name;
end;
$$;

create or replace function public.claim_club_post_digests(max_count integer default 200)
returns table (
  user_id uuid, email text, member_name text,
  club_id uuid, club_name text, volume_id text,
  chapter_index smallint, posts bigint, authors text[],
  was_through timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_until timestamptz := now() - interval '1 minute';
begin
  return query
  with fresh as (
    select m.user_id as reader, p.club_id as club, p.chapter_index as chapter, p.user_id as author
    from public.club_members m
    join public.account_private a on a.user_id = m.user_id and a.club_post_emails
    join public.book_clubs b on b.id = m.club_id
    join public.club_posts p on p.club_id = m.club_id
    left join public.reading_progress r on r.user_id = m.user_id and r.volume_id = private.member_volume(b.volume_id, m.own_copy)
    where m.notify
      and p.user_id <> m.user_id
      and p.created_at > greatest(m.last_read_at, coalesce(a.club_posts_emailed_through, '-infinity'::timestamptz), now() - interval '7 days')
      and p.created_at <= v_until
      and (coalesce(r.finished, false) or p.chapter_index <= coalesce(r.chapter_index, 0))
  ), due as (
    select a.user_id as reader, a.club_posts_emailed_through as was
    from public.account_private a
    join auth.users u on u.id = a.user_id and u.email is not null and u.email_confirmed_at is not null
    where a.user_id in (select f.reader from fresh f)
    order by a.user_id
    limit least(greatest(coalesce(max_count, 200), 1), 500)
    for update of a skip locked
  ), claimed as (
    update public.account_private a set club_posts_emailed_through = v_until
    from due where a.user_id = due.reader
    returning a.user_id as reader, due.was
  )
  select c.reader, u.email::text, me.display_name,
         f.club, b.name, b.volume_id,
         f.chapter, count(*), array_agg(distinct coalesce(w.display_name, 'A member') order by coalesce(w.display_name, 'A member')),
         c.was
  from claimed c
  join fresh f on f.reader = c.reader
  join auth.users u on u.id = c.reader
  join public.book_clubs b on b.id = f.club
  left join public.profiles me on me.id = c.reader
  left join public.profiles w on w.id = f.author
  group by c.reader, u.email, me.display_name, f.club, b.name, b.volume_id, f.chapter, c.was
  order by c.reader, b.name, f.chapter;
end;
$$;

create or replace function public.claim_club_post_pushes(max_count integer default 200)
returns table (user_id uuid, club_id uuid, club_name text, last_chapter smallint, posts bigint, authors text[])
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_until timestamptz := now() - interval '1 minute';
begin
  return query
  with fresh as (
    select m.user_id as reader, p.club_id as club, p.chapter_index as chapter, p.user_id as author
    from public.club_members m
    join public.account_private a on a.user_id = m.user_id and 'club_posts' = any (a.push_kinds)
    join public.book_clubs b on b.id = m.club_id
    join public.club_posts p on p.club_id = m.club_id
    left join public.reading_progress r on r.user_id = m.user_id and r.volume_id = private.member_volume(b.volume_id, m.own_copy)
    where m.notify
      and p.user_id <> m.user_id
      and p.created_at > greatest(m.last_read_at, a.club_posts_pushed_through, now() - interval '1 day')
      and p.created_at <= v_until
      and (coalesce(r.finished, false) or p.chapter_index <= coalesce(r.chapter_index, 0))
      and exists (select 1 from public.push_subscriptions s where s.user_id = m.user_id)
  ), due as (
    select a.user_id as reader
    from public.account_private a
    where a.user_id in (select f.reader from fresh f)
    order by a.user_id
    limit least(greatest(coalesce(max_count, 200), 1), 500)
    for update of a skip locked
  ), claimed as (
    update public.account_private a set club_posts_pushed_through = v_until
    from due where a.user_id = due.reader
    returning a.user_id as reader
  )
  select c.reader, f.club, b.name, max(f.chapter), count(*),
         array_agg(distinct coalesce(w.display_name, 'A member') order by coalesce(w.display_name, 'A member'))
  from claimed c
  join fresh f on f.reader = c.reader
  join public.book_clubs b on b.id = f.club
  left join public.profiles w on w.id = f.author
  group by c.reader, f.club, b.name
  order by c.reader, b.name;
end;
$$;

create or replace function private.club_highlights_fill()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_highlight public.highlights%rowtype;
begin
  select * into v_highlight from public.highlights h where h.id = new.highlight_id and h.user_id = new.user_id;
  if not found then
    raise exception 'Share one of your own highlights' using errcode = 'check_violation';
  end if;
  if not exists (
    select 1 from public.book_clubs c
    join public.club_members m on m.club_id = c.id and m.user_id = new.user_id
    where c.id = new.club_id and private.member_volume(c.volume_id, m.own_copy) = v_highlight.volume_id
  ) then
    raise exception 'Share a highlight from the club''s book' using errcode = 'check_violation';
  end if;
  if (select count(*) from public.club_highlights x where x.club_id = new.club_id and x.user_id = new.user_id) >= 300 then
    raise exception 'You can share up to 300 highlights in a club' using errcode = 'check_violation';
  end if;
  new.chapter_index := v_highlight.chapter_index;
  new.quote := v_highlight.quote;
  new.color := v_highlight.color;
  new.note := case when new.share_note then v_highlight.note else null end;
  new.created_at := now();
  return new;
end;
$$;

-- =============================================================================
-- 20261101006590_index_club_members_own_copy.sql
-- =============================================================================
-- The foreign key club_members.own_copy → uploaded_books (migration 6589). One statement: CONCURRENTLY can't run in a transaction.
create index concurrently if not exists club_members_own_copy_idx on public.club_members (own_copy);

-- =============================================================================
-- 20261101006591_club_upload_books_legal.sql
-- =============================================================================
-- Book clubs on uploaded books (migration 6589): the Privacy Policy, Copyright and Terms say a club
-- started around an upload shows its members only the title and author, each member reads their own
-- copy and nobody's upload is shared; Help gets "Book clubs on your own books". src/data/legalPages.json
-- has the same. Each is changed once; a page an editor has reworded is left as it is.

update public.legal_pages
set sections = replace(sections::text, $lw$and books you upload (private to the profile that added them; we keep their text only).$lw$, $lw$and books you upload (private to the profile that added them; we keep their text only; if you start a book club around one, the club's members see its title and author, never its text).$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$and books you upload (private to the profile that added them; we keep their text only).$lw$) > 0;

update public.legal_pages
set sections = replace(sections::text, $lw$Books members upload are private to their own profile and aren't shown to anyone else;$lw$, $lw$Books members upload are private to their own profile and aren't shown to anyone else (a book club started around one shows only its title and author);$lw$)::jsonb, updated_at = now()
where slug = $lw$copyright$lw$ and strpos(sections::text, $lw$Books members upload are private to their own profile and aren't shown to anyone else;$lw$) > 0;

update public.legal_pages
set sections = replace(sections::text, $lw$Your uploads stay private to the profile that added them. We store their text only to show it to you, claim no rights in them, and delete them when you do or when you delete the profile or account."$lw$, $lw$Your uploads stay private to the profile that added them. We store their text only to show it to you, claim no rights in them, and delete them when you do or when you delete the profile or account.", "You can start a book club around a book you uploaded. Its members see only the title and author; each of them reads their own copy, which they must also have the right to read, and nobody's upload is shared with anyone else."$lw$)::jsonb, updated_at = now()
where slug = $lw$terms$lw$
  and strpos(sections::text, $lw$Your uploads stay private to the profile that added them. We store their text only to show it to you, claim no rights in them, and delete them when you do or when you delete the profile or account.$lw$) > 0
  and strpos(sections::text, $lw$start a book club around a book you uploaded$lw$) = 0;

-- Before the last section (Report a problem).
update public.legal_pages
set sections = jsonb_insert(sections, '{-1}', $lw${"heading": "Book clubs on your own books", "paragraphs": ["A club can read a LiteraryWorm title or a book you uploaded, such as a DRM-free EPUB you bought. When you start a club in My Library → Clubs, choose My uploads under Book from and search by title or author to find it.", "Uploads stay private, so members don't get your file. The club shows the book's title and author, and each member uploads their own copy and chooses it on the club's page (Choose your copy). Posts, where everyone is and shared highlights then follow each member's place in their own copy, so nothing past their chapter is spoiled. An uploaded book has no recording, so there's no listening along."]}$lw$::jsonb), updated_at = now()
where slug = $lw$help$lw$
  and jsonb_typeof(sections) = 'array'
  and jsonb_array_length(sections) > 0
  and strpos(sections::text, $lw$Book clubs on your own books$lw$) = 0;

