insert into public.changelog_entries (released_on, version, kind, title, body, major)
select $lw$2026-11-01$lw$::date, $lw$2026.11$lw$, $lw$update$lw$, $lw$A clearer Children's Privacy Notice$lw$, $lw$We rewrote the Children's Privacy Notice for parents and guardians. It now starts with a short summary, groups what a Kids profile keeps, lists what we never collect, explains the AI features a Kids profile can use (only the book's own text reaches Anthropic), says who can see a child's reading and for how long it's kept, and how to withdraw consent or ask us a question.$lw$, false
where not exists (select 1 from public.changelog_entries c where c.title = $lw$A clearer Children's Privacy Notice$lw$ and c.version = $lw$2026.11$lw$);

-- =============================================================================
-- 20261101006604_book_moods.sql
-- =============================================================================
-- Moods and pace: how a book felt to one profile (StoryGraph's 14 moods and three paces, so the
-- export lines up; src/lib/moods.ts has the same lists). Per profile, like book_ratings: every row
-- carries the account for RLS and a composite foreign key to reader_profiles(id, account_id), and
-- the primary key starts with (profile_id, user_id), so it also indexes that foreign key. Up to
-- three moods a book; a row with nothing tagged is deleted by the browser instead of kept.

create table public.book_moods (
  profile_id uuid not null,
  user_id    uuid not null,
  volume_id  text not null check (volume_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  moods      text[] not null default '{}'
    check (cardinality(moods) <= 3
       and moods <@ array['adventurous', 'challenging', 'dark', 'emotional', 'funny', 'hopeful', 'informative',
                          'inspiring', 'lighthearted', 'mysterious', 'reflective', 'relaxing', 'sad', 'tense']::text[]),
  pace       text check (pace in ('slow', 'medium', 'fast')),
  updated_at timestamptz not null default now(),
  primary key (profile_id, user_id, volume_id),
  foreign key (profile_id, user_id) references public.reader_profiles (id, account_id) on delete cascade,
  check (cardinality(moods) > 0 or pace is not null)
);

create trigger book_moods_set_updated_at
  before update on public.book_moods
  for each row execute function public.set_updated_at();

alter table public.book_moods enable row level security;

create policy "Readers see their own moods" on public.book_moods for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Readers tag moods as themselves" on public.book_moods for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Readers change their own moods" on public.book_moods for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Readers clear their own moods" on public.book_moods for delete to authenticated
  using (user_id = (select auth.uid()));
create policy "Two-step sign-in when turned on" on public.book_moods as restrictive for all to authenticated
  using ((select public.second_step_done())) with check ((select public.second_step_done()));

revoke all on public.book_moods from anon, authenticated;
grant select, delete on public.book_moods to authenticated;
grant insert (profile_id, user_id, volume_id, moods, pace) on public.book_moods to authenticated;
grant update (moods, pace) on public.book_moods to authenticated;

-- =============================================================================
-- 20261101006605_whats_new_moods.sql
-- =============================================================================
-- What's new: moods and pace (src/data/changelog.json has the same).
-- Data only; skipped if an editor added it already.

insert into public.changelog_entries (released_on, version, kind, title, body, major)
select $lw$2026-11-01$lw$::date, $lw$2026.11$lw$, $lw$feature$lw$, $lw$Moods and pace$lw$, $lw$Tag how a book felt on its page, under How did it feel?: up to three moods, such as funny, hopeful, dark or tense, and a pace (slow, medium or fast). Each profile keeps its own. My Library can show only the books with one mood, the Feel-good picks smart list gathers the cheerful ones, and the StoryGraph export carries your moods and pace.$lw$, true
where not exists (select 1 from public.changelog_entries c where c.title = $lw$Moods and pace$lw$ and c.version = $lw$2026.11$lw$);

-- =============================================================================
-- 20261101006606_kids_bedtime.sql
-- =============================================================================
-- Bedtime for Kids profiles: a grown-up picks a bedtime and a wake-up time in the profile editor;
-- between them, on the device's clock, the reader and the player show Time for bed. Like the
-- daily limit it's the account holder's call, so only the manage-profile function (set_bedtime,
-- with the account password, service role) writes it: the browser is granted select only.
-- Both or neither; moving a profile off Kids clears it (src/lib/bedtime.ts has the same choices).

alter table public.reader_profiles
  add column bedtime time check (bedtime in ('19:00', '19:30', '20:00', '20:30', '21:00', '21:30', '22:00')),
  add column wake_time time check (wake_time in ('06:00', '06:30', '07:00', '07:30', '08:00')),
  add constraint reader_profiles_bedtime_pair check ((bedtime is null) = (wake_time is null));
grant select (bedtime, wake_time) on public.reader_profiles to authenticated;

create or replace function private.clear_bedtime_off_kids()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.age_rating <> 'kids' then
    new.bedtime := null;
    new.wake_time := null;
  end if;
  return new;
end;
$$;
revoke execute on function private.clear_bedtime_off_kids() from public, anon, authenticated;

create trigger reader_profiles_clear_bedtime
  before insert or update of age_rating, bedtime, wake_time on public.reader_profiles
  for each row execute function private.clear_bedtime_off_kids();

